export enum IssueCategory {
  POTHOLE = 'Pothole',
  STREET_LIGHT = 'Street Light',
  GARBAGE = 'Garbage',
  WATER = 'Water Leakage',
  SANITATION = 'Sanitation',
  DRAINAGE = 'Drainage',
  OTHERS = 'Others'
}

export enum IssueStatus {
  SUBMITTED = 'Submitted',
  IN_PROGRESS = 'In Progress',
  RESOLVED = 'Resolved',
  REJECTED = 'Rejected'
}

export interface Location {
  latitude: number;
  longitude: number;
  address?: string;
}

export interface Grievance {
  id: string;
  title: string;
  category: IssueCategory;
  description: string;
  image?: string;
  location: Location;
  status: IssueStatus;
  createdAt: string;
  updatedAt: string;
  aiCategorized: boolean;
}

export interface ContactForm {
  name: string;
  email: string;
  subject: string;
  message: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { IssueCategory } from "../types";

const API_KEY = process.env.API_KEY || "";

export const aiService = {
  async categorizeIssue(description: string): Promise<{ category: IssueCategory; reasoning: string }> {
    try {
      const ai = new GoogleGenAI({ apiKey: API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Categorize this civic grievance description into one of these categories: ${Object.values(IssueCategory).join(", ")}. 
        Description: "${description}"`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              category: {
                type: Type.STRING,
                description: "The most appropriate category from the provided list.",
              },
              reasoning: {
                type: Type.STRING,
                description: "Brief reasoning for the choice.",
              },
            },
            required: ["category", "reasoning"],
          },
        },
      });

      const result = JSON.parse(response.text);
      // Validate category
      const validatedCategory = Object.values(IssueCategory).includes(result.category as IssueCategory) 
        ? (result.category as IssueCategory) 
        : IssueCategory.OTHERS;

      return {
        category: validatedCategory,
        reasoning: result.reasoning
      };
    } catch (error) {
      console.error("AI Categorization failed:", error);
      return { category: IssueCategory.OTHERS, reasoning: "Error during AI analysis." };
    }
  }
};

