import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Camera, 
  MapPin, 
  Send, 
  Loader2, 
  AlertCircle,
  CheckCircle,
  Sparkles
} from 'lucide-react';
import { IssueCategory, IssueStatus, Grievance, Location } from '../types';
import { aiService } from '../services/geminiService';

interface ReportPageProps {
  onAdd: (g: Grievance) => void;
}

const ReportPage: React.FC<ReportPageProps> = ({ onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [locationLoading, setLocationLoading] = useState(false);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    description: '',
    image: '',
    location: null as Location | null
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, reasoning: string } | null>(null);

  const handleLocation = () => {
    setLocationLoading(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setForm(prev => ({
            ...prev,
            location: {
              latitude: position.coords.latitude,
              longitude: position.coords.longitude,
              address: "Coordinates captured successfully"
            }
          }));
          setLocationLoading(false);
        },
        (error) => {
          console.error(error);
          alert("Could not get location. Please allow location access.");
          setLocationLoading(false);
        }
      );
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, image: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDescriptionBlur = async () => {
    if (form.description.length < 10) return;

    setAnalyzing(true);
    const result = await aiService.categorizeIssue(form.description);
    setForm(prev => ({ ...prev, category: result.category }));
    setAiInsight({ category: result.category, reasoning: result.reasoning });
    setAnalyzing(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.title || !form.description || !form.location) {
      alert("Please fill in all required fields and capture your location.");
      return;
    }

    setLoading(true);

    const newGrievance: Grievance = {
      id: `GRV-${Math.floor(1000 + Math.random() * 9000)}`,
      title: form.title,
      category: form.category,
      description: form.description,
      image: form.image,
      location: form.location,
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight
    };

    setTimeout(() => {
      onAdd(newGrievance);
      setLoading(false);
      setSuccess(true);
      setTimeout(() => navigate('/track'), 2000);
    }, 1500);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-20 animate-fadeIn">
        <div className="bg-green-50 text-green-600 p-8 rounded-full mb-6">
          <CheckCircle size={80} />
        </div>
        <h2 className="text-3xl font-bold text-gray-900 mb-2">Issue Reported!</h2>
        <p className="text-gray-600 mb-8">Redirecting you to tracking page...</p>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 animate-fadeIn">
      <div className="mb-10 text-center">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">Report a Civic Issue</h1>
        <p className="text-gray-600">Fill out the form below to alert the authorities. AI will help categorize your issue.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2">
          <form onSubmit={handleSubmit} className="bg-white p-8 rounded-2xl shadow-sm border border-gray-200 space-y-6">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Issue Title *</label>
              <input 
                type="text" 
                required
                placeholder="Brief summary (e.g., Street light out near library)"
                className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none"
                value={form.title}
                onChange={e => setForm({...form, title: e.target.value})}
              />
            </div>

            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Category *</label>
              <div className="relative">
                <select 
                  className="w-full px-4 py-3 rounded-xl border border-gray-300 appearance-none bg-white focus:ring-2 focus:ring-blue-500 transition-all outline-none"
                  value={form.category}
                  onChange={e => setForm({...form, category: e.target.value as IssueCategory})}
                >
                  {Object.values(IssueCategory).map(cat => (
                    <option key={cat} value={cat}>{cat}</option>
                  ))}
                </select>
                {analyzing && (
                  <div className="absolute right-10 top-3 flex items-center gap-2 text-blue-600">
                    <Sparkles size={16} className="animate-pulse" />
                    <span className="text-xs font-bold uppercase tracking-wider">Analyzing...</span>
                  </div>
                )}
              </div>
              {aiInsight && (
                <div className="mt-2 text-xs flex items-start gap-2 text-blue-700 bg-blue-50 p-3 rounded-lg border border-blue-100">
                  <Sparkles size={14} className="mt-0.5 flex-shrink-0" />
                  <div>
                    <span className="font-bold">AI Suggestion:</span> {aiInsight.reasoning}
                  </div>
                </div>
              )}
            </div>

            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Description *</label>
              <textarea 
                required
                rows={4}
                placeholder="Provide details about the issue. More details help our AI categorize it accurately."
                className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-blue-500 transition-all outline-none"
                value={form.description}
                onBlur={handleDescriptionBlur}
                onChange={e => setForm({...form, description: e.target.value})}
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Photo Upload</label>
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="border-2 border-dashed border-gray-300 rounded-2xl p-6 flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all"
                >
                  {form.image ? (
                    <img src={form.image} className="w-full h-32 object-cover rounded-lg" alt="Preview" />
                  ) : (
                    <>
                      <Camera size={32} className="text-gray-400 mb-2" />
                      <span className="text-sm text-gray-500 font-medium">Click to upload photo</span>
                    </>
                  )}
                </div>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  onChange={handleFileChange} 
                  accept="image/*" 
                  className="hidden" 
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Your Location *</label>
                <div className="space-y-4">
                  <button 
                    type="button"
                    onClick={handleLocation}
                    disabled={locationLoading}
                    className="w-full px-4 py-4 rounded-xl bg-gray-100 text-gray-700 font-bold flex items-center justify-center gap-2 hover:bg-gray-200 transition-colors disabled:opacity-50"
                  >
                    {locationLoading ? <Loader2 size={18} className="animate-spin" /> : <MapPin size={18} />}
                    {form.location ? 'Location Captured' : 'Get Current Location'}
                  </button>
                  {form.location && (
                    <div className="text-xs text-green-700 bg-green-50 p-3 rounded-lg flex items-center gap-2">
                      <CheckCircle size={14} />
                      Latitude: {form.location.latitude.toFixed(4)}, Longitude: {form.location.longitude.toFixed(4)}
                    </div>
                  )}
                </div>
              </div>
            </div>

            <button 
              type="submit"
              disabled={loading}
              className="w-full bg-blue-700 text-white py-4 rounded-xl font-bold text-lg hover:bg-blue-800 shadow-lg flex items-center justify-center gap-2 transition-all transform hover:scale-[1.01] active:scale-[0.99] disabled:opacity-50"
            >
              {loading ? <Loader2 size={24} className="animate-spin" /> : <Send size={24} />}
              Submit Report
            </button>
          </form>
        </div>

        <div className="space-y-6">
          <div className="bg-amber-50 p-6 rounded-2xl border border-amber-100">
            <h3 className="flex items-center gap-2 text-amber-800 font-bold mb-4">
              <AlertCircle size={20} />
              Reporting Tips
            </h3>
            <ul className="space-y-4 text-sm text-amber-700">
              <li className="flex gap-2">
                <span className="font-bold">•</span>
                Be specific about the location if the GPS isn't exact.
              </li>
              <li className="flex gap-2">
                <span className="font-bold">•</span>
                Take clear photos during daylight if possible.
              </li>
              <li className="flex gap-2">
                <span className="font-bold">•</span>
                Describe if the issue is a safety hazard.
              </li>
            </ul>
          </div>

          <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
            <h3 className="font-bold text-gray-800 mb-4">AI Categorization</h3>
            <p className="text-sm text-gray-600 mb-4">
              Our platform uses Gemini AI to process your description and automatically route it to the right department. This ensures faster response times.
            </p>
            <div className="flex items-center gap-3 text-blue-600 font-bold text-sm">
              <Sparkles size={18} />
              Powered by GenAI
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ReportPage;

import React, { useState } from 'react';
import { 
  Search, 
  Clock, 
  MapPin, 
  Tag, 
  Calendar,
  AlertCircle,
  CheckCircle2,
  ChevronRight,
  History
} from 'lucide-react';
import { Grievance, IssueStatus } from '../types';

interface TrackPageProps {
  grievances: Grievance[];
}

const TrackPage: React.FC<TrackPageProps> = ({ grievances }) => {
  const [searchId, setSearchId] = useState('');
  const [selectedIssue, setSelectedIssue] = useState<Grievance | null>(null);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    const found = grievances.find(g => g.id.toLowerCase() === searchId.toLowerCase());
    if (found) {
      setSelectedIssue(found);
    } else {
      alert("No grievance found with this ID.");
    }
  };

  const statusConfig = {
    [IssueStatus.SUBMITTED]: { color: 'bg-blue-100 text-blue-700', icon: <Clock size={16} /> },
    [IssueStatus.IN_PROGRESS]: { color: 'bg-orange-100 text-orange-700', icon: <History size={16} /> },
    [IssueStatus.RESOLVED]: { color: 'bg-green-100 text-green-700', icon: <CheckCircle2 size={16} /> },
    [IssueStatus.REJECTED]: { color: 'bg-red-100 text-red-700', icon: <AlertCircle size={16} /> }
  };

  const getTimeline = (status: IssueStatus) => {
    const steps = [
      { label: 'Submitted', status: IssueStatus.SUBMITTED },
      { label: 'Under Review', status: IssueStatus.IN_PROGRESS },
      { label: 'Assigned', status: IssueStatus.IN_PROGRESS },
      { label: 'Resolved', status: IssueStatus.RESOLVED }
    ];

    const currentIdx = steps.findIndex(s => s.status === status);
    // Rough logic for UI representation
    const activeIdx = status === IssueStatus.SUBMITTED ? 0 : 
                      status === IssueStatus.IN_PROGRESS ? 2 :
                      status === IssueStatus.RESOLVED ? 3 : -1;

    return steps.map((step, idx) => ({
      ...step,
      completed: idx <= activeIdx
    }));
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 animate-fadeIn">
      <div className="mb-10 text-center">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">Track Your Complaint</h1>
        <p className="text-gray-600">Enter your Complaint ID to see real-time progress updates.</p>
      </div>

      <form onSubmit={handleSearch} className="mb-12">
        <div className="relative max-w-lg mx-auto">
          <input 
            type="text" 
            placeholder="e.g. GRV-1001"
            className="w-full pl-12 pr-4 py-4 rounded-2xl border-2 border-blue-100 focus:border-blue-500 transition-all outline-none text-lg font-bold"
            value={searchId}
            onChange={e => setSearchId(e.target.value)}
          />
          <Search className="absolute left-4 top-5 text-gray-400" size={24} />
