}

const ReportPage: React.FC<ReportPageProps> = ({ onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [locationLoading, setLocationLoading] = useState(false);
  const [showValidation, setShowValidation] = useState(false);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    description: '',
    image: '',
    location: null as Location | null
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, reasoning: string } | null>(null);

  const handleLocation = () => {
    setLocationLoading(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setForm(prev => ({
            ...prev,
            location: {
              latitude: position.coords.latitude,
              longitude: position.coords.longitude,
              address: "Browser GPS Location"
            }
          }));
          setLocationLoading(false);
        },
        (error) => {
          console.error(error);
          // Fallback for demo purposes if user denies permission
          setForm(prev => ({
            ...prev,
            location: {
              latitude: 40.7128,
              longitude: -74.0060,
              address: "City Center (Fallback Location)"
            }
          }));
          setLocationLoading(false);
        },
        { timeout: 10000 }
      );
    } else {
      alert("Geolocation is not supported by this browser.");
      setLocationLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, image: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDescriptionBlur = async () => {
    if (form.description.length < 15) return;

    setAnalyzing(true);
    const result = await aiService.categorizeIssue(form.description);
    setForm(prev => ({ ...prev, category: result.category }));
    setAiInsight({ category: result.category, reasoning: result.reasoning });
    setAnalyzing(false);
  };

  const isFormValid = form.title.length > 3 && form.description.length > 10 && form.location !== null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setShowValidation(true);

    if (!isFormValid) {
      return;
    }

    setLoading(true);

    const newGrievance: Grievance = {
      id: `GRV-${Math.floor(1000 + Math.random() * 8999)}`,
      title: form.title,
      category: form.category,
      description: form.description,
      image: form.image,
      location: form.location!,
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight
    };

    // Simulate network delay
    setTimeout(() => {
      onAdd(newGrievance);
      setLoading(false);
      setSuccess(true);
      // Redirect to track page with the new ID
      setTimeout(() => navigate('/track'), 1500);
    }, 1200);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-32 animate-fadeIn bg-white min-h-[60vh]">
        <div className="bg-green-100 text-green-600 p-8 rounded-full mb-6 animate-bounce">
          <CheckCircle size={80} />
        </div>
        <h2 className="text-3xl font-bold text-gray-900 mb-2">Issue Reported Successfully!</h2>
        <p className="text-gray-500 mb-8">Authorities have been notified. Redirecting to your tracker...</p>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 animate-fadeIn">
      <div className="mb-10 text-center">
        <h1 className="text-3xl md:text-4xl font-extrabold text-gray-900 mb-3 tracking-tight">Report a Civic Issue</h1>
        <p className="text-gray-600 max-w-xl mx-auto">Your feedback helps us build a better city. Fill out the details below and our AI will route it to the right department.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2">
          <form onSubmit={handleSubmit} className="bg-white p-8 rounded-3xl shadow-xl shadow-blue-900/5 border border-gray-100 space-y-8">
            {/* Title Field */}
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-2">Issue Title *</label>
              <input 
                type="text" 
                required
                placeholder="e.g., Massive pothole at 5th and Main"
                className={`w-full px-5 py-4 rounded-2xl border transition-all outline-none focus:ring-4 focus:ring-blue-100 ${
                  showValidation && form.title.length <= 3 ? 'border-red-300 bg-red-50' : 'border-gray-200 focus:border-blue-500'
                }`}
                value={form.title}
                onChange={e => setForm({...form, title: e.target.value})}
              />
              {showValidation && form.title.length <= 3 && (
                <p className="text-red-500 text-xs mt-2 flex items-center gap-1">
                  <AlertCircle size={12} /> Title must be at least 4 characters.
                </p>
              )}
            </div>

            {/* Category Field */}
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-2">Category *</label>
              <div className="relative">
                <select 
                  className="w-full px-5 py-4 rounded-2xl border border-gray-200 appearance-none bg-white focus:ring-4 focus:ring-blue-100 focus:border-blue-500 transition-all outline-none font-medium text-gray-700"
                  value={form.category}
                  onChange={e => setForm({...form, category: e.target.value as IssueCategory})}
                >
                  {Object.values(IssueCategory).map(cat => (
                    <option key={cat} value={cat}>{cat}</option>
                  ))}
                </select>
                <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                  {analyzing ? <Loader2 size={18} className="animate-spin text-blue-500" /> : <ChevronDown size={20} />}
                </div>
              </div>
              {aiInsight && (
                <div className="mt-3 text-sm flex items-start gap-3 text-blue-800 bg-blue-50 p-4 rounded-2xl border border-blue-100 animate-slideUp">
                  <Sparkles size={16} className="mt-0.5 flex-shrink-0 text-blue-600" />
                  <div>
                    <span className="font-bold">AI Suggestion:</span> {aiInsight.reasoning}
                  </div>
                </div>
              )}
            </div>

            {/* Description Field */}
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-2">Description *</label>
              <textarea 
                required
                rows={4}
                placeholder="Describe the problem in detail. Include specific landmarks if possible."
                className={`w-full px-5 py-4 rounded-2xl border transition-all outline-none focus:ring-4 focus:ring-blue-100 ${
                  showValidation && form.description.length <= 10 ? 'border-red-300 bg-red-50' : 'border-gray-200 focus:border-blue-500'
                }`}
                value={form.description}
                onBlur={handleDescriptionBlur}
                onChange={e => setForm({...form, description: e.target.value})}
              />
              <p className="text-xs text-gray-400 mt-2">Helpful hint: Use more than 15 characters to trigger AI categorization.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* Photo Upload */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">Attach Photo</label>
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="group border-2 border-dashed border-gray-200 rounded-3xl p-8 flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all h-40 overflow-hidden"
                >
                  {form.image ? (
                    <div className="relative w-full h-full">
                      <img src={form.image} className="w-full h-full object-cover rounded-xl" alt="Preview" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity rounded-xl">
                        <span className="text-white text-xs font-bold">Change Photo</span>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center mb-3 group-hover:bg-blue-100 transition-colors">
                        <Camera size={24} className="text-gray-400 group-hover:text-blue-600" />
                      </div>
                      <span className="text-sm text-gray-500 font-bold">Tap to upload</span>
                    </>
                  )}
                </div>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  onChange={handleFileChange} 
                  accept="image/*" 
                  className="hidden" 
                />
              </div>

              {/* Location Selection */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">Tag Location *</label>
                <div className="space-y-4">
                  <button 
                    type="button"
                    onClick={handleLocation}
                    disabled={locationLoading}
                    className={`w-full px-5 py-5 rounded-2xl font-bold flex items-center justify-center gap-3 transition-all ${
                      form.location 
                      ? 'bg-green-50 text-green-700 border border-green-200' 
                      : 'bg-gray-100 text-gray-700 hover:bg-gray-200 border border-transparent'
                    } ${showValidation && !form.location ? 'border-red-300 bg-red-50' : ''}`}
                  >
                    {locationLoading ? <Loader2 size={20} className="animate-spin" /> : <MapPin size={20} />}
                    {form.location ? 'Location Updated' : 'Capture My Location'}
                  </button>
                  {form.location && (
                    <div className="text-[11px] text-green-700 bg-green-50/50 p-4 rounded-2xl flex items-start gap-2 border border-green-100 animate-fadeIn">
                      <CheckCircle size={14} className="mt-0.5" />
                      <div>
                        <span className="font-bold">Address:</span> {form.location.address}<br/>
                        <span className="opacity-70 font-mono">{form.location.latitude.toFixed(6)}, {form.location.longitude.toFixed(6)}</span>
                      </div>
                    </div>
                  )}
                  {showValidation && !form.location && (
                    <p className="text-red-500 text-xs flex items-center gap-1">
                      <AlertCircle size={12} /> Please capture your location to submit.
                    </p>
                  )}
                </div>
              </div>
            </div>

            <div className="pt-4">
              <button 
                type="submit"
                disabled={loading}
                className={`w-full py-5 rounded-2xl font-black text-xl shadow-lg flex items-center justify-center gap-3 transition-all transform active:scale-95 ${
                  isFormValid 
                  ? 'bg-blue-700 text-white hover:bg-blue-800 shadow-blue-500/20' 
                  : 'bg-gray-200 text-gray-400 cursor-not-allowed'
                }`}
              >
                {loading ? <Loader2 size={24} className="animate-spin" /> : <Send size={24} />}
                Submit Report
              </button>
              {showValidation && !isFormValid && (
                <p className="text-center text-red-500 text-sm mt-4 font-medium animate-pulse">
                  Please complete the required fields marked with *
                </p>
              )}
            </div>
          </form>
        </div>

        {/* Sidebar help */}
        <div className="space-y-6">
          <div className="bg-blue-700 text-white p-8 rounded-3xl shadow-xl shadow-blue-900/10">
            <h3 className="flex items-center gap-2 text-xl font-bold mb-4">
              <Info size={24} className="text-blue-300" />
              What Happens Next?
            </h3>
            <ul className="space-y-6 text-sm">
              <li className="flex gap-4">
                <span className="flex-shrink-0 w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold">1</span>
                <p className="text-blue-50">Report is assigned a tracking ID instantly.</p>
              </li>
              <li className="flex gap-4">
                <span className="flex-shrink-0 w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold">2</span>
                <p className="text-blue-50">The relevant department is alerted with your photos and GPS.</p>
              </li>
              <li className="flex gap-4">
                <span className="flex-shrink-0 w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold">3</span>
                <p className="text-blue-50">You can track resolution progress on the 'Track' page.</p>
              </li>
            </ul>
          </div>

          <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-sm">
            <h3 className="font-bold text-gray-900 mb-4 flex items-center gap-2">
              <Sparkles size={20} className="text-blue-600" />
              Smart Categorization
            </h3>
            <p className="text-sm text-gray-600 leading-relaxed">
              Our integration with <strong>Gemini 3 Flash</strong> processes your description to ensure it goes to the right hands without manual dispatch delays.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

