import React, { useState, useEffect } from 'react';
import { 
  Search, 
  Clock, 
  MapPin, 
  Tag, 
  Calendar,
  AlertCircle,
  CheckCircle2,
  ChevronRight,
  History,
  ArrowLeft
} from 'lucide-react';
import { Grievance, IssueStatus } from '../types';

interface TrackPageProps {
  grievances: Grievance[];
}

const TrackPage: React.FC<TrackPageProps> = ({ grievances }) => {
  const [searchId, setSearchId] = useState('');
  const [selectedIssue, setSelectedIssue] = useState<Grievance | null>(null);

  // Automatically select the most recent grievance for convenience if it's the only one or user just submitted
  useEffect(() => {
    if (grievances.length > 0 && !selectedIssue && searchId === '') {
      // Don't auto-select unless we want to highlight the newest one
    }
  }, [grievances]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    const found = grievances.find(g => g.id.toLowerCase() === searchId.toLowerCase().trim());
    if (found) {
      setSelectedIssue(found);
    } else {
      alert("Complaint ID not found. Please check and try again.");
    }
  };

  const statusConfig = {
    [IssueStatus.SUBMITTED]: { color: 'bg-blue-100 text-blue-700', icon: <Clock size={16} /> },
    [IssueStatus.IN_PROGRESS]: { color: 'bg-orange-100 text-orange-700', icon: <History size={16} /> },
    [IssueStatus.RESOLVED]: { color: 'bg-green-100 text-green-700', icon: <CheckCircle2 size={16} /> },
    [IssueStatus.REJECTED]: { color: 'bg-red-100 text-red-700', icon: <AlertCircle size={16} /> }
  };

  const getTimeline = (status: IssueStatus) => {
    const steps = [
      { label: 'Submitted', status: IssueStatus.SUBMITTED },
      { label: 'Under Review', status: IssueStatus.IN_PROGRESS },
      { label: 'Assigned', status: IssueStatus.IN_PROGRESS },
      { label: 'Resolved', status: IssueStatus.RESOLVED }
    ];

    const activeIdx = status === IssueStatus.SUBMITTED ? 0 : 
                      status === IssueStatus.IN_PROGRESS ? 2 :
                      status === IssueStatus.RESOLVED ? 3 : -1;

    return steps.map((step, idx) => ({
      ...step,
      completed: idx <= activeIdx
    }));
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 animate-fadeIn min-h-[80vh]">
      <div className="mb-10 text-center">
        <h1 className="text-3xl font-extrabold text-gray-900 mb-3 tracking-tight">Track Your Complaint</h1>
        <p className="text-gray-600">Enter your unique tracking ID or select from recent reports below.</p>
      </div>

      {!selectedIssue ? (
        <div className="space-y-12">
          <form onSubmit={handleSearch} className="max-w-xl mx-auto">
            <div className="relative group">
              <input 
                type="text" 
                placeholder="e.g. GRV-1234"
                className="w-full pl-14 pr-28 py-6 rounded-3xl border-2 border-blue-50 focus:border-blue-600 transition-all outline-none text-xl font-bold placeholder:text-gray-300 shadow-xl shadow-blue-900/5 group-hover:border-blue-200"
                value={searchId}
                onChange={e => setSearchId(e.target.value)}
              />
              <Search className="absolute left-6 top-7 text-gray-400 group-hover:text-blue-500 transition-colors" size={24} />
              <button 
                type="submit"
                className="absolute right-3 top-3 bg-blue-700 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-blue-800 transition-all shadow-lg active:scale-95"
              >
                Track
              </button>
            </div>
          </form>

          <div>
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold text-gray-900">Recent Reports</h3>
              <span className="text-xs font-bold text-blue-600 bg-blue-50 px-3 py-1 rounded-full uppercase tracking-widest">Public Feed</span>
            </div>
            <div className="grid grid-cols-1 gap-4">
              {grievances.length === 0 ? (
                <div className="text-center py-20 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-100">
                  <p className="text-gray-400 font-medium italic">No recent reports found in your area.</p>
                </div>
              ) : (
                grievances.slice(0, 5).map((g) => (
                  <div 
                    key={g.id} 
                    className="bg-white p-6 rounded-2xl border border-gray-100 flex items-center justify-between group cursor-pointer hover:border-blue-300 hover:shadow-lg hover:shadow-blue-900/5 transition-all"
                    onClick={() => { setSelectedIssue(g); setSearchId(g.id); }}
                  >
                    <div className="flex items-center gap-5">
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-sm ${statusConfig[g.status].color}`}>
                        {statusConfig[g.status].icon}
                      </div>
                      <div>
                        <h4 className="font-bold text-gray-900 mb-1 group-hover:text-blue-700 transition-colors">{g.title}</h4>
                        <div className="text-xs text-gray-500 flex items-center gap-3">
                          <span className="font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded-md">{g.id}</span>
                          <span>•</span>
                          <span className="flex items-center gap-1"><Tag size={12} /> {g.category}</span>
                        </div>
                      </div>
                    </div>
                    <div className="hidden sm:flex items-center gap-3">
                      <div className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${statusConfig[g.status].color}`}>
                        {g.status}
                      </div>
                      <ChevronRight className="text-gray-300 group-hover:text-blue-500 transition-colors" />
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      ) : (
        <div className="animate-slideUp">
          <button 
            onClick={() => setSelectedIssue(null)}
            className="mb-8 flex items-center gap-2 text-gray-500 font-bold hover:text-blue-700 transition-colors"
          >
            <ArrowLeft size={18} />
            Back to search
          </button>

          <div className="bg-white p-8 md:p-12 rounded-[2.5rem] shadow-2xl shadow-blue-900/5 border border-gray-100">
            <div className="flex flex-col md:flex-row justify-between items-start gap-6 mb-10">
              <div className="space-y-2">
                <div className="flex items-center gap-3">
                  <span className="text-xs font-black uppercase tracking-[0.2em] text-blue-600 bg-blue-50 px-3 py-1 rounded-lg">Official Report</span>
                  <span className="text-xs font-bold text-gray-400">#{selectedIssue.id}</span>
                </div>
                <h2 className="text-3xl md:text-4xl font-black text-gray-900 tracking-tight leading-tight">{selectedIssue.title}</h2>
              </div>
              <div className={`flex items-center gap-2.5 px-6 py-3 rounded-2xl font-black text-sm shadow-sm ${statusConfig[selectedIssue.status].color}`}>
                {statusConfig[selectedIssue.status].icon}
                {selectedIssue.status.toUpperCase()}
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 mb-12">
              <div className="space-y-6">
                <div className="bg-gray-50/50 p-6 rounded-3xl space-y-5">
                  <div className="flex items-center gap-4 text-gray-700">
                    <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-blue-600">
                      <Tag size={20} />
                    </div>
                    <div>
                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Category</p>
                      <p className="font-bold">{selectedIssue.category}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 text-gray-700">
                    <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-red-600">
                      <MapPin size={20} />
                    </div>
                    <div>
                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Location</p>
                      <p className="font-bold">{selectedIssue.location.address || "Geo-tagged location"}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 text-gray-700">
                    <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-green-600">
                      <Calendar size={20} />
                    </div>
                    <div>
                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Reported Date</p>
                      <p className="font-bold">{new Date(selectedIssue.createdAt).toLocaleDateString(undefined, { dateStyle: 'long' })}</p>
                    </div>
                  </div>
                </div>

                <div className="bg-blue-50/30 p-6 rounded-3xl border border-blue-50">
                  <p className="text-[10px] font-bold text-blue-400 uppercase tracking-widest mb-2">Detailed Description</p>
                  <p className="text-gray-600 leading-relaxed font-medium">"{selectedIssue.description}"</p>
                </div>
              </div>

              {selectedIssue.image ? (
                <div className="rounded-[2rem] overflow-hidden border-8 border-gray-50 shadow-inner group">
                  <img src={selectedIssue.image} alt="Report evidence" className="w-full h-full object-cover aspect-video lg:aspect-square group-hover:scale-110 transition-transform duration-700" />
                </div>
              ) : (
                <div className="rounded-[2rem] bg-gray-50 flex flex-col items-center justify-center p-12 text-center border-2 border-dashed border-gray-100">
                  <History size={40} className="text-gray-200 mb-4" />
                  <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">No Evidence Photo Provided</p>
                </div>
              )}
            </div>

            <div className="border-t border-gray-100 pt-12">
              <h3 className="font-black text-gray-900 mb-10 flex items-center gap-3 text-xl">
                <History size={24} className="text-blue-600" />
                Resolution Journey
              </h3>

              <div className="relative px-4 sm:px-12">
                <div className="absolute top-6 left-12 right-12 h-1 bg-gray-100 hidden sm:block"></div>
                <div className="flex flex-col sm:flex-row justify-between relative z-10 gap-8 sm:gap-0">
                  {getTimeline(selectedIssue.status).map((step, i) => (
                    <div key={i} className="flex flex-row sm:flex-col items-center gap-4 sm:gap-0 text-left sm:text-center sm:max-w-[120px]">
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mb-4 border-4 border-white shadow-md transition-all duration-500 ${step.completed ? 'bg-blue-600 text-white scale-110' : 'bg-gray-100 text-gray-300'}`}>
                        {step.completed ? <CheckCircle2 size={24} /> : <span className="text-sm font-black">{i + 1}</span>}
                      </div>
                      <div>
                        <span className={`text-[10px] font-black uppercase tracking-widest block ${step.completed ? 'text-blue-700' : 'text-gray-400'}`}>
                          {step.label}
                        </span>
                        {step.completed && (
                          <span className="text-[9px] text-gray-400 font-bold mt-1 block">Completed</span>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

