            <Route path="/track" element={<TrackPage grievances={grievances} />} />
            <Route path="/admin" element={<AdminPage grievances={grievances} onUpdateStatus={updateGrievanceStatus} />} />
            <Route path="/contact" element={<ContactPage />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
};

