import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Camera, 
  MapPin, 
  Send, 
  Loader2, 
  AlertCircle,
  CheckCircle,
  Sparkles,
  Info,
  ArrowRight,
  ArrowLeft,
  FileText,
  Image as ImageIcon
} from 'lucide-react';
import { IssueCategory, IssueStatus, Grievance, Location } from '../types';
import { aiService } from '../services/geminiService';

interface ReportPageProps {
  onAdd: (g: Grievance) => void;
}

const ReportPage: React.FC<ReportPageProps> = ({ onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [locationLoading, setLocationLoading] = useState(false);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    description: '',
    image: '',
    location: null as Location | null
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, reasoning: string } | null>(null);

  const handleLocation = () => {
    setLocationLoading(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setForm(prev => ({
            ...prev,
            location: {
              latitude: position.coords.latitude,
              longitude: position.coords.longitude,
              address: "Current GPS Location"
            }
          }));
          setLocationLoading(false);
        },
        (error) => {
          setForm(prev => ({
            ...prev,
            location: { latitude: 40.7128, longitude: -74.0060, address: "Manual Location Set" }
          }));
          setLocationLoading(false);
        }
      );
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 15) return;
    setAnalyzing(true);
    const result = await aiService.categorizeIssue(form.description);
    setForm(prev => ({ ...prev, category: result.category }));
    setAiInsight({ category: result.category, reasoning: result.reasoning });
    setAnalyzing(false);
  };

  const handleSubmit = () => {
    setLoading(true);
    const newGrievance: Grievance = {
      id: `GRV-${Math.floor(1000 + Math.random() * 8999)}`,
      title: form.title,
      category: form.category,
      description: form.description,
      image: form.image,
      location: form.location!,
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight
    };

    setTimeout(() => {
      onAdd(newGrievance);
      setLoading(false);
      setSuccess(true);
      setTimeout(() => navigate('/track'), 2000);
    }, 1500);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-40 animate-fadeIn min-h-[70vh]">
        <div className="bg-green-100 text-green-600 p-8 rounded-[2rem] mb-8 animate-bounce shadow-xl shadow-green-100/50">
          <CheckCircle size={80} />
        </div>
        <h2 className="text-4xl font-black text-gray-900 mb-4 tracking-tight">Report Received!</h2>
        <p className="text-gray-500 font-medium">Assigning officials to your case. Redirecting...</p>
      </div>
    );
  }

  const steps = [
    { n: 1, label: 'Details', icon: <FileText size={16} /> },
    { n: 2, label: 'Evidence', icon: <Camera size={16} /> },
    { n: 3, label: 'Review', icon: <Send size={16} /> }
  ];

  return (
    <div className="max-w-3xl mx-auto px-4 py-16 animate-fadeIn">
      {/* Progress Header */}
      <div className="mb-12 flex items-center justify-between px-2">
        {steps.map((s, idx) => (
          <React.Fragment key={s.n}>
            <div className="flex flex-col items-center gap-3 relative">
              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all duration-500 font-bold ${
                step >= s.n ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-gray-100 text-gray-400'
              }`}>
                {step > s.n ? <CheckCircle size={20} /> : s.icon}
              </div>
              <span className={`text-[10px] font-black uppercase tracking-widest ${step >= s.n ? 'text-blue-700' : 'text-gray-400'}`}>
                {s.label}
              </span>
            </div>
            {idx < steps.length - 1 && (
              <div className={`h-0.5 flex-grow mx-4 rounded-full transition-all duration-700 ${step > s.n ? 'bg-blue-600' : 'bg-gray-100'}`} />
            )}
          </React.Fragment>
        ))}
      </div>

      <div className="bg-white p-8 md:p-12 rounded-[3rem] shadow-2xl shadow-blue-900/5 border border-gray-100">
        {step === 1 && (
          <div className="space-y-8 animate-fadeIn">
            <div>
              <h2 className="text-2xl font-black text-gray-900 mb-2">Issue Description</h2>
              <p className="text-gray-500 text-sm mb-6">Tell us exactly what's wrong. Be as detailed as possible.</p>

              <div className="space-y-6">
                <div>
                  <label className="block text-xs font-black uppercase tracking-widest text-gray-400 mb-2">Brief Summary</label>
                  <input 
                    type="text" 
                    placeholder="e.g. Clogged drain on 5th Avenue"
                    className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-none focus:ring-4 focus:ring-blue-100 transition-all font-medium"
                    value={form.title}
                    onChange={e => setForm({...form, title: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-xs font-black uppercase tracking-widest text-gray-400 mb-2">Detailed Context</label>
                  <textarea 
                    rows={4}
                    placeholder="Describe the severity and how long it's been happening..."
                    className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-none focus:ring-4 focus:ring-blue-100 transition-all font-medium"
                    value={form.description}
                    onChange={e => setForm({...form, description: e.target.value})}
                    onBlur={runAiAnalysis}
                  />
                </div>
              </div>
            </div>

            {aiInsight && (
              <div className="bg-blue-50 border border-blue-100 p-6 rounded-3xl flex gap-4 animate-slideUp">
                <Sparkles className="text-blue-600 flex-shrink-0" size={24} />
                <div>
                  <div className="text-xs font-black uppercase tracking-widest text-blue-400 mb-1">AI Classification</div>
                  <p className="text-blue-900 font-bold text-sm mb-1">{form.category}</p>
                  <p className="text-blue-700/70 text-xs leading-relaxed">{aiInsight.reasoning}</p>
                </div>
              </div>
            )}

            <button 
              disabled={form.title.length < 5 || form.description.length < 10}
              onClick={() => setStep(2)}
              className="w-full py-5 rounded-2xl bg-blue-600 text-white font-black flex items-center justify-center gap-3 hover:bg-blue-700 disabled:opacity-30 disabled:grayscale transition-all shadow-xl shadow-blue-100"
            >
              Next Step
              <ArrowRight size={20} />
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-8 animate-fadeIn">
            <div>
              <h2 className="text-2xl font-black text-gray-900 mb-2">Evidence & Location</h2>
              <p className="text-gray-500 text-sm mb-6">Visuals and location data help us prioritize your report.</p>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="aspect-square bg-gray-50 rounded-[2rem] border-4 border-dashed border-gray-100 flex flex-col items-center justify-center cursor-pointer hover:bg-blue-50 hover:border-blue-200 transition-all group relative overflow-hidden"
                >
                  {form.image ? (
                    <img src={form.image} className="w-full h-full object-cover" alt="Preview" />
                  ) : (
                    <>
                      <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center shadow-sm text-gray-400 group-hover:text-blue-600 transition-colors mb-4">
                        <ImageIcon size={32} />
                      </div>
                      <span className="text-xs font-black text-gray-400 uppercase tracking-widest">Add Photo</span>
                    </>
                  )}
                  <input ref={fileInputRef} type="file" className="hidden" onChange={handleFileChange} accept="image/*" />
                </div>

                <div className="space-y-4">
                  <button 
                    onClick={handleLocation}
                    className={`w-full h-1/2 rounded-[2rem] flex flex-col items-center justify-center transition-all ${
                      form.location ? 'bg-green-50 text-green-700 border-2 border-green-100' : 'bg-blue-50 text-blue-700 border-2 border-blue-100 hover:bg-blue-100'
                    }`}
                  >
                    {locationLoading ? <Loader2 size={32} className="animate-spin" /> : <MapPin size={32} />}
                    <span className="text-[10px] font-black uppercase tracking-widest mt-2">
                      {form.location ? 'Location Cached' : 'Pin My Location'}
                    </span>
                  </button>
                  {form.location && (
                    <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100 text-[10px] font-bold text-gray-400">
                      <p className="uppercase tracking-widest mb-1">Detected Address</p>
                      <p className="text-gray-900">{form.location.address}</p>
                    </div>
                  )}
                </div>
              </div>
            </div>

            <div className="flex gap-4">
              <button 
                onClick={() => setStep(1)}
                className="w-20 h-16 rounded-2xl bg-gray-100 flex items-center justify-center text-gray-500 hover:bg-gray-200 transition-colors"
              >
                <ArrowLeft size={24} />
              </button>
              <button 
                disabled={!form.location}
                onClick={() => setStep(3)}
                className="flex-grow py-5 rounded-2xl bg-blue-600 text-white font-black flex items-center justify-center gap-3 hover:bg-blue-700 disabled:opacity-30 transition-all shadow-xl shadow-blue-100"
              >
                Final Review
                <ArrowRight size={20} />
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-8 animate-fadeIn">
            <div>
              <h2 className="text-2xl font-black text-gray-900 mb-2">Review Report</h2>
              <p className="text-gray-500 text-sm mb-8">Make sure everything looks correct before submitting.</p>

              <div className="space-y-6">
                <div className="bg-gray-50 p-6 rounded-3xl space-y-4">
                  <div>
                    <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 block mb-1">Issue</span>
                    <p className="font-bold text-gray-900">{form.title}</p>
                  </div>
                  <div className="flex gap-12">
                    <div>
                      <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 block mb-1">Category</span>
                      <p className="font-bold text-blue-600">{form.category}</p>
                    </div>
                    <div>
                      <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 block mb-1">Location</span>
                      <p className="font-bold text-gray-700">{form.location?.address}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex gap-4">
              <button 
                onClick={() => setStep(2)}
                className="w-20 h-16 rounded-2xl bg-gray-100 flex items-center justify-center text-gray-500 hover:bg-gray-200 transition-colors"
              >
                <ArrowLeft size={24} />
              </button>
              <button 
                disabled={loading}
                onClick={handleSubmit}
                className="flex-grow py-5 rounded-2xl bg-green-600 text-white font-black flex items-center justify-center gap-3 hover:bg-green-700 transition-all shadow-xl shadow-green-100"
              >
