import { GoogleGenAI, Type } from "@google/genai";
import { IssueCategory, IssuePriority } from "../types";

export const aiService = {
  async categorizeIssue(description: string): Promise<{ category: IssueCategory; priority: IssuePriority; reasoning: string }> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Analyze this civic grievance: "${description}". 
        Assign it exactly one of these categories: ${Object.values(IssueCategory).join(", ")}. 
        Also assign a priority level: ${Object.values(IssuePriority).join(", ")} (e.g., life-threatening hazards like fire or open manholes should be CRITICAL, inconveniences like potholes should be MEDIUM or LOW).`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              category: {
                type: Type.STRING,
                description: "The most appropriate category from the provided list.",
              },
              priority: {
                type: Type.STRING,
                description: "The suggested priority level.",
              },
              reasoning: {
                type: Type.STRING,
                description: "Brief reasoning for the choices.",
              },
            },
            required: ["category", "priority", "reasoning"],
          },
        },
      });

      const result = JSON.parse(response.text);

      const validatedCategory = Object.values(IssueCategory).includes(result.category as IssueCategory) 
        ? (result.category as IssueCategory) 
        : IssueCategory.OTHERS;

      const validatedPriority = Object.values(IssuePriority).includes(result.priority as IssuePriority)
        ? (result.priority as IssuePriority)
        : IssuePriority.MEDIUM;

      return {
        category: validatedCategory,
        priority: validatedPriority,
        reasoning: result.reasoning
      };
    } catch (error) {
      console.error("AI Categorization failed:", error);
      return { 
        category: IssueCategory.OTHERS, 
        priority: IssuePriority.MEDIUM, 
        reasoning: "Error during AI analysis." 
      };
    }
  }
};

