import { GoogleGenAI, Type } from "@google/genai";
import { IssueCategory, IssuePriority } from "../types";

/**
 * Utility for exponential backoff retries
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 3, initialDelay = 1000): Promise<T> {
  let lastError: any;
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      // Only retry on potential transient errors (network, 5xx)
      const isTransient = error instanceof Error && 
        (error.message.includes('500') || 
         error.message.includes('xhr') || 
         error.message.includes('fetch') ||
         error.message.includes('Rpc failed'));

      if (!isTransient && attempt > 0) break; 

      const delay = initialDelay * Math.pow(2, attempt);
      console.warn(`AI API call failed (Attempt ${attempt + 1}/${maxRetries}). Retrying in ${delay}ms...`, error);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}

export const aiService = {
  async categorizeIssue(description: string): Promise<{ category: IssueCategory; priority: IssuePriority; reasoning: string }> {
    const performCategorization = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Analyze this civic grievance: "${description}". 
        Assign it exactly one of these categories: ${Object.values(IssueCategory).join(", ")}. 
        Also assign a priority level: ${Object.values(IssuePriority).join(", ")} (e.g., life-threatening hazards like fire or open manholes should be CRITICAL, inconveniences like potholes should be MEDIUM or LOW).

        Provide your reasoning in a concise manner.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              category: {
                type: Type.STRING,
                description: "The most appropriate category from the provided list.",
              },
              priority: {
                type: Type.STRING,
                description: "The suggested priority level.",
              },
              reasoning: {
                type: Type.STRING,
                description: "Brief reasoning for the choices.",
              },
            },
            required: ["category", "priority", "reasoning"],
          },
        },
      });

      if (!response || !response.text) {
        throw new Error("Empty response from AI model");
      }

      const result = JSON.parse(response.text.trim());

      const validatedCategory = Object.values(IssueCategory).includes(result.category as IssueCategory) 
        ? (result.category as IssueCategory) 
        : IssueCategory.OTHERS;

      const validatedPriority = Object.values(IssuePriority).includes(result.priority as IssuePriority)
        ? (result.priority as IssuePriority)
        : IssuePriority.MEDIUM;

      return {
        category: validatedCategory,
        priority: validatedPriority,
        reasoning: result.reasoning || "Categorized based on description details."
      };
    };

    try {
      // Execute the request with retry logic
      return await withRetry(performCategorization);
    } catch (error) {
      console.error("AI Categorization failed after multiple attempts:", error);

      // Graceful fallback to allow user to proceed
      return { 
        category: IssueCategory.OTHERS, 
        priority: IssuePriority.MEDIUM, 
        reasoning: "The automated analysis service is currently unavailable. You can manually adjust your report settings before submission." 
      };
    }
  }
};

