/**
 * Utility for exponential backoff retries
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 3, initialDelay = 1000): Promise<T> {
  let lastError: any;
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      const isTransient = error instanceof Error && 
        (error.message.includes('500') || 
         error.message.includes('xhr') || 
         error.message.includes('fetch') ||
         error.message.includes('Rpc failed'));

      if (!isTransient && attempt > 0) break; 

      const delay = initialDelay * Math.pow(2, attempt);
      console.warn(`AI API call failed (Attempt ${attempt + 1}/${maxRetries}). Retrying in ${delay}ms...`, error);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}

export const aiService = {
  async categorizeIssue(description: string): Promise<{ category: IssueCategory; priority: IssuePriority; reasoning: string }> {
    const performCategorization = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Analyze this civic grievance: "${description}". 
        Assign it exactly one of these categories: ${Object.values(IssueCategory).join(", ")}. 
        Also assign a priority level: ${Object.values(IssuePriority).join(", ")}.

        Provide your reasoning in a concise manner.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              category: { type: Type.STRING },
              priority: { type: Type.STRING },
              reasoning: { type: Type.STRING },
            },
            required: ["category", "priority", "reasoning"],
          },
        },
      });

      if (!response || !response.text) throw new Error("Empty response");
      const result = JSON.parse(response.text.trim());

      return {
        category: Object.values(IssueCategory).includes(result.category as IssueCategory) ? (result.category as IssueCategory) : IssueCategory.OTHERS,
        priority: Object.values(IssuePriority).includes(result.priority as IssuePriority) ? (result.priority as IssuePriority) : IssuePriority.MEDIUM,
        reasoning: result.reasoning || "Analyzed via AI models."
      };
    };

    try { return await withRetry(performCategorization); } catch (e) {
      return { category: IssueCategory.OTHERS, priority: IssuePriority.MEDIUM, reasoning: "Manual review required." };
    }
  },

  async detectDuplicates(description: string, existingReports: Grievance[]): Promise<Grievance | null> {
    if (existingReports.length === 0) return null;

    const summary = existingReports.map(r => `ID: ${r.id}, Desc: ${r.description}`).join("\n");
    const performDetection = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `A user is reporting this: "${description}".
        Below are existing reports:
        ${summary}

        Is there a report above that likely describes the EXACT same physical issue? 
        If yes, return that report ID. If no, return null.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              duplicateId: { type: Type.STRING, nullable: true },
            }
          },
        },
      });

      if (!response || !response.text) return null;
      const result = JSON.parse(response.text.trim());
      return existingReports.find(r => r.id === result.duplicateId) || null;
    };

    try { return await withRetry(performDetection); } catch { return null; }
  }
};

