              <div className="flex gap-2">
                <span className="px-3 py-1 bg-white border rounded-full text-[10px] font-black uppercase">{form.category}</span>
                <span className="px-3 py-1 bg-white border rounded-full text-[10px] font-black uppercase">{form.priority}</span>
              </div>
            </div>
            <div className="flex gap-4">
