              <button disabled={loading} onClick={handleSubmit} className="flex-grow py-5 bg-green-600 text-white rounded-2xl font-black flex items-center justify-center gap-2">
                {loading && <Loader2 size={20} className="animate-spin" />}
                Submit Grievance
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

