  const [locationLoading, setLocationLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [duplicateReport, setDuplicateReport] = useState<Grievance | null>(null);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    priority: IssuePriority.MEDIUM,
    description: '',
    image: '',
    location: null as Location | null
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, priority: string, reasoning: string } | null>(null);

  // Initialize Speech Recognition once
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.lang = 'en-US';
      recognition.continuous = false;
      recognition.interimResults = false;

      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onerror = (event: any) => {
        console.error('Speech recognition error:', event.error);
        setIsListening(false);
      };

      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setForm(prev => ({ 
          ...prev, 
          description: (prev.description + " " + transcript).trim() 
        }));
      };

      recognitionRef.current = recognition;
    }

    return () => {
      if (recognitionRef.current) recognitionRef.current.stop();
    };
  }, []);

  const toggleVoiceInput = (e: React.MouseEvent) => {
    e.preventDefault();
    if (!recognitionRef.current) {
      alert("Speech recognition is not supported in this browser. Try Chrome or Edge.");
      return;
    }

    if (isListening) {
      recognitionRef.current.stop();
    } else {
      try {
        recognitionRef.current.start();
      } catch (err) {
        console.error("Failed to start recognition:", err);
      }
    }
  };

  const checkDuplicates = async () => {
    if (form.description.length < 20) return;
    const duplicate = await aiService.detectDuplicates(form.description, grievances);
    setDuplicateReport(duplicate);
  };

  const handleLocation = () => {
    setLocationLoading(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setForm(prev => ({
            ...prev,
            location: {
              latitude: position.coords.latitude,
              longitude: position.coords.longitude,
              address: `${position.coords.latitude.toFixed(4)}, ${position.coords.longitude.toFixed(4)}`,
              area: "Central Zone"
            }
          }));
          setLocationLoading(false);
        },
        () => setLocationLoading(false),
        { enableHighAccuracy: true, timeout: 5000 }
      );
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 15) return;
    setAnalyzing(true);
    const result = await aiService.categorizeIssue(form.description);
    setForm(prev => ({ ...prev, category: result.category, priority: result.priority }));
    setAiInsight({ category: result.category, priority: result.priority, reasoning: result.reasoning });
    setAnalyzing(false);
    checkDuplicates();
  };

  const handleSubmit = () => {
    if (!form.location) return;
    setLoading(true);
    const newGrievance: Grievance = {
      id: `GRV-${Math.floor(1000 + Math.random() * 8999)}`,
      title: form.title || `Issue: ${form.category}`,
      category: form.category,
      priority: form.priority,
      description: form.description,
      image: form.image,
      location: form.location,
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight,
      upvotes: 0
    };

    setTimeout(() => {
      onAdd(newGrievance);
      setLoading(false);
      setSuccess(true);
      setTimeout(() => navigate('/track'), 2000);
    }, 1500);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-40 animate-fadeIn min-h-[70vh] bg-white">
        <div className="bg-green-100 text-green-600 p-8 rounded-[2rem] mb-8 shadow-xl">
          <CheckCircle size={80} />
        </div>
        <h2 className="text-4xl font-black text-gray-900 mb-4 tracking-tight">Submission Successful!</h2>
        <p className="text-gray-500 font-medium">Authorities have been notified. Taking you to tracking...</p>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto px-4 py-16 animate-fadeIn">
      <div className="mb-12 flex items-center justify-between px-2">
        {[1, 2, 3].map((s) => (
          <div key={s} className="flex flex-col items-center gap-2">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold ${step >= s ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-400'}`}>
              {s}
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 md:p-12 rounded-[3rem] shadow-2xl border border-gray-100">
        {step === 1 && (
          <div className="space-y-8 animate-slideLeft">
            <div>
              <h2 className="text-3xl font-black text-gray-900 mb-2">Issue Details</h2>
              <p className="text-gray-500 text-sm mb-8">Describe the problem. Tap the mic icon to dictate.</p>

              <div className="space-y-6">
                <div className="relative">
                  <label className="block text-xs font-black uppercase tracking-widest text-gray-400 mb-3">Describe the situation</label>
                  <textarea 
                    rows={4}
                    placeholder="E.g., Large pothole causing traffic near..."
                    className="w-full px-6 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-100 focus:bg-white transition-all font-medium text-gray-800"
                    value={form.description}
                    onChange={e => setForm({...form, description: e.target.value})}
                    onBlur={runAiAnalysis}
                  />
                  <button 
                    type="button"
                    onClick={toggleVoiceInput}
                    className={`absolute right-4 bottom-4 w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-md active:scale-95 ${
                      isListening ? 'bg-red-500 text-white animate-pulse ring-4 ring-red-100' : 'bg-white text-gray-400 hover:text-blue-600'
                    }`}
                  >
                    {isListening ? <MicOff size={22} /> : <Mic size={22} />}
                  </button>
                </div>

                {duplicateReport && (
                  <div className="bg-orange-50 border border-orange-100 p-6 rounded-[2rem] flex flex-col gap-4 animate-slideUp">
                    <div className="flex items-center gap-3 text-orange-700 font-black text-sm">
                      <Search size={20} />
                      Duplicate Issue Detected Nearby!
                    </div>
                    <p className="text-orange-900/70 text-xs">A similar issue was reported: <strong>"{duplicateReport.title}"</strong>. Support it instead of creating a new one?</p>
                    <Link to="/track" className="bg-orange-600 text-white px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest text-center hover:bg-orange-700 transition-all">
                      Support Existing Report
                    </Link>
                  </div>
                )}

                <div>
                  <label className="block text-xs font-black uppercase tracking-widest text-gray-400 mb-3">Issue Category</label>
                  <div className="relative">
                    <select 
                      className="w-full px-6 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-100 transition-all font-bold text-gray-800 appearance-none cursor-pointer"
                      value={form.category}
                      onChange={e => setForm({...form, category: e.target.value as IssueCategory})}
                    >
                      {Object.values(IssueCategory).map(cat => (
                        <option key={cat} value={cat}>{cat}</option>
                      ))}
                    </select>
                    <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                      <ChevronDown size={20} />
                    </div>
                  </div>
                </div>

                {analyzing ? (
                  <div className="flex items-center gap-3 text-blue-600 font-bold text-sm p-4 bg-blue-50 rounded-2xl border border-blue-100 animate-pulse">
                    <Loader2 size={20} className="animate-spin" />
                    Civic AI is scanning for duplicates...
                  </div>
                ) : aiInsight && (
                  <div className="bg-blue-50 border border-blue-100 p-6 rounded-[2rem] animate-slideUp">
                    <div className="flex items-center gap-2 mb-2">
                      <Sparkles size={14} className="text-blue-600" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-blue-400">AI Classification Result</span>
                    </div>
                    <div className="flex flex-wrap gap-2 mb-3">
                      <span className="bg-blue-600 text-white text-[10px] font-black px-3 py-1 rounded-full">{form.category}</span>
                      <span className="bg-blue-100 text-blue-700 text-[10px] font-black px-3 py-1 rounded-full">{form.priority} Priority</span>
                    </div>
                    <p className="text-blue-900/80 text-xs font-medium leading-relaxed">{aiInsight.reasoning}</p>
                  </div>
                )}
              </div>
            </div>

            <button 
              disabled={form.description.length < 15 || analyzing}
              onClick={() => setStep(2)}
              className="w-full py-5 rounded-2xl bg-blue-600 text-white font-black hover:bg-blue-700 disabled:opacity-30 transition-all shadow-xl shadow-blue-100 active:scale-95"
            >
              Next Step
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-8 animate-slideLeft">
            <h2 className="text-3xl font-black text-gray-900 mb-2">Proof & Location</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="aspect-square bg-gray-50 rounded-[2.5rem] border-4 border-dashed border-gray-100 flex flex-col items-center justify-center cursor-pointer hover:bg-blue-50 transition-all relative overflow-hidden group"
              >
                {form.image ? (
                  <img src={form.image} className="w-full h-full object-cover" alt="Preview" />
                ) : (
                  <div className="text-center text-gray-400 group-hover:text-blue-600 transition-colors">
                    <ImageIcon size={40} className="mx-auto mb-2" />
                    <span className="text-[10px] font-black uppercase tracking-widest">Attach Evidence</span>
                  </div>
                )}
                <input ref={fileInputRef} type="file" className="hidden" onChange={handleFileChange} accept="image/*" />
              </div>

              <button 
                onClick={handleLocation}
                className={`aspect-square rounded-[2.5rem] flex flex-col items-center justify-center transition-all border-2 active:scale-95 ${
                  form.location ? 'bg-green-50 text-green-700 border-green-100' : 'bg-blue-50 text-blue-700 border-blue-100 shadow-lg'
                }`}
              >
                {locationLoading ? <Loader2 className="animate-spin" size={40} /> : (form.location ? <CheckCircle size={40} /> : <MapPin size={40} />)}
                <span className="text-[10px] font-black uppercase mt-4 tracking-widest">
                  {form.location ? 'Location Logged' : 'Auto Geo-Tag'}
                </span>
              </button>
            </div>

            <div className="flex gap-4">
              <button onClick={() => setStep(1)} className="w-20 py-5 bg-gray-100 rounded-2xl text-gray-500 hover:bg-gray-200 transition-colors"><ArrowLeft className="mx-auto" /></button>
              <button disabled={!form.location} onClick={() => setStep(3)} className="flex-grow py-5 bg-blue-600 text-white rounded-2xl font-black hover:bg-blue-700 active:scale-95 shadow-xl shadow-blue-500/20">Review Report</button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-8 animate-slideLeft">
            <h2 className="text-3xl font-black text-gray-900 mb-2">Final Confirmation</h2>
            <div className="bg-gray-50 p-6 rounded-[2rem] space-y-4 border border-gray-100 shadow-inner">
              <p className="font-bold text-sm text-gray-800 leading-relaxed italic">"{form.description}"</p>
              <div className="flex gap-2">
                <span className="px-3 py-1 bg-white border border-gray-200 rounded-full text-[10px] font-black uppercase text-blue-600">{form.category}</span>
                <span className="px-3 py-1 bg-white border border-gray-200 rounded-full text-[10px] font-black uppercase text-gray-600">{form.priority} Priority</span>
              </div>
            </div>
            <div className="flex gap-4">
              <button onClick={() => setStep(2)} className="w-20 py-5 bg-gray-100 rounded-2xl text-gray-500 hover:bg-gray-200 transition-colors"><ArrowLeft className="mx-auto" /></button>
              <button disabled={loading} onClick={handleSubmit} className="flex-grow py-5 bg-green-600 text-white rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-green-700 shadow-xl shadow-green-100 active:scale-95">
                {loading && <Loader2 size={20} className="animate-spin" />}
                Submit Grievance
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ReportPage;

import React, { useState } from 'react';
import { 
  Filter, 
  MapPin, 
  Tag, 
  ArrowUpRight,
  MoreVertical,
  Download,
  Search,
  CheckCircle,
  Clock,
  AlertTriangle,
  Sparkles,
  TrendingUp,
  Inbox,
  ShieldAlert,
  Info,
  Activity,
  CheckCircle2,
  XCircle,
  Wrench,
  Loader2
} from 'lucide-react';
import { Grievance, IssueCategory, IssueStatus, IssuePriority } from '../types';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  onUpdateStatus: (id: string, status: IssueStatus) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances, onUpdateStatus }) => {
  const [filterCategory, setFilterCategory] = useState<string>('All');
  const [filterStatus, setFilterStatus] = useState<string>('All');
  const [filterPriority, setFilterPriority] = useState<string>('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [verifyingId, setVerifyingId] = useState<string | null>(null);

  const filtered = grievances.filter(g => {
    const matchesCategory = filterCategory === 'All' || g.category === filterCategory;
    const matchesStatus = filterStatus === 'All' || g.status === filterStatus;
    const matchesPriority = filterPriority === 'All' || g.priority === filterPriority;
    const matchesSearch = g.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          g.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          g.description.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesStatus && matchesSearch && matchesPriority;
  });

  const stats = [
    { label: 'Active Reports', count: grievances.length, icon: <Inbox />, color: 'bg-blue-600', trend: '+12%' },
    { label: 'Pending Action', count: grievances.filter(g => g.status === IssueStatus.SUBMITTED).length, icon: <Clock />, color: 'bg-orange-600', trend: '-2%' },
    { label: 'Success Rate', count: Math.round((grievances.filter(g => g.status === IssueStatus.RESOLVED).length / (grievances.length || 1)) * 100) + '%', icon: <CheckCircle />, color: 'bg-green-600', trend: '+5%' },
    { label: 'Critical Issues', count: grievances.filter(g => g.priority === IssuePriority.CRITICAL).length, icon: <AlertTriangle />, color: 'bg-red-600', trend: 'Priority' }
  ];

  const priorityStyles = {
    [IssuePriority.LOW]: 'bg-slate-50 text-slate-500 border-slate-100',
    [IssuePriority.MEDIUM]: 'bg-blue-50 text-blue-600 border-blue-100',
    [IssuePriority.HIGH]: 'bg-orange-50 text-orange-600 border-orange-100',
    [IssuePriority.CRITICAL]: 'bg-red-50 text-red-600 border-red-100'
  };

  const statusIcons = {
    [IssueStatus.SUBMITTED]: <Clock size={16} />,
    [IssueStatus.IN_PROGRESS]: <Wrench size={16} />,
    [IssueStatus.RESOLVED]: <CheckCircle2 size={16} />,
    [IssueStatus.REJECTED]: <XCircle size={16} />
  };

  const handleManualVerify = async (g: Grievance) => {
    setVerifyingId(g.id);
    const result = await aiService.categorizeIssue(g.description);
    alert(`AI Analysis Results:\nCategory: ${result.category}\nPriority: ${result.priority}\nReasoning: ${result.reasoning}`);
    setVerifyingId(null);
  };

  const handleMoreClick = (g: Grievance) => {
    alert(`Case Detail: ${g.id}\nCategory: ${g.category}\nFull Description: ${g.description}\nLocation: ${g.location.address}`);
  };

  return (
    <div className="bg-[#fcfcfd] min-h-screen pb-20 animate-fadeIn">
      {/* Dashboard Header */}
      <div className="bg-white border-b border-gray-100 pt-16 pb-12 mb-10 shadow-sm shadow-gray-100/50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-12">
            <div>
              <div className="flex items-center gap-3 mb-3">
                <span className="bg-blue-100 text-blue-700 text-[10px] font-black px-3 py-1 rounded-lg uppercase tracking-widest">Authority Portal</span>
                <span className="text-gray-300">•</span>
                <span className="text-gray-400 text-[10px] font-bold uppercase tracking-widest">Digital Command Center</span>
              </div>
              <h1 className="text-4xl font-black text-gray-900 tracking-tight">Municipal Operations</h1>
            </div>
            <button className="bg-gray-900 text-white px-8 py-4 rounded-2xl font-black text-sm flex items-center gap-3 hover:bg-black transition-all shadow-xl shadow-gray-200 active:scale-95">
              <Download size={18} />
              Export Dataset
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {stats.map((stat, i) => (
              <div key={i} className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm relative overflow-hidden group hover:shadow-xl hover:shadow-blue-900/5 transition-all">
                <div className="absolute -right-4 -top-4 w-24 h-24 bg-gray-50 rounded-full opacity-50 group-hover:scale-150 transition-transform duration-700" />
                <div className="relative flex justify-between items-start mb-6">
                  <div className={`p-4 rounded-2xl text-white ${stat.color} shadow-lg shadow-current/20`}>
                    {React.cloneElement(stat.icon as React.ReactElement<any>, { size: 24 })}
