                  <div className="flex flex-col items-end">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{stat.label}</span>
                    <div className="text-3xl font-black text-gray-900">{stat.count}</div>
                  </div>
                </div>
                <div className="flex items-center gap-2 text-[10px] font-bold text-green-500">
                  <TrendingUp size={12} />
                  <span>{stat.trend} week-on-week</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4">
        {/* Advanced Filters */}
        <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm mb-10 flex flex-wrap items-center gap-6">
          <div className="relative flex-grow min-w-[300px]">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input 
              type="text" 
              placeholder="Search by ID, title, or keywords..."
              className="w-full pl-16 pr-6 py-5 rounded-3xl bg-gray-50 border-none outline-none focus:ring-4 focus:ring-blue-100 transition-all font-medium text-gray-800"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex flex-wrap gap-4">
            <div className="flex items-center gap-3 px-6 py-4 bg-gray-50 rounded-2xl border border-transparent hover:border-gray-200 transition-all">
              <Filter size={18} className="text-gray-400" />
              <select 
                className="bg-transparent outline-none text-[10px] font-black text-gray-700 uppercase tracking-widest pr-4 cursor-pointer"
                value={filterCategory}
                onChange={e => setFilterCategory(e.target.value)}
              >
                <option value="All">All Categories</option>
                {Object.values(IssueCategory).map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <div className="flex items-center gap-3 px-6 py-4 bg-gray-50 rounded-2xl border border-transparent hover:border-gray-200 transition-all">
              <ShieldAlert size={18} className="text-gray-400" />
              <select 
                className="bg-transparent outline-none text-[10px] font-black text-gray-700 uppercase tracking-widest pr-4 cursor-pointer"
                value={filterPriority}
                onChange={e => setFilterPriority(e.target.value)}
              >
                <option value="All">All Priorities</option>
                {Object.values(IssuePriority).map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
          </div>
        </div>

        {/* Data Table */}
        <div className="bg-white rounded-[3rem] border border-gray-100 shadow-xl shadow-gray-200/20 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100">
                  <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-widest">Report Entry</th>
                  <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-widest">Priority Badge</th>
                  <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-widest">AI Status</th>
                  <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-widest text-right">Workflow Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filtered.map((g) => (
                  <tr key={g.id} className="hover:bg-blue-50/20 transition-colors group">
                    <td className="px-10 py-8">
                      <div className="flex items-center gap-8">
                        <div className="w-14 h-14 rounded-2xl bg-gray-100 flex items-center justify-center text-blue-600 font-black text-[10px] border border-gray-200 group-hover:bg-white group-hover:shadow-md transition-all">
                          {g.id.split('-')[1]}
                        </div>
                        <div>
                          <div className="flex items-center gap-3 mb-1.5">
                            <span className="text-blue-600 font-black text-[10px] tracking-widest uppercase">{g.id}</span>
                            <span className="text-gray-300 text-lg">·</span>
                            <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{new Date(g.createdAt).toLocaleDateString()}</span>
                          </div>
                          <h4 className="font-black text-gray-900 mb-1.5 text-lg group-hover:text-blue-700 transition-colors">{g.title}</h4>
                          <div className="flex items-center gap-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                            <span className="flex items-center gap-1.5"><Tag size={12} className="text-blue-500" /> {g.category}</span>
                            <span className="flex items-center gap-1.5"><MapPin size={12} className="text-red-400" /> {g.location.area || 'Unknown Zone'}</span>
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-8">
                      <span className={`inline-flex items-center gap-1.5 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border ${priorityStyles[g.priority]}`}>
                        <ShieldAlert size={12} />
                        {g.priority}
                      </span>
                    </td>
                    <td className="px-10 py-8">
                      {g.aiCategorized ? (
                        <div 
                          className="inline-flex items-center gap-2 px-4 py-2 bg-emerald-50 text-emerald-700 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-emerald-100 shadow-sm"
                        >
                          <Sparkles size={14} className="animate-pulse" />
                          AI Verified
                        </div>
                      ) : (
                        <button 
                          onClick={() => handleManualVerify(g)}
                          disabled={verifyingId === g.id}
                          className="inline-flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-blue-100 hover:bg-blue-600 hover:text-white transition-all active:scale-95 disabled:opacity-50"
                        >
                          {verifyingId === g.id ? <Loader2 size={14} className="animate-spin" /> : <Activity size={14} />}
                          Run AI Audit
                        </button>
