const App: React.FC = () => {
  const [grievances, setGrievances] = useState<Grievance[]>(() => {
    const saved = localStorage.getItem('civic_grievances');
    return saved ? JSON.parse(saved) : INITIAL_GRIEVANCES;
  });

  useEffect(() => {
    localStorage.setItem('civic_grievances', JSON.stringify(grievances));
  }, [grievances]);

  const addGrievance = (g: Grievance) => {
    setGrievances(prev => [g, ...prev]);
  };

  const updateGrievance = (id: string, updates: Partial<Grievance>) => {
    setGrievances(prev => prev.map(g => 
      g.id === id ? { ...g, ...updates, updatedAt: new Date().toISOString() } : g
    ));
  };

  const updateGrievanceStatus = (id: string, status: IssueStatus) => {
    updateGrievance(id, { status });
  };

  const toggleUpvote = (id: string) => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        const alreadyVoted = g.votedByMe;
        return {
          ...g,
          upvotes: alreadyVoted ? g.upvotes - 1 : g.upvotes + 1,
          votedByMe: !alreadyVoted
        };
      }
      return g;
    }));
  };

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-white">
        <Navbar />
        <main className="flex-grow pt-16">
          <Routes>
            <Route path="/" element={<HomePage grievances={grievances} />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/report" element={<ReportPage grievances={grievances} onAdd={addGrievance} />} />
            <Route path="/track" element={<TrackPage grievances={grievances} onUpvote={toggleUpvote} />} />
            <Route path="/admin" element={<AdminPage grievances={grievances} onUpdateStatus={updateGrievanceStatus} onUpdateGrievance={updateGrievance} />} />
            <Route path="/contact" element={<ContactPage />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  Filter, 
  MapPin, 
  Tag, 
  ArrowUpRight,
  MoreVertical,
  Download,
  Search,
  CheckCircle,
  Clock,
  AlertTriangle,
  Sparkles,
  TrendingUp,
  Inbox,
  ShieldAlert,
  Info,
  Activity,
  CheckCircle2,
  XCircle,
  Wrench,
  Loader2,
  ChevronDown
} from 'lucide-react';
import { Grievance, IssueCategory, IssueStatus, IssuePriority } from '../types';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  onUpdateStatus: (id: string, status: IssueStatus) => void;
  onUpdateGrievance?: (id: string, updates: Partial<Grievance>) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances, onUpdateStatus, onUpdateGrievance }) => {
  const [filterCategory, setFilterCategory] = useState<string>('All');
  const [filterStatus, setFilterStatus] = useState<string>('All');
  const [filterPriority, setFilterPriority] = useState<string>('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [verifyingId, setVerifyingId] = useState<string | null>(null);

  const filtered = grievances.filter(g => {
    const matchesCategory = filterCategory === 'All' || g.category === filterCategory;
    const matchesStatus = filterStatus === 'All' || g.status === filterStatus;
    const matchesPriority = filterPriority === 'All' || g.priority === filterPriority;
    const matchesSearch = g.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          g.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          g.description.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesStatus && matchesSearch && matchesPriority;
  });

  const stats = [
    { label: 'Active Reports', count: grievances.length, icon: <Inbox />, color: 'bg-blue-600', trend: '+12%' },
    { label: 'Pending Action', count: grievances.filter(g => g.status === IssueStatus.SUBMITTED).length, icon: <Clock />, color: 'bg-orange-600', trend: '-2%' },
    { label: 'Success Rate', count: Math.round((grievances.filter(g => g.status === IssueStatus.RESOLVED).length / (grievances.length || 1)) * 100) + '%', icon: <CheckCircle />, color: 'bg-green-600', trend: '+5%' },
    { label: 'Critical Issues', count: grievances.filter(g => g.priority === IssuePriority.CRITICAL).length, icon: <AlertTriangle />, color: 'bg-red-600', trend: 'Priority' }
  ];

  const priorityStyles = {
    [IssuePriority.LOW]: 'bg-slate-50 text-slate-500 border-slate-100',
    [IssuePriority.MEDIUM]: 'bg-blue-50 text-blue-600 border-blue-100',
    [IssuePriority.HIGH]: 'bg-orange-50 text-orange-600 border-orange-100',
    [IssuePriority.CRITICAL]: 'bg-red-50 text-red-600 border-red-100'
  };

  const statusIcons = {
    [IssueStatus.SUBMITTED]: <Clock size={16} />,
    [IssueStatus.IN_PROGRESS]: <Wrench size={16} />,
    [IssueStatus.RESOLVED]: <CheckCircle2 size={16} />,
    [IssueStatus.REJECTED]: <XCircle size={16} />
  };

  const handleExportCSV = () => {
    if (grievances.length === 0) {
      alert("No data available to export.");
      return;
    }

    const headers = ["ID", "Title", "Category", "Priority", "Status", "Address", "Area", "Created At", "Upvotes"];
    const rows = grievances.map(g => [
      g.id,
      `"${g.title.replace(/"/g, '""')}"`,
      g.category,
      g.priority,
      g.status,
      `"${(g.location.address || '').replace(/"/g, '""')}"`,
      g.location.area || '',
      new Date(g.createdAt).toLocaleString(),
      g.upvotes
    ]);

    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `civic_connect_export_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleManualVerify = async (g: Grievance) => {
    setVerifyingId(g.id);
    try {
      const result = await aiService.categorizeIssue(g.description);
      // ACTUAL STATE UPDATE: update the grievance in the global system
      if (onUpdateGrievance) {
        onUpdateGrievance(g.id, {
          category: result.category,
          priority: result.priority,
          aiCategorized: true
        });
        alert(`AI Analysis Complete!\n\nSystem Updated To:\nCategory: ${result.category}\nPriority: ${result.priority}\n\nAI Reasoning: ${result.reasoning}`);
      }
    } catch (e) {
      alert("AI Analysis failed. Please check your connection.");
    } finally {
      setVerifyingId(null);
    }
  };

  const handleMoreClick = (g: Grievance) => {
    alert(`Case Detail: ${g.id}\nCategory: ${g.category}\nFull Description: ${g.description}\nLocation: ${g.location.address}`);
  };

  return (
    <div className="bg-[#fcfcfd] min-h-screen pb-20 animate-fadeIn">
      {/* Dashboard Header */}
      <div className="bg-white border-b border-gray-100 pt-16 pb-12 mb-10 shadow-sm shadow-gray-100/50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-12">
            <div>
              <div className="flex items-center gap-3 mb-3">
                <span className="bg-blue-100 text-blue-700 text-[10px] font-black px-3 py-1 rounded-lg uppercase tracking-widest">Authority Portal</span>
                <span className="text-gray-300">•</span>
                <span className="text-gray-400 text-[10px] font-bold uppercase tracking-widest">Digital Command Center</span>
              </div>
              <h1 className="text-4xl font-black text-gray-900 tracking-tight">Municipal Operations</h1>
            </div>
            <button 
              onClick={handleExportCSV}
              className="bg-gray-900 text-white px-8 py-4 rounded-2xl font-black text-sm flex items-center gap-3 hover:bg-black transition-all shadow-xl shadow-gray-200 active:scale-95"
            >
              <Download size={18} />
              Export Dataset
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {stats.map((stat, i) => (
              <div key={i} className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm relative overflow-hidden group hover:shadow-xl hover:shadow-blue-900/5 transition-all">
                <div className="absolute -right-4 -top-4 w-24 h-24 bg-gray-50 rounded-full opacity-50 group-hover:scale-150 transition-transform duration-700" />
                <div className="relative flex justify-between items-start mb-6">
                  <div className={`p-4 rounded-2xl text-white ${stat.color} shadow-lg shadow-current/20`}>
                    {React.cloneElement(stat.icon as React.ReactElement<any>, { size: 24 })}
                  </div>
                  <div className="flex flex-col items-end">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{stat.label}</span>
                    <div className="text-3xl font-black text-gray-900">{stat.count}</div>
                  </div>
                </div>
                <div className="flex items-center gap-2 text-[10px] font-bold text-green-500">
                  <TrendingUp size={12} />
                  <span>{stat.trend} week-on-week</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4">
        {/* Advanced Filters */}
        <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm mb-10 flex flex-wrap items-center gap-6">
          <div className="relative flex-grow min-w-[300px]">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input 
