                          className="inline-flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-blue-100 hover:bg-blue-600 hover:text-white transition-all active:scale-95 disabled:opacity-50"
                        >
                          {verifyingId === g.id ? <Loader2 size={14} className="animate-spin" /> : <Sparkles size={14} />}
                          AI Audit
                        </button>
                      )}
                    </td>
                    <td className="px-10 py-8 text-right">
                      <div className="flex items-center justify-end gap-3">
                        <div className={`relative flex items-center gap-3 px-5 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest text-white shadow-md transition-all ${statusColors[g.status]} ${updatingId === g.id ? 'opacity-50' : 'hover:scale-105'}`}>
                          {updatingId === g.id ? <RefreshCw size={16} className="animate-spin" /> : statusIcons[g.status]}

                          <select 
                            className="bg-transparent outline-none cursor-pointer pr-4 appearance-none relative z-10"
                            value={g.status}
                            onChange={(e) => handleStatusChange(g.id, e.target.value as IssueStatus)}
                          >
                            {Object.values(IssueStatus).map(st => (
                              <option key={st} value={st} className="bg-white text-gray-900">{st}</option>
                            ))}
                          </select>
                          <ChevronDown size={14} className="pointer-events-none absolute right-4 opacity-50" />
                        </div>
                        <button 
                          onClick={() => handleMoreClick(g)}
                          className="p-3.5 bg-gray-50 hover:bg-white rounded-2xl text-gray-400 hover:text-blue-600 transition-all hover:shadow-lg border border-gray-100 active:scale-95"
                        >
                          <ArrowUpRight size={20} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {filtered.length === 0 && (
            <div className="p-32 text-center">
              <div className="w-24 h-24 bg-gray-50 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 text-gray-200">
                <Search size={48} />
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-3 tracking-tight">Empty Records</h3>
              <p className="text-gray-400 font-medium max-w-xs mx-auto">No reports match your current filter settings.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdminPage;

