diffs.replacement:
import React, { useState, useRef, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { 
  Camera, 
  MapPin, 
  Send, 
  Loader2, 
  CheckCircle,
  Sparkles,
  ArrowLeft,
  Image as ImageIcon,
  AlertCircle,
  X,
  ShieldAlert,
  ChevronDown,
  Mic,
  MicOff,
  Search,
  Map as MapIcon,
  Navigation,
  FileSearch,
  CheckCircle2
} from 'lucide-react';
import { IssueCategory, IssueStatus, IssuePriority, Grievance, Location } from '../types';
import { aiService } from '../services/geminiService';

interface ReportPageProps {
  grievances: Grievance[];
  onAdd: (g: Grievance) => void;
}

const ReportPage: React.FC<ReportPageProps> = ({ grievances, onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [locationLoading, setLocationLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [duplicateReport, setDuplicateReport] = useState<Grievance | null>(null);
  const [generatedId] = useState(`GRV-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 8999)}`);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    priority: IssuePriority.MEDIUM,
    description: '',
    image: '',
    location: null as Location | null
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, priority: string, reasoning: string } | null>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.lang = 'en-US';
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setForm(prev => ({ 
          ...prev, 
          description: (prev.description + " " + transcript).trim() 
        }));
      };
      recognitionRef.current = recognition;
    }
    return () => { if (recognitionRef.current) recognitionRef.current.stop(); };
  }, []);

  const toggleVoiceInput = (e: React.MouseEvent) => {
    e.preventDefault();
    if (!recognitionRef.current) {
      alert("Speech recognition is not supported in this browser.");
      return;
    }
    if (isListening) { recognitionRef.current.stop(); } 
    else { recognitionRef.current.start(); }
  };

  const handleLocation = () => {
    if (!("geolocation" in navigator)) {
      alert("Geolocation is not supported by your browser.");
      return;
    }
    setLocationLoading(true);
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const lat = position.coords.latitude;
        const lng = position.coords.longitude;
        setForm(prev => ({
          ...prev,
          location: {
            latitude: lat,
            longitude: lng,
            address: `Lat: ${lat.toFixed(5)}, Lng: ${lng.toFixed(5)}`,
            area: "GPS Verified Zone"
          }
        }));
        setLocationLoading(false);
      },
      (error) => {
        setLocationLoading(false);
        switch(error.code) {
          case error.PERMISSION_DENIED:
            alert("Location access denied. Please enable GPS permissions in your browser.");
            break;
          case error.POSITION_UNAVAILABLE:
            alert("Location information is unavailable.");
            break;
          case error.TIMEOUT:
            alert("The request to get user location timed out.");
            break;
          default:
            alert("An unknown error occurred while fetching location.");
            break;
        }
      },
      { enableHighAccuracy: true, timeout: 8000 }
    );
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 15) return;
    setAnalyzing(true);
    try {
      const result = await aiService.categorizeIssue(form.description);
      setForm(prev => ({ ...prev, category: result.category, priority: result.priority }));
      setAiInsight({ category: result.category, priority: result.priority, reasoning: result.reasoning });
      const duplicate = await aiService.detectDuplicates(form.description, grievances);
      setDuplicateReport(duplicate);
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleSubmit = () => {
    if (!form.location) return;
    setLoading(true);
    const newGrievance: Grievance = {
      id: generatedId,
      title: form.title || `${form.category} Report`,
      category: form.category,
      priority: form.priority,
      description: form.description,
      image: form.image,
      location: form.location,
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight,
      upvotes: 0
    };

    setTimeout(() => {
      onAdd(newGrievance);
      setLoading(false);
      setSuccess(true);
      setTimeout(() => navigate('/track'), 2500);
    }, 1500);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-40 animate-fadeIn min-h-[70vh] bg-white text-center px-4">
        <div className="bg-emerald-100 text-emerald-600 p-8 rounded-[2.5rem] mb-8 shadow-xl animate-bounce">
          <CheckCircle2 size={80} />
        </div>
        <h2 className="text-4xl font-black text-gray-900 mb-4 tracking-tight">Report Logged Successfully</h2>
        <p className="text-gray-500 font-medium mb-8">Case Reference: <span className="text-blue-600 font-black">{generatedId}</span></p>
        <div className="flex items-center gap-3 px-6 py-3 bg-blue-50 text-blue-700 rounded-2xl font-bold text-sm">
          <Loader2 size={18} className="animate-spin" />
          Synchronizing with Municipal Portal...
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto px-4 py-16 animate-fadeIn">
      {/* Step Indicator */}
      <div className="mb-16 flex items-center justify-between px-6 relative">
        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-gray-100 -translate-y-1/2 z-0"></div>
        {[1, 2, 3].map((s) => (
          <div key={s} className="relative z-10 flex flex-col items-center gap-3">
            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg transition-all duration-500 ${
              step === s ? 'bg-blue-600 text-white shadow-xl shadow-blue-200 scale-110' : 
              step > s ? 'bg-emerald-500 text-white shadow-lg' : 'bg-white text-gray-300 border-2 border-gray-100'
            }`}>
              {step > s ? <CheckCircle size={20} /> : s}
            </div>
            <span className={`text-[10px] font-black uppercase tracking-widest ${step >= s ? 'text-gray-900' : 'text-gray-400'}`}>
              {s === 1 ? 'Describe' : s === 2 ? 'Evidence' : 'Review'}
            </span>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 md:p-14 rounded-[3.5rem] shadow-2xl border border-gray-50 overflow-hidden">
        {step === 1 && (
          <div className="space-y-8 animate-slideLeft">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <FileSearch className="text-blue-600" size={24} />
                <h2 className="text-3xl font-black text-gray-900 tracking-tight">Issue Details</h2>
              </div>
              <p className="text-gray-400 font-medium text-sm mb-10 leading-relaxed">Describe the civic issue accurately. Use your voice to dictate the details if you're on the move.</p>

              <div className="space-y-8">
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Title or Summary</label>
                  <input 
                    type="text"
                    placeholder="E.g., Major leak on Park Road"
                    className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-100 focus:bg-white transition-all font-bold text-gray-800 placeholder:text-gray-300"
                    value={form.title}
                    onChange={e => setForm({...form, title: e.target.value})}
                  />
                </div>

                <div className="relative">
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Full Description</label>
                  <textarea 
                    rows={4}
                    placeholder="Provide as much detail as possible for the engineering team..."
                    className="w-full px-8 py-6 rounded-[2.5rem] bg-gray-50 border-2 border-transparent focus:border-blue-100 focus:bg-white transition-all font-medium text-gray-800 leading-relaxed placeholder:text-gray-300"
                    value={form.description}
                    onChange={e => setForm({...form, description: e.target.value})}
                    onBlur={runAiAnalysis}
                  />
                  <button 
                    type="button"
                    onClick={toggleVoiceInput}
                    className={`absolute right-6 bottom-6 w-14 h-14 rounded-[1.5rem] flex items-center justify-center transition-all shadow-xl active:scale-95 ${
                      isListening ? 'bg-red-500 text-white animate-pulse ring-8 ring-red-100' : 'bg-white text-gray-400 hover:text-blue-600 border border-gray-100'
                    }`}
                  >
                    {isListening ? <MicOff size={24} /> : <Mic size={24} />}
                  </button>
                </div>

                {duplicateReport && (
                  <div className="bg-orange-50 border border-orange-100 p-8 rounded-[2.5rem] flex flex-col gap-5 animate-slideUp">
                    <div className="flex items-center gap-3 text-orange-700 font-black text-sm">
                      <AlertCircle size={24} />
                      Duplicate Warning
                    </div>
                    <p className="text-orange-900/70 text-xs font-medium leading-relaxed">
                      A report titled <strong>"{duplicateReport.title}"</strong> exists in this zone. You may want to support it instead of creating a new entry.
                    </p>
                    <Link to="/track" className="bg-orange-600 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest text-center hover:bg-orange-700 transition-all shadow-lg shadow-orange-200">
                      View Existing Report
                    </Link>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Category</label>
                    <div className="relative">
                      <select 
                        className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-100 transition-all font-bold text-gray-800 appearance-none cursor-pointer"
                        value={form.category}
                        onChange={e => setForm({...form, category: e.target.value as IssueCategory})}
                      >
                        {Object.values(IssueCategory).map(cat => (
                          <option key={cat} value={cat}>{cat}</option>
                        ))}
                      </select>
                      <ChevronDown className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400" size={20} />
                    </div>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">System Priority</label>
                    <div className={`w-full px-8 py-5 rounded-3xl font-black text-sm border-2 transition-all flex items-center gap-3 ${
                      form.priority === IssuePriority.CRITICAL ? 'bg-red-50 border-red-100 text-red-600' :
                      form.priority === IssuePriority.HIGH ? 'bg-orange-50 border-orange-100 text-orange-600' :
                      'bg-blue-50 border-blue-100 text-blue-600'
                    }`}>
                      <ShieldAlert size={18} />
                      {form.priority}
                    </div>
                  </div>
                </div>

                {analyzing ? (
                  <div className="flex items-center gap-4 text-blue-600 font-black text-xs p-6 bg-blue-50 rounded-[2rem] border border-blue-100 animate-pulse">
                    <Loader2 size={24} className="animate-spin" />
                    AI AGENT: Categorizing issue and scanning for duplicates...
                  </div>
                ) : aiInsight && (
                  <div className="bg-gray-900 text-white p-8 rounded-[2.5rem] animate-slideUp shadow-2xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-10">
                      <Sparkles size={100} />
                    </div>
                    <div className="relative z-10">
                      <div className="flex items-center gap-2 mb-4">
                        <Sparkles size={16} className="text-blue-400" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-blue-400">Civic AI Insights</span>
                      </div>
                      <p className="text-gray-300 text-xs font-medium leading-relaxed italic">"{aiInsight.reasoning}"</p>
                    </div>
                  </div>
                )}
              </div>
            </div>

            <button 
              disabled={form.description.length < 15 || analyzing}
              onClick={() => setStep(2)}
              className="w-full py-6 rounded-3xl bg-blue-600 text-white font-black hover:bg-blue-700 disabled:opacity-30 transition-all shadow-2xl shadow-blue-500/20 active:scale-95 flex items-center justify-center gap-3"
            >
              Continue to Evidence
              <ArrowLeft className="rotate-180" size={20} />
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-10 animate-slideLeft">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <Navigation className="text-blue-600" size={24} />
                <h2 className="text-3xl font-black text-gray-900 tracking-tight">Proof & GPS</h2>
              </div>
              <p className="text-gray-400 font-medium text-sm mb-10 leading-relaxed">Capture a clear photo and lock your GPS location for faster resolution.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="aspect-square bg-gray-50 rounded-[3rem] border-4 border-dashed border-gray-100 flex flex-col items-center justify-center cursor-pointer hover:bg-blue-50/50 transition-all relative overflow-hidden group shadow-inner"
              >
                {form.image ? (
                  <img src={form.image} className="w-full h-full object-cover" alt="Preview" />
                ) : (
                  <div className="text-center text-gray-300 group-hover:text-blue-600 transition-colors">
                    <Camera size={48} className="mx-auto mb-4" />
                    <span className="text-[10px] font-black uppercase tracking-widest">Snap or Upload Proof</span>
                  </div>
                )}
                <input ref={fileInputRef} type="file" className="hidden" onChange={handleFileChange} accept="image/*" />
              </div>

              <div className="flex flex-col gap-6">
                <button 
                  onClick={handleLocation}
                  className={`flex-grow rounded-[3rem] flex flex-col items-center justify-center transition-all border-4 border-dashed active:scale-95 relative overflow-hidden ${
                    form.location ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-blue-50 text-blue-700 border-blue-100 shadow-xl'
                  }`}
                >
                  {locationLoading ? <Loader2 className="animate-spin" size={48} /> : (form.location ? <MapIcon size={48} /> : <MapPin size={48} />)}
                  <span className="text-[10px] font-black uppercase mt-4 tracking-widest">
                    {form.location ? 'GPS Location Locked' : 'Auto Detect Location'}
                  </span>
                  {form.location && (
                    <div className="mt-4 px-4 py-2 bg-emerald-100 rounded-full text-[9px] font-black uppercase">
                      {form.location.address}
                    </div>
                  )}
                </button>
                <div className="p-6 bg-gray-50 rounded-[2rem] border border-gray-100">
                  <div className="flex items-center gap-3 text-[10px] font-black uppercase tracking-widest text-gray-400">
                    <ShieldAlert size={14} className="text-orange-500" />
                    Security Notice
                  </div>
                  <p className="text-[10px] text-gray-400 mt-2 font-medium">Your data is transmitted over a secure channel directly to municipal servers.</p>
                </div>
              </div>
            </div>

            <div className="flex gap-4 pt-4">
              <button onClick={() => setStep(1)} className="w-24 py-6 bg-gray-100 rounded-[2rem] text-gray-500 hover:bg-gray-200 transition-colors shadow-sm"><ArrowLeft className="mx-auto" /></button>
              <button 
                disabled={!form.location} 
                onClick={() => setStep(3)} 
                className="flex-grow py-6 bg-blue-600 text-white rounded-[2rem] font-black hover:bg-blue-700 active:scale-95 shadow-2xl shadow-blue-500/30 flex items-center justify-center gap-3"
              >
                Review Report Summary
                <ArrowLeft className="rotate-180" size={20} />
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-10 animate-slideLeft">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <FileSearch className="text-blue-600" size={24} />
                <h2 className="text-3xl font-black text-gray-900 tracking-tight">Final Verification</h2>
              </div>
              <p className="text-gray-400 font-medium text-sm mb-10 leading-relaxed">Review the details before final submission to city authorities.</p>
            </div>

            <div className="bg-white rounded-[3rem] border border-gray-100 shadow-2xl overflow-hidden">
              {/* Review Header */}
              <div className="bg-gray-900 p-8 text-white flex justify-between items-center">
                <div>
                  <span className="text-[9px] font-black uppercase tracking-[0.2em] text-blue-400 block mb-1">Generated Tracking ID</span>
                  <h4 className="text-2xl font-black tracking-tighter">{generatedId}</h4>
                </div>
                <div className="px-4 py-2 bg-white/10 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/20">
                  Step 3 of 3
                </div>
              </div>

              {/* Review Body */}
              <div className="p-10 space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <div className="space-y-6">
                    <div>
                      <h5 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Description</h5>
                      <p className="text-gray-900 font-bold leading-relaxed italic text-lg">"{form.description}"</p>
                    </div>
                    <div className="flex flex-wrap gap-3">
                      <div className="px-4 py-2 bg-blue-50 text-blue-700 rounded-xl text-[10px] font-black uppercase tracking-widest border border-blue-100">
                        {form.category}
                      </div>
                      <div className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border ${
                        form.priority === IssuePriority.CRITICAL ? 'bg-red-50 text-red-700 border-red-100' : 'bg-gray-50 text-gray-600 border-gray-100'
                      }`}>
                        {form.priority} Priority
                      </div>
                    </div>
                    <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100">
                      <div className="flex items-center gap-3 text-slate-500 mb-3">
                        <MapPin size={18} />
                        <span className="text-[10px] font-black uppercase tracking-widest">GPS Coordinates</span>
                      </div>
                      <p className="text-sm font-black text-slate-900">{form.location?.address}</p>
                    </div>
                  </div>
                  {form.image && (
                    <div className="relative">
                      <h5 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Attached Proof</h5>
                      <div className="rounded-[2.5rem] overflow-hidden shadow-2xl border-8 border-gray-50">
                        <img src={form.image} className="w-full aspect-square object-cover" alt="Verification Proof" />
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>

            <div className="flex gap-4 pt-6">
              <button onClick={() => setStep(2)} className="w-24 py-6 bg-gray-100 rounded-[2rem] text-gray-500 hover:bg-gray-200 transition-colors shadow-sm"><ArrowLeft className="mx-auto" /></button>
              <button 
                disabled={loading} 
                onClick={handleSubmit} 
                className="flex-grow py-6 bg-green-600 text-white rounded-[2rem] font-black flex items-center justify-center gap-4 hover:bg-green-700 shadow-2xl shadow-green-500/30 active:scale-95"
              >
                {loading ? <Loader2 size={24} className="animate-spin" /> : <CheckCircle size={24} />}
                Submit Formal Grievance
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

