import React, { useState, useRef, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { 
  Camera, 
  MapPin, 
  Send, 
  Loader2, 
  CheckCircle,
  Sparkles,
  ArrowLeft,
  Image as ImageIcon,
  AlertCircle,
  X,
  ShieldAlert,
  ChevronDown,
  Mic,
  MicOff,
  Search,
  Map as MapIcon,
  Navigation,
  FileSearch,
  CheckCircle2,
  QrCode,
  FileCheck
} from 'lucide-react';
import { IssueCategory, IssueStatus, IssuePriority, Grievance, Location } from '../types';
import { aiService } from '../services/geminiService';

interface ReportPageProps {
  grievances: Grievance[];
  onAdd: (g: Grievance) => void;
}

const ReportPage: React.FC<ReportPageProps> = ({ grievances, onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [locationLoading, setLocationLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [duplicateReport, setDuplicateReport] = useState<Grievance | null>(null);
  const [generatedId] = useState(`GRV-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 8999)}`);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    priority: IssuePriority.MEDIUM,
    description: '',
    image: '',
    location: null as Location | null
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, priority: string, reasoning: string } | null>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.lang = 'en-US';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setForm(prev => ({ ...prev, description: (prev.description + " " + transcript).trim() }));
      };
      recognitionRef.current = recognition;
    }
  }, []);

  const toggleVoiceInput = (e: React.MouseEvent) => {
    e.preventDefault();
    if (isListening) recognitionRef.current?.stop();
    else recognitionRef.current?.start();
  };

  const handleLocation = () => {
    if (!("geolocation" in navigator)) {
      alert("Geolocation is not supported. Using demo coordinates.");
      simulateLocation();
      return;
    }
    setLocationLoading(true);
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const lat = position.coords.latitude;
        const lng = position.coords.longitude;
        setForm(prev => ({
          ...prev,
          location: {
            latitude: lat,
            longitude: lng,
            address: `${lat.toFixed(5)}, ${lng.toFixed(5)}`,
            area: "GPS Verified"
          }
        }));
        setLocationLoading(false);
      },
      () => {
        setLocationLoading(false);
        alert("Location access denied. Using simulated coordinates for demo purposes.");
        simulateLocation();
      },
      { enableHighAccuracy: true, timeout: 5000 }
    );
  };

  const simulateLocation = () => {
    // Standard Demo Coordinates (e.g., City Hall)
    setForm(prev => ({
      ...prev,
      location: {
        latitude: 40.7128,
        longitude: -74.0060,
        address: "40.7128° N, 74.0060° W",
        area: "Municipal Zone (Simulated)"
      }
    }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 10) return;
    setAnalyzing(true);
    try {
      const result = await aiService.categorizeIssue(form.description);
      setForm(prev => ({ ...prev, category: result.category, priority: result.priority }));
      setAiInsight({ category: result.category, priority: result.priority, reasoning: result.reasoning });
    } catch (e) {
      console.error("AI Analysis skipped", e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleSubmit = () => {
    setLoading(true);
    const newGrievance: Grievance = {
      id: generatedId,
      title: form.title || `${form.category} Issue`,
      category: form.category,
      priority: form.priority,
      description: form.description,
      image: form.image,
      location: form.location || { latitude: 0, longitude: 0, address: "Manual Entry" },
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight,
      upvotes: 0
    };

    // Simulate server delay for professional feel
    setTimeout(() => {
      onAdd(newGrievance);
      setLoading(false);
      setSuccess(true);
      // Auto redirect to tracker
      setTimeout(() => navigate('/track'), 3000);
    }, 2000);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-40 animate-fadeIn min-h-[70vh] bg-white text-center px-4">
        <div className="bg-emerald-100 text-emerald-600 p-8 rounded-[2.5rem] mb-8 shadow-xl animate-bounce">
          <CheckCircle2 size={80} />
        </div>
        <h2 className="text-4xl font-black text-gray-900 mb-4 tracking-tight">Grievance Locked!</h2>
        <p className="text-gray-500 font-medium mb-8">Reference ID: <span className="text-blue-600 font-black">{generatedId}</span></p>
        <div className="flex items-center gap-3 px-6 py-3 bg-blue-50 text-blue-700 rounded-2xl font-bold text-sm">
          <Loader2 size={18} className="animate-spin" />
          Navigating to live tracker...
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-16 animate-fadeIn">
      {/* Header Info */}
      <div className="text-center mb-16">
        <h1 className="text-4xl font-black text-gray-900 tracking-tight mb-4">Lodge a Grievance</h1>
        <p className="text-gray-500 font-medium">Follow the 3-step secure submission process below.</p>
      </div>

      {/* Step Indicator */}
      <div className="mb-16 flex items-center justify-between px-10 relative">
        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-gray-100 -translate-y-1/2 z-0"></div>
        {[1, 2, 3].map((s) => (
          <div key={s} className="relative z-10 flex flex-col items-center gap-3">
            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-lg transition-all duration-500 ${
              step === s ? 'bg-blue-600 text-white shadow-2xl shadow-blue-200 scale-110' : 
              step > s ? 'bg-emerald-500 text-white shadow-lg' : 'bg-white text-gray-300 border-2 border-gray-100'
            }`}>
              {step > s ? <CheckCircle size={24} /> : s}
            </div>
            <span className={`text-[10px] font-black uppercase tracking-widest ${step >= s ? 'text-gray-900' : 'text-gray-400'}`}>
              {s === 1 ? 'Describe' : s === 2 ? 'Attach' : 'Verify'}
            </span>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 md:p-14 rounded-[3.5rem] shadow-2xl border border-gray-50">
        {step === 1 && (
          <div className="space-y-10 animate-slideLeft">
            <div className="space-y-8">
              <div>
                <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">What is the problem?</label>
                <input 
                  type="text"
                  placeholder="Summarize the issue (e.g., Pothole on Sector 4)"
                  className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-100 focus:bg-white transition-all font-bold text-gray-800 placeholder:text-gray-300"
                  value={form.title}
                  onChange={e => setForm({...form, title: e.target.value})}
                />
              </div>

              <div className="relative">
                <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Detailed Context</label>
                <textarea 
                  rows={4}
                  placeholder="Explain exactly where and what the issue is..."
                  className="w-full px-8 py-6 rounded-[2.5rem] bg-gray-50 border-2 border-transparent focus:border-blue-100 focus:bg-white transition-all font-medium text-gray-800 leading-relaxed placeholder:text-gray-300"
                  value={form.description}
                  onChange={e => setForm({...form, description: e.target.value})}
                  onBlur={runAiAnalysis}
                />
                <button 
                  type="button"
                  onClick={toggleVoiceInput}
                  className={`absolute right-6 bottom-6 w-14 h-14 rounded-[1.5rem] flex items-center justify-center transition-all shadow-xl active:scale-95 ${
                    isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-white text-gray-400 hover:text-blue-600 border border-gray-100'
                  }`}
                >
                  {isListening ? <MicOff size={24} /> : <Mic size={24} />}
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Primary Category</label>
                  <div className="relative">
                    <select 
                      className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-100 transition-all font-bold text-gray-800 appearance-none cursor-pointer"
                      value={form.category}
                      onChange={e => setForm({...form, category: e.target.value as IssueCategory})}
                    >
                      {Object.values(IssueCategory).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <ChevronDown className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400" size={20} />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Priority Level</label>
                  <div className={`w-full px-8 py-5 rounded-3xl font-black text-sm border-2 flex items-center gap-3 ${
                    form.priority === IssuePriority.CRITICAL ? 'bg-red-50 border-red-100 text-red-600' : 'bg-blue-50 border-blue-100 text-blue-600'
                  }`}>
                    <ShieldAlert size={18} /> {form.priority}
                  </div>
                </div>
              </div>
            </div>

            <button 
              disabled={form.description.length < 5 || analyzing}
              onClick={() => setStep(2)}
              className="w-full py-6 rounded-3xl bg-blue-600 text-white font-black hover:bg-blue-700 shadow-2xl shadow-blue-500/20 active:scale-95 flex items-center justify-center gap-3 transition-all"
            >
              Continue to Attachments
              <ArrowLeft className="rotate-180" size={20} />
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-10 animate-slideLeft">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              {/* Evidence Upload */}
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="aspect-square bg-gray-50 rounded-[3rem] border-4 border-dashed border-gray-100 flex flex-col items-center justify-center cursor-pointer hover:bg-blue-50/50 transition-all relative overflow-hidden group"
              >
                {form.image ? (
                  <img src={form.image} className="w-full h-full object-cover" alt="Evidence" />
                ) : (
                  <div className="text-center text-gray-300 group-hover:text-blue-600 transition-colors">
                    <Camera size={48} className="mx-auto mb-4" />
                    <span className="text-[10px] font-black uppercase tracking-widest">Snap Proof Image</span>
                  </div>
                )}
                <input ref={fileInputRef} type="file" className="hidden" onChange={handleFileChange} accept="image/*" />
              </div>

              {/* Location Selector */}
              <div className="flex flex-col gap-6">
                <button 
                  onClick={handleLocation}
                  disabled={locationLoading}
                  className={`flex-grow rounded-[3rem] flex flex-col items-center justify-center transition-all border-4 border-dashed active:scale-95 relative overflow-hidden ${
                    form.location ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-blue-50 text-blue-700 border-blue-100 shadow-xl'
                  }`}
                >
                  {locationLoading ? <Loader2 className="animate-spin" size={48} /> : (form.location ? <CheckCircle size={48} /> : <MapPin size={48} />)}
                  <span className="text-[10px] font-black uppercase mt-4 tracking-widest text-center px-4">
                    {form.location ? `Locked: ${form.location.area}` : 'Auto-Detect Geo-Tag'}
                  </span>
                </button>
                <div className="p-6 bg-gray-50 rounded-[2rem] border border-gray-100 flex items-center gap-4">
                  <ShieldAlert className="text-orange-500 flex-shrink-0" />
                  <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tight">Geo-Tagging ensures authorities can pinpoint the exact site.</p>
                </div>
              </div>
            </div>

            <div className="flex gap-4">
              <button onClick={() => setStep(1)} className="w-24 py-6 bg-gray-100 rounded-[2.5rem] text-gray-500 hover:bg-gray-200 transition-all"><ArrowLeft className="mx-auto" /></button>
              <button 
                onClick={() => setStep(3)} 
                className="flex-grow py-6 bg-blue-600 text-white rounded-[2.5rem] font-black hover:bg-blue-700 shadow-2xl shadow-blue-500/20 flex items-center justify-center gap-3 transition-all"
              >
                Review Report Summary
                <ArrowLeft className="rotate-180" size={20} />
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="animate-slideLeft">
            <div className="bg-gray-50 rounded-[3rem] border border-gray-100 overflow-hidden shadow-xl mb-10">
              {/* Report Voucher Header */}
              <div className="bg-gray-900 p-10 text-white flex justify-between items-center relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-10">
                  <QrCode size={120} />
                </div>
                <div className="relative z-10">
                  <span className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-400 block mb-2">Municipal Case File</span>
                  <h4 className="text-3xl font-black tracking-tighter">{generatedId}</h4>
                </div>
                <div className="relative z-10 px-6 py-3 bg-white/10 rounded-2xl border border-white/20 text-[10px] font-black uppercase tracking-widest">
                  Draft Pending
                </div>
              </div>

              {/* Report Body */}
              <div className="p-10 space-y-12">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                  <div className="space-y-10">
                    <div className="group">
                      <label className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">
                        <FileCheck size={14} className="text-blue-500" /> Subject & Details
                      </label>
                      <h5 className="text-2xl font-black text-gray-900 mb-3 tracking-tight">{form.title || "Untitled Grievance"}</h5>
                      <p className="text-gray-500 font-medium leading-relaxed italic text-lg">"{form.description}"</p>
                    </div>

                    <div className="flex flex-wrap gap-4">
                      <div className="px-5 py-2.5 bg-blue-100 text-blue-700 rounded-xl text-[10px] font-black uppercase tracking-widest border border-blue-200">
                        {form.category}
                      </div>
                      <div className="px-5 py-2.5 bg-orange-100 text-orange-700 rounded-xl text-[10px] font-black uppercase tracking-widest border border-orange-200">
                        {form.priority} Priority
                      </div>
                    </div>

                    <div className="p-6 bg-white rounded-[2rem] border border-gray-100 shadow-sm">
                      <div className="flex items-center gap-3 text-gray-400 mb-2">
                        <MapPin size={18} />
                        <span className="text-[10px] font-black uppercase tracking-widest">Verified Site</span>
                      </div>
                      <p className="text-sm font-black text-gray-900">{form.location?.address || "Location Access Pending Final Sync"}</p>
                    </div>
                  </div>

                  <div className="relative">
                     <label className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">
                        <ImageIcon size={14} className="text-blue-500" /> Evidence Capture
                      </label>
                    <div className="aspect-square rounded-[3rem] overflow-hidden border-8 border-white shadow-2xl relative">
                      {form.image ? (
                        <img src={form.image} className="w-full h-full object-cover" alt="Final Review" />
                      ) : (
                        <div className="w-full h-full bg-gray-100 flex items-center justify-center text-gray-300 italic text-sm">
                          No visual evidence attached
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex gap-4">
              <button onClick={() => setStep(2)} className="w-24 py-6 bg-gray-100 rounded-[2.5rem] text-gray-500 hover:bg-gray-200 transition-all"><ArrowLeft className="mx-auto" /></button>
              <button 
                disabled={loading} 
                onClick={handleSubmit} 
                className="flex-grow py-6 bg-green-600 text-white rounded-[2.5rem] font-black flex items-center justify-center gap-4 hover:bg-green-700 shadow-2xl shadow-green-500/30 active:scale-95 transition-all"
              >
                {loading ? (
                  <>
                    <Loader2 size={24} className="animate-spin" />
                    Finalizing Submission...
                  </>
                ) : (
                  <>
                    <Send size={24} />
                    Confirm & Lodge Report
                  </>
                )}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

