interface ReportPageProps {
  grievances: Grievance[];
  onAdd: (g: Grievance) => void;
}

const ReportPage: React.FC<ReportPageProps> = ({ grievances, onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [locationLoading, setLocationLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [duplicateReport, setDuplicateReport] = useState<Grievance | null>(null);
  const [generatedId] = useState(`GRV-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 8999)}`);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    priority: IssuePriority.MEDIUM,
    description: '',
    image: '',
    location: null as Location | null,
    isEmergency: false
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, priority: string, reasoning: string } | null>(null);

  useEffect(() => {
    const handleOnlineStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleOnlineStatus);
    window.addEventListener('offline', handleOnlineStatus);

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.lang = 'en-US';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setForm(prev => ({ ...prev, description: (prev.description + " " + transcript).trim() }));
      };
      recognitionRef.current = recognition;
    }
    return () => {
      window.removeEventListener('online', handleOnlineStatus);
      window.removeEventListener('offline', handleOnlineStatus);
    };
  }, []);

  const toggleVoiceInput = (e: React.MouseEvent) => {
    e.preventDefault();
    if (isListening) recognitionRef.current?.stop();
    else recognitionRef.current?.start();
  };

  const handleLocation = () => {
    if (!("geolocation" in navigator)) {
      alert("Geolocation is not supported. Using demo coordinates.");
      simulateLocation();
      return;
    }
    setLocationLoading(true);
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const lat = position.coords.latitude;
        const lng = position.coords.longitude;
        setForm(prev => ({
          ...prev,
          location: {
            latitude: lat,
            longitude: lng,
            address: `${lat.toFixed(5)}, ${lng.toFixed(5)}`,
            area: "GPS Verified"
          }
        }));
        setLocationLoading(false);
      },
      () => {
        setLocationLoading(false);
        simulateLocation();
      },
      { enableHighAccuracy: true, timeout: 5000 }
    );
  };

  const simulateLocation = () => {
    setForm(prev => ({
      ...prev,
      location: {
        latitude: 40.7128,
        longitude: -74.0060,
        address: "40.7128° N, 74.0060° W",
        area: "Municipal Zone"
      }
    }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 10) return;
    setAnalyzing(true);
    try {
      const result = await aiService.categorizeIssue(form.description);
      setForm(prev => ({ ...prev, category: result.category, priority: result.priority }));
      setAiInsight({ category: result.category, priority: result.priority, reasoning: result.reasoning });
    } catch (e) {
      console.error("AI Analysis skipped", e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleSaveDraft = () => {
    const draft = { ...form, id: `DRAFT-${Date.now()}` };
    const savedDrafts = JSON.parse(localStorage.getItem('civic_drafts') || '[]');
    localStorage.setItem('civic_drafts', JSON.stringify([...savedDrafts, draft]));
    alert("Draft saved! It will auto-sync once you're back online.");
    navigate('/');
  };

  const handleSubmit = () => {
    setLoading(true);
    // Calculate SLA Deadline (e.g., 48h for Critical, 120h for Low)
    const hours = form.isEmergency ? 24 : (form.priority === IssuePriority.CRITICAL ? 48 : 120);
    const deadline = new Date();
    deadline.setHours(deadline.getHours() + hours);

    const newGrievance: Grievance = {
      id: generatedId,
      title: form.title || `${form.category} Issue`,
      category: form.category,
      priority: form.isEmergency ? IssuePriority.CRITICAL : form.priority,
      description: form.description,
      image: form.image,
      location: form.location || { latitude: 0, longitude: 0, address: "Manual Entry" },
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight,
      upvotes: 0,
      isEmergency: form.isEmergency,
      slaDeadline: deadline.toISOString()
    };

    setTimeout(() => {
      onAdd(newGrievance);
      setLoading(false);
      setSuccess(true);
      setTimeout(() => navigate('/track'), 3000);
    }, 2000);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-40 animate-fadeIn min-h-[70vh] bg-white text-center px-4">
        <div className="bg-emerald-100 text-emerald-600 p-8 rounded-[2.5rem] mb-8 shadow-xl animate-bounce">
          <CheckCircle2 size={80} />
        </div>
        <h2 className="text-4xl font-black text-gray-900 mb-4 tracking-tight">Case Locked!</h2>
        <p className="text-gray-500 font-medium mb-8">Ref: <span className="text-blue-600 font-black">{generatedId}</span></p>
        <div className="bg-blue-50 text-blue-700 px-6 py-4 rounded-2xl font-bold flex flex-col gap-2">
          <span>+50 Civic Points Earned! 🏆</span>
          <span className="text-xs opacity-70">Authorities will respond within 48 hours.</span>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-16 animate-fadeIn">
      <div className="mb-16 flex items-center justify-between px-10 relative">
        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-gray-100 -translate-y-1/2 z-0"></div>
        {[1, 2, 3].map((s) => (
          <div key={s} className="relative z-10 flex flex-col items-center gap-3">
            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-lg transition-all duration-500 ${
              step === s ? 'bg-blue-600 text-white shadow-2xl shadow-blue-200 scale-110' : 
              step > s ? 'bg-emerald-500 text-white shadow-lg' : 'bg-white text-gray-300 border-2 border-gray-100'
            }`}>
              {step > s ? <CheckCircle size={24} /> : s}
            </div>
            <span className={`text-[10px] font-black uppercase tracking-widest ${step >= s ? 'text-gray-900' : 'text-gray-400'}`}>
              {s === 1 ? 'Problem' : s === 2 ? 'Evidence' : 'Verify'}
            </span>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 md:p-14 rounded-[3.5rem] shadow-2xl border border-gray-50">
        {step === 1 && (
          <div className="space-y-10 animate-slideLeft">
            <div className="bg-red-50 border border-red-100 p-6 rounded-[2rem] flex items-center justify-between mb-8">
              <div className="flex items-center gap-4">
                <AlertOctagon className="text-red-500" size={32} />
                <div>
                  <h4 className="text-sm font-black text-red-900 uppercase">Emergency Protocol</h4>
                  <p className="text-xs text-red-700 font-medium">Life-threatening? Mark as emergency for instant escalation.</p>
                </div>
              </div>
              <button 
                onClick={() => setForm({...form, isEmergency: !form.isEmergency})}
                className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${
                  form.isEmergency ? 'bg-red-600 text-white shadow-lg' : 'bg-white text-red-600 border border-red-200'
                }`}
              >
                {form.isEmergency ? 'Emergency Active' : 'Mark Emergency'}
              </button>
            </div>

            <div className="space-y-8">
              <div>
                <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Title</label>
                <input 
                  type="text"
                  placeholder="Summary of the issue"
                  className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-100 focus:bg-white transition-all font-bold text-gray-800"
                  value={form.title}
                  onChange={e => setForm({...form, title: e.target.value})}
                />
              </div>

              <div className="relative">
                <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Description</label>
                <textarea 
                  rows={4}
                  placeholder="Tell us what happened..."
                  className="w-full px-8 py-6 rounded-[2.5rem] bg-gray-50 border-2 border-transparent focus:border-blue-100 focus:bg-white transition-all font-medium text-gray-800"
                  value={form.description}
                  onChange={e => setForm({...form, description: e.target.value})}
                  onBlur={runAiAnalysis}
                />
                <button type="button" onClick={toggleVoiceInput} className={`absolute right-6 bottom-6 w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-white text-gray-400 border border-gray-100'}`}>
                  {isListening ? <MicOff size={24} /> : <Mic size={24} />}
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Category</label>
                  <select 
                    className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-100 transition-all font-bold text-gray-800 appearance-none"
                    value={form.category}
                    onChange={e => setForm({...form, category: e.target.value as IssueCategory})}
                  >
                    {Object.values(IssueCategory).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Default Priority</label>
                  <div className="px-8 py-5 rounded-3xl bg-blue-50 border border-blue-100 text-blue-700 font-black text-sm uppercase flex items-center gap-2">
                    <ShieldAlert size={18} /> {form.priority}
                  </div>
                </div>
              </div>
            </div>

            <div className="flex flex-col gap-4">
              <button 
                disabled={form.description.length < 5 || analyzing}
                onClick={() => setStep(2)}
                className="w-full py-6 rounded-3xl bg-blue-600 text-white font-black hover:bg-blue-700 shadow-2xl shadow-blue-500/20 active:scale-95 transition-all flex items-center justify-center gap-3"
              >
                Continue to Evidence
                <ArrowLeft className="rotate-180" size={20} />
              </button>
              {!isOnline && (
                <button 
                  onClick={handleSaveDraft}
                  className="w-full py-5 rounded-3xl bg-amber-50 text-amber-700 font-black flex items-center justify-center gap-2 border border-amber-200"
                >
                  <Save size={20} /> Save as Draft (Offline)
                </button>
              )}
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-10 animate-slideLeft">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div onClick={() => fileInputRef.current?.click()} className="aspect-square bg-gray-50 rounded-[3rem] border-4 border-dashed border-gray-100 flex flex-col items-center justify-center cursor-pointer hover:bg-blue-50/50 transition-all relative overflow-hidden group">
                {form.image ? <img src={form.image} className="w-full h-full object-cover" /> : (
                  <div className="text-center text-gray-300">
                    <Camera size={48} className="mx-auto mb-4" />
                    <span className="text-[10px] font-black uppercase tracking-widest">Snap Proof</span>
                  </div>
                )}
                <input ref={fileInputRef} type="file" className="hidden" onChange={handleFileChange} accept="image/*" />
              </div>

              <div className="flex flex-col gap-6">
                <button onClick={handleLocation} className="flex-grow rounded-[3rem] flex flex-col items-center justify-center transition-all border-4 border-dashed bg-blue-50 text-blue-700 border-blue-100 shadow-xl">
                  {locationLoading ? <Loader2 className="animate-spin" size={48} /> : (form.location ? <CheckCircle size={48} /> : <MapPin size={48} />)}
                  <span className="text-[10px] font-black uppercase mt-4 tracking-widest text-center px-4">
                    {form.location ? `Synced: ${form.location.area}` : 'Sync Geo-Tag'}
