                </button>
                <div className="p-6 bg-emerald-50 rounded-[2rem] border border-emerald-100 flex items-center gap-4">
                  <Navigation className="text-emerald-500 flex-shrink-0" />
                  <p className="text-[10px] text-emerald-800 font-bold uppercase tracking-tight">Geo-Tagging boosts response time by 40%.</p>
                </div>
              </div>
            </div>

