import { GoogleGenAI, Type } from "@google/genai";
import { IssueCategory, IssuePriority, Grievance } from "../types";

/**
 * Utility for exponential backoff retries to handle transient network errors
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 3, initialDelay = 1000): Promise<T> {
  let lastError: any;
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      // Handle typical transient errors
      const isTransient = error instanceof Error && 
        (error.message.includes('500') || 
         error.message.includes('fetch') ||
         error.message.includes('quota') ||
         error.message.includes('deadline'));

      if (!isTransient || attempt === maxRetries - 1) break; 

      const delay = initialDelay * Math.pow(2, attempt);
      console.warn(`AI API call failed (Attempt ${attempt + 1}/${maxRetries}). Retrying in ${delay}ms...`, error);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}

export const aiService = {
  /**
   * Automatically categorizes a civic issue based on the user's text description.
   */
  async categorizeIssue(description: string): Promise<{ category: IssueCategory; priority: IssuePriority; reasoning: string }> {
    const performCategorization = async () => {
      // Always initialize a new instance to ensure the latest API key from the environment
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Review this civic grievance description: "${description}". 

        Tasks:
        1. Select the most relevant category from: ${Object.values(IssueCategory).join(", ")}.
        2. Assign a priority: Low, Medium, High, or Critical. (Critical is for life-threatening issues like open manholes or fire hazards).
        3. Provide a one-sentence reasoning for your choice.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              category: { 
                type: Type.STRING,
                description: "The exact category name from the provided list."
              },
              priority: { 
                type: Type.STRING,
                description: "The priority level: Low, Medium, High, or Critical."
              },
              reasoning: { 
                type: Type.STRING,
                description: "Brief explanation for the categorization."
              },
            },
            required: ["category", "priority", "reasoning"],
          },
        },
      });

      const text = response.text || "";
      if (!text) throw new Error("AI returned an empty response.");

      const result = JSON.parse(text.trim());

      // Map AI string output back to strictly typed Enums
      const findCategory = (val: string): IssueCategory => {
        const found = Object.values(IssueCategory).find(cat => cat.toLowerCase() === val.toLowerCase().trim());
        return found || IssueCategory.OTHERS;
      };

      const findPriority = (val: string): IssuePriority => {
        const found = Object.values(IssuePriority).find(p => p.toLowerCase() === val.toLowerCase().trim());
        return found || IssuePriority.MEDIUM;
      };

      return {
        category: findCategory(result.category),
        priority: findPriority(result.priority),
        reasoning: result.reasoning || "Categorized based on municipal standards."
      };
    };

    try { 
      return await withRetry(performCategorization); 
    } catch (e) {
      console.error("Critical AI Error:", e);
      return { 
        category: IssueCategory.OTHERS, 
        priority: IssuePriority.MEDIUM, 
        reasoning: "Categorization failed due to connectivity issues. Manual review required." 
      };
    }
  },

  /**
   * Compares a new report against existing ones to prevent duplicate complaints for the same physical issue.
   */
  async detectDuplicates(description: string, existingReports: Grievance[]): Promise<Grievance | null> {
    if (existingReports.length === 0) return null;

    // Only check against recent/unresolved reports to save tokens
    const relevantReports = existingReports.slice(0, 15);
    const summary = relevantReports.map(r => `ID: ${r.id}, Category: ${r.category}, Desc: ${r.description}`).join("\n");

    const performDetection = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `A citizen is reporting: "${description}".

        Existing Reports in this area:
        ${summary}

        Is this new report a DUPLICATE of an existing one (meaning it refers to the EXACT same physical location and problem)? 
        Return the duplicate report ID if found, otherwise return null.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              duplicateId: { 
                type: Type.STRING, 
                description: "The ID of the duplicate report or null if unique.",
              },
            },
            required: ["duplicateId"]
          },
        },
      });

      const text = response.text || "";
      if (!text) return null;

      try {
        const result = JSON.parse(text.trim());
        if (!result.duplicateId || result.duplicateId.toLowerCase() === "null") return null;
        return existingReports.find(r => r.id === result.duplicateId) || null;
      } catch {
        return null;
      }
    };

    try { 
      return await withRetry(performDetection); 
    } catch { 
      return null; 
    }
  }
};

