const ReportPage: React.FC<ReportPageProps> = ({ grievances, onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [locationLoading, setLocationLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [duplicateReport, setDuplicateReport] = useState<Grievance | null>(null);

  // Persist generated ID so it doesn't change on re-renders
  const [generatedId] = useState(() => `GRV-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 8999)}`);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    priority: IssuePriority.MEDIUM,
    description: '',
    image: '',
    location: null as Location | null,
    isEmergency: false
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, priority: string, reasoning: string } | null>(null);

  useEffect(() => {
    const handleOnlineStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleOnlineStatus);
    window.addEventListener('offline', handleOnlineStatus);

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.lang = 'en-US';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setForm(prev => ({ ...prev, description: (prev.description + " " + transcript).trim() }));
      };
      recognitionRef.current = recognition;
    }
    return () => {
      window.removeEventListener('online', handleOnlineStatus);
      window.removeEventListener('offline', handleOnlineStatus);
    };
  }, []);

  const toggleVoiceInput = (e: React.MouseEvent) => {
    e.preventDefault();
    if (isListening) recognitionRef.current?.stop();
    else recognitionRef.current?.start();
  };

  const handleLocation = () => {
    if (!("geolocation" in navigator)) {
      alert("Geolocation not supported by this browser. Using demo location.");
      simulateLocation();
      return;
    }
    setLocationLoading(true);
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const lat = position.coords.latitude;
        const lng = position.coords.longitude;
        setForm(prev => ({
          ...prev,
          location: {
            latitude: lat,
            longitude: lng,
            address: `${lat.toFixed(5)}, ${lng.toFixed(5)}`,
            area: "Verified GPS Coordinate"
          }
        }));
        setLocationLoading(false);
      },
      (error) => {
        console.error("Location error", error);
        setLocationLoading(false);
        alert("Location access denied or unavailable. Using simulated coordinates for this report.");
        simulateLocation();
      },
      { enableHighAccuracy: true, timeout: 8000 }
    );
  };

  const simulateLocation = () => {
    setForm(prev => ({
      ...prev,
      location: {
        latitude: 40.7128,
        longitude: -74.0060,
        address: "40.7128° N, 74.0060° W",
        area: "Downtown Municipal District"
      }
    }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 15) return;
    setAnalyzing(true);
    setDuplicateReport(null);
    try {
      // Run categorization and duplicate detection in parallel for efficiency
      const [catResult, dupResult] = await Promise.all([
        aiService.categorizeIssue(form.description),
        aiService.detectDuplicates(form.description, grievances)
      ]);

      setForm(prev => ({ 
        ...prev, 
        category: catResult.category, 
        priority: prev.isEmergency ? IssuePriority.CRITICAL : catResult.priority 
      }));
      setAiInsight(catResult);
      setDuplicateReport(dupResult);
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleSubmit = () => {
    setLoading(true);

    // Calculate SLA (Critical: 24h, High: 48h, Others: 120h)
    const hours = form.isEmergency ? 24 : (form.priority === IssuePriority.CRITICAL ? 48 : 120);
    const deadline = new Date();
    deadline.setHours(deadline.getHours() + hours);

    const newGrievance: Grievance = {
      id: generatedId,
      title: form.title || `${form.category} Report`,
      category: form.category,
      priority: form.isEmergency ? IssuePriority.CRITICAL : form.priority,
      description: form.description,
      image: form.image,
      location: form.location || { latitude: 0, longitude: 0, address: "Manual Location Block" },
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight,
      upvotes: 0,
      isEmergency: form.isEmergency,
      slaDeadline: deadline.toISOString()
    };

    // Simulate final portal sync
    setTimeout(() => {
      onAdd(newGrievance);
      setLoading(false);
      setSuccess(true);
      setTimeout(() => navigate('/track'), 3000);
    }, 2000);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-40 animate-fadeIn min-h-[70vh] bg-white text-center px-4">
        <div className="bg-emerald-100 text-emerald-600 p-8 rounded-[2.5rem] mb-8 shadow-xl animate-bounce">
          <CheckCircle2 size={80} />
        </div>
        <h2 className="text-4xl font-black text-gray-900 mb-4 tracking-tight">Report Logged</h2>
        <p className="text-gray-500 font-medium mb-8">Ref: <span className="text-blue-600 font-black">{generatedId}</span></p>
        <div className="bg-blue-50 text-blue-700 px-8 py-4 rounded-2xl font-bold flex flex-col gap-2 shadow-sm border border-blue-100">
          <span className="flex items-center justify-center gap-2">Citizen Points Added! <Star size={16} className="fill-blue-700" /></span>
          <span className="text-xs opacity-70">Case is now visible on the public tracker.</span>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-16 animate-fadeIn">
      {/* Wizard Steps Header */}
      <div className="mb-16 flex items-center justify-between px-10 relative">
        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-gray-100 -translate-y-1/2 z-0"></div>
        {[1, 2, 3].map((s) => (
          <div key={s} className="relative z-10 flex flex-col items-center gap-3">
            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-lg transition-all duration-500 ${
              step === s ? 'bg-blue-600 text-white shadow-2xl shadow-blue-200 scale-110' : 
              step > s ? 'bg-emerald-500 text-white shadow-lg' : 'bg-white text-gray-300 border-2 border-gray-100'
            }`}>
              {step > s ? <CheckCircle size={24} /> : s}
            </div>
            <span className={`text-[10px] font-black uppercase tracking-widest ${step >= s ? 'text-gray-900' : 'text-gray-400'}`}>
              {s === 1 ? 'Problem' : s === 2 ? 'Evidence' : 'Verify'}
            </span>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 md:p-14 rounded-[3.5rem] shadow-2xl border border-gray-50">
        {step === 1 && (
          <div className="space-y-10 animate-slideLeft">
            <div className="bg-red-50 border border-red-100 p-6 rounded-[2rem] flex items-center justify-between">
              <div className="flex items-center gap-4">
                <AlertOctagon className="text-red-500" size={32} />
                <div>
                  <h4 className="text-sm font-black text-red-900 uppercase">Emergency?</h4>
                  <p className="text-xs text-red-700 font-medium leading-tight">Mark as emergency for immediate 24h escalation.</p>
                </div>
              </div>
              <button 
                onClick={() => setForm({...form, isEmergency: !form.isEmergency})}
                className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all shadow-md ${
                  form.isEmergency ? 'bg-red-600 text-white' : 'bg-white text-red-600 border border-red-200'
                }`}
              >
                {form.isEmergency ? 'Emergency Mode' : 'Flag Emergency'}
              </button>
            </div>

            <div className="space-y-8">
              <div>
                <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Summary Title</label>
                <input 
                  type="text"
                  placeholder="E.g., Pothole near Central Market"
                  className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-100 focus:bg-white transition-all font-bold text-slate-800"
                  value={form.title}
                  onChange={e => setForm({...form, title: e.target.value})}
                />
              </div>

              <div className="relative">
                <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Description</label>
                <textarea 
                  rows={4}
                  placeholder="Describe the issue in detail..."
                  className="w-full px-8 py-6 rounded-[2.5rem] bg-gray-50 border-2 border-transparent focus:border-blue-100 focus:bg-white transition-all font-medium text-slate-800 leading-relaxed"
                  value={form.description}
                  onChange={e => setForm({...form, description: e.target.value})}
                  onBlur={runAiAnalysis}
                />
                <button 
                  type="button" 
                  onClick={toggleVoiceInput} 
                  className={`absolute right-6 bottom-6 w-14 h-14 rounded-2xl flex items-center justify-center transition-all shadow-lg ${
                    isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-white text-gray-400 border border-gray-100'
                  }`}
                >
                  {isListening ? <MicOff size={24} /> : <Mic size={24} />}
                </button>
              </div>

              {duplicateReport && (
                <div className="p-6 bg-amber-50 border border-amber-100 rounded-[2rem] flex items-center gap-4 animate-fadeIn">
                  <AlertCircle className="text-amber-600 flex-shrink-0" />
                  <div>
                    <h5 className="text-xs font-black text-amber-900 uppercase">Possible Duplicate</h5>
                    <p className="text-[11px] text-amber-700 font-medium">Someone might have already reported this: <span className="font-bold underline cursor-pointer" onClick={() => navigate('/track')}>{duplicateReport.id}</span></p>
                  </div>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Issue Category</label>
                  <div className="relative">
                    <select 
                      className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-100 transition-all font-bold text-slate-800 appearance-none cursor-pointer"
                      value={form.category}
                      onChange={e => setForm({...form, category: e.target.value as IssueCategory})}
                    >
                      {Object.values(IssueCategory).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <ChevronDown className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400" size={20} />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Assigned Priority</label>
                  <div className={`w-full px-8 py-5 rounded-3xl font-black text-sm flex items-center gap-3 border-2 ${
                    form.isEmergency || form.priority === IssuePriority.CRITICAL ? 'bg-red-50 border-red-100 text-red-600' : 'bg-blue-50 border-blue-100 text-blue-600'
                  }`}>
                    <ShieldAlert size={18} /> {form.isEmergency ? 'CRITICAL (EMERGENCY)' : form.priority}
                  </div>
                </div>
              </div>

              {analyzing ? (
                <div className="flex items-center gap-4 p-6 bg-blue-50 border border-blue-100 rounded-3xl animate-pulse">
                  <Loader2 className="animate-spin text-blue-600" />
                  <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest">AI Categorizing Details...</span>
                </div>
              ) : aiInsight && (
                <div className="flex items-start gap-4 p-6 bg-slate-50 border border-slate-100 rounded-3xl">
                  <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-blue-600 shadow-sm flex-shrink-0">
                    <Sparkles size={20} />
                  </div>
                  <div>
                    <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">AI Suggestion reasoning</h5>
                    <p className="text-xs font-medium text-slate-600 leading-relaxed italic">"{aiInsight.reasoning}"</p>
                  </div>
                </div>
              )}
            </div>

            <button 
              disabled={form.description.length < 5 || analyzing}
              onClick={() => setStep(2)}
              className="w-full py-6 rounded-3xl bg-blue-600 text-white font-black hover:bg-blue-700 shadow-2xl shadow-blue-500/20 active:scale-95 transition-all flex items-center justify-center gap-3"
            >
              Continue to Photos
              <ArrowLeft className="rotate-180" size={20} />
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-10 animate-slideLeft">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              {/* Image Input */}
              <div 
                onClick={() => fileInputRef.current?.click()} 
                className="aspect-square bg-gray-50 rounded-[3rem] border-4 border-dashed border-gray-100 flex flex-col items-center justify-center cursor-pointer hover:bg-blue-50/50 transition-all relative overflow-hidden group shadow-inner"
              >
                {form.image ? (
                  <img src={form.image} className="w-full h-full object-cover" alt="Captured evidence" />
                ) : (
                  <div className="text-center text-gray-300 group-hover:text-blue-600">
                    <Camera size={48} className="mx-auto mb-4" />
                    <span className="text-[10px] font-black uppercase tracking-widest">Snap or Upload Proof</span>
                  </div>
                )}
                <input ref={fileInputRef} type="file" className="hidden" onChange={handleFileChange} accept="image/*" />
              </div>

              {/* Location Sync */}
              <div className="flex flex-col gap-6">
                <button 
                  onClick={handleLocation} 
                  disabled={locationLoading}
                  className={`flex-grow rounded-[3rem] flex flex-col items-center justify-center transition-all border-4 border-dashed shadow-xl active:scale-95 ${
                    form.location ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-blue-50 text-blue-700 border-blue-100'
                  }`}
                >
                  {locationLoading ? <Loader2 className="animate-spin" size={48} /> : (form.location ? <CheckCircle size={48} /> : <MapPin size={48} />)}
                  <span className="text-[10px] font-black uppercase mt-4 tracking-widest text-center px-4 leading-relaxed">
