import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Shield, User, LogIn, UserPlus, Globe, Mail, Lock, ArrowRight, Loader2, Star } from 'lucide-react';
import { User as UserType, UserRole } from '../types';

interface LoginPageProps {
  onLogin: (user: UserType) => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const navigate = useNavigate();
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [role, setRole] = useState<UserRole>('citizen');
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({ email: '', password: '' });

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    // Simulate API delay
    await new Promise(resolve => setTimeout(resolve, 800));

    if (role === 'admin') {
      if (form.email === 'admin@civic.gov' && form.password === 'admin123') {
        const adminUser: UserType = { email: form.email, role: 'admin', points: 0, badges: [] };
        onLogin(adminUser);
        navigate('/admin');
      } else {
        alert("❌ Invalid Authority Credentials");
      }
    } else {
      let citizens: UserType[] = JSON.parse(localStorage.getItem('civic_registered_users') || '[]');

      if (mode === 'register') {
        const exists = citizens.find(u => u.email === form.email);
        if (exists) {
          alert("Account already exists. Please login.");
        } else {
          const newUser: UserType = { email: form.email, role: 'citizen', points: 100, badges: ['🥉 Newcomer'] };
          citizens.push(newUser);
          localStorage.setItem('civic_registered_users', JSON.stringify(citizens));
          onLogin(newUser);
          navigate('/');
        }
      } else {
        const user = citizens.find(u => u.email === form.email);
        if (user) {
          onLogin(user);
          navigate('/');
        } else {
          alert("❌ Account not found. Please register first.");
        }
      }
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center py-20 px-4 animate-fadeIn">
      <div className="max-w-md w-full">
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-blue-600 text-white rounded-[2rem] shadow-2xl shadow-blue-500/20 mb-6">
            <Globe size={40} />
          </div>
          <h1 className="text-3xl font-black text-gray-900 tracking-tight">Welcome to CivicConnect</h1>
          <p className="text-gray-500 font-medium mt-2">Access your city dashboard</p>
        </div>

        <div className="bg-white p-8 md:p-10 rounded-[3rem] shadow-2xl border border-gray-100">
          {/* Role Toggle */}
          <div className="flex bg-gray-100 p-1.5 rounded-2xl mb-8">
            <button 
              onClick={() => { setRole('citizen'); setMode('login'); }}
              className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${role === 'citizen' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
            >
              <User size={16} /> Citizen
            </button>
            <button 
              onClick={() => { setRole('admin'); setMode('login'); }}
              className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${role === 'admin' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
            >
              <Shield size={16} /> Authority
            </button>
          </div>

          <form onSubmit={handleAuth} className="space-y-6">
            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Email Address</label>
              <div className="relative">
                <Mail className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                <input 
                  type="email" 
                  required
                  className="w-full pl-16 pr-8 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-600 focus:bg-white transition-all font-bold text-gray-800 outline-none"
                  placeholder={role === 'admin' ? 'admin@civic.gov' : 'name@example.com'}
                  value={form.email}
                  onChange={e => setForm({...form, email: e.target.value})}
                />
              </div>
            </div>

            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 ml-2">Password</label>
              <div className="relative">
                <Lock className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                <input 
                  type="password" 
                  required
                  className="w-full pl-16 pr-8 py-5 rounded-3xl bg-gray-50 border-2 border-transparent focus:border-blue-600 focus:bg-white transition-all font-bold text-gray-800 outline-none"
                  placeholder="••••••••"
                  value={form.password}
                  onChange={e => setForm({...form, password: e.target.value})}
                />
              </div>
            </div>

            <button 
              disabled={loading}
              type="submit"
              className={`w-full py-6 rounded-3xl text-white font-black shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 ${
                role === 'admin' ? 'bg-gray-900 hover:bg-black shadow-gray-500/20' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-500/20'
              }`}
            >
              {loading ? <Loader2 className="animate-spin" /> : (mode === 'login' ? <LogIn size={20} /> : <UserPlus size={20} />)}
              {mode === 'login' ? 'Continue Access' : 'Create Citizen Profile'}
            </button>
          </form>

          {role === 'citizen' && (
            <div className="mt-8 text-center">
              <button 
                onClick={() => setMode(mode === 'login' ? 'register' : 'login')}
                className="text-xs font-black text-gray-400 uppercase tracking-widest hover:text-blue-600 transition-colors"
              >
                {mode === 'login' ? "Don't have an account? Register" : "Already have an account? Login"}
              </button>
            </div>
          )}

          {role === 'admin' && (
            <div className="mt-8 p-4 bg-amber-50 rounded-2xl border border-amber-100 flex items-start gap-3">
              <Star className="text-amber-500 flex-shrink-0" size={16} />
              <p className="text-[10px] text-amber-800 font-bold uppercase tracking-tight leading-relaxed">
                Use system default credentials for Authority testing.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default LoginPage;

