const App: React.FC = () => {
  const [grievances, setGrievances] = useState<Grievance[]>(() => {
    const saved = localStorage.getItem('civic_grievances');
    return saved ? JSON.parse(saved) : INITIAL_GRIEVANCES;
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('civic_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  useEffect(() => {
    localStorage.setItem('civic_grievances', JSON.stringify(grievances));
  }, [grievances]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('civic_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('civic_current_user');
    }
  }, [currentUser]);

  const addGrievance = (g: Grievance) => {
    setGrievances(prev => [g, ...prev]);
    if (currentUser && currentUser.role === 'citizen') {
      const updatedUser = {
        ...currentUser,
        points: currentUser.points + 50,
        badges: currentUser.points + 50 > 300 ? [...currentUser.badges, '🥈 Civic Pro'] : currentUser.badges
      };
      setCurrentUser(updatedUser);

      // Also update in registered list
      let citizens: User[] = JSON.parse(localStorage.getItem('civic_registered_users') || '[]');
      citizens = citizens.map(u => u.email === updatedUser.email ? updatedUser : u);
      localStorage.setItem('civic_registered_users', JSON.stringify(citizens));
    }
  };

  const updateGrievanceStatus = (id: string, status: IssueStatus) => {
    setGrievances(prev => prev.map(g => 
      g.id === id ? { ...g, status, updatedAt: new Date().toISOString() } : g
    ));
  };

  const toggleUpvote = (id: string) => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        const alreadyVoted = g.votedByMe;
        return {
          ...g,
          upvotes: alreadyVoted ? g.upvotes - 1 : g.upvotes + 1,
          votedByMe: !alreadyVoted
        };
      }
      return g;
    }));
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-white">
        <Navbar user={currentUser} onLogout={handleLogout} />
        <main className="flex-grow pt-16">
          <Routes>
            <Route path="/" element={<HomePage grievances={grievances} user={currentUser} />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/login" element={<LoginPage onLogin={handleLogin} />} />
            <Route path="/report" element={<ReportPage grievances={grievances} onAdd={addGrievance} />} />
            <Route path="/track" element={<TrackPage grievances={grievances} onUpvote={toggleUpvote} />} />
            <Route 
              path="/admin" 
              element={currentUser?.role === 'admin' ? (
                <AdminPage grievances={grievances} onUpdateStatus={updateGrievanceStatus} />
              ) : (
                <Navigate to="/login" />
              )} 
            />
            <Route path="/contact" element={<ContactPage />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
};

export default App;

