            <div className="bg-blue-600 p-2 rounded-xl text-white shadow-lg shadow-blue-600/20 group-hover:scale-110 transition-transform">
              <Globe size={20} />
            </div>
            <span className={`font-black text-xl tracking-tight transition-colors ${scrolled ? 'text-gray-900' : 'text-gray-900'}`}>
              Civic<span className="text-blue-600">Connect</span>
