                    ? 'text-blue-700 bg-blue-50' 
                    : 'text-gray-600 hover:text-blue-600 hover:bg-gray-50'
                }`}
              >
                {link.icon}
                {link.name}
              </Link>
            ))}

            <div className="h-6 w-px bg-gray-200 mx-4"></div>

            <div className="flex items-center gap-4">
              {!isOnline && (
                <div className="flex items-center gap-1.5 px-3 py-1 bg-amber-50 text-amber-600 rounded-lg text-[10px] font-black uppercase tracking-widest border border-amber-100 animate-pulse">
                  <WifiOff size={14} /> Offline Mode
                </div>
              )}

              {user ? (
                <>
                  {user.role === 'citizen' && (
                    <div className="flex items-center gap-2 px-4 py-1.5 bg-blue-50 text-blue-700 rounded-full border border-blue-100 shadow-sm">
                      <Star size={14} className="fill-blue-700" />
                      <span className="text-xs font-black">{user.points} XP</span>
                    </div>
                  )}
                  <button 
                    onClick={onLogout}
                    className="flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold text-red-600 hover:bg-red-50 transition-all group"
                  >
                    <LogOut size={18} className="group-hover:-translate-x-1 transition-transform" />
                    <span className="hidden lg:inline">Logout</span>
                  </button>
