              ) : (
                <Link 
                  to="/login"
                  className="group flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-xl text-sm font-black shadow-lg shadow-blue-500/30 hover:bg-blue-700 transition-all active:scale-95 animate-pulse-subtle"
                >
                  <LogIn size={18} className="group-hover:translate-x-1 transition-transform" />
                  Sign In
