<button onclick="location.href='admin-login.html'">Admin Login</button>
<button onclick="location.href='user-login.html'">User Login</button>

</body>
</html>

👉 Now your login page IS ADDED (this is the missing part earlier).


---

✅ STEP 3: ADMIN LOGIN (FIXED ID & PASSWORD)

📄 admin-login.html

<!DOCTYPE html>
<html>
<head>
  <title>Admin Login</title>
</head>
<body>

<h2>Admin Login</h2>

<input type="email" id="email" placeholder="Admin Email"><br><br>
<input type="password" id="password" placeholder="Password"><br><br>

<button onclick="adminLogin()">Login</button>

<script>
function adminLogin() {
  const email = document.getElementById("email").value;
  const password = document.getElementById("password").value;

  if (email === "admin@civic.gov" && password === "admin123") {
    localStorage.setItem("adminLoggedIn", "true");
    window.location.href = "admin-dashboard.html";
  } else {
    alert("Invalid Admin Credentials");
  }
}
</script>

</body>
</html>

✅ Admin credentials are fixed
✅ Redirect works


---

✅ STEP 4: USER LOGIN (NEW + EXISTING USER)

📄 user-login.html

<!DOCTYPE html>
<html>
<head>
  <title>User Login</title>
</head>
<body>

<h2>User Login</h2>

<input type="email" id="email" placeholder="Email"><br><br>
<input type="password" id="password" placeholder="Password"><br><br>

<button onclick="loginUser()">Existing User Login</button>
<button onclick="registerUser()">New User Register</button>

<script>
function registerUser() {
  const email = document.getElementById("email").value;
  const password = document.getElementById("password").value;

  if (!email || !password) {
    alert("Fill all fields");
    return;
  }

  let users = JSON.parse(localStorage.getItem("users")) || [];

  if (users.find(u => u.email === email)) {
    alert("User already exists");
    return;
  }

  users.push({ email, password });
  localStorage.setItem("users", JSON.stringify(users));

  alert("Registration successful. Now login.");
}

function loginUser() {
  const email = document.getElementById("email").value;
  const password = document.getElementById("password").value;

  let users = JSON.parse(localStorage.getItem("users")) || [];

  let valid = users.find(u => u.email === email && u.password === password);

  if (valid) {
    localStorage.setItem("loggedInUser", email);
    window.location.href = "user-dashboard.html";
  } else {
    alert("Invalid login or user not registered");
  }
}
</script>

</body>
</html>

✅ New user → Register
✅ Existing user → Login
✅ Data stored correctly


---

✅ STEP 5: USER DASHBOARD (PROTECTED)

📄 user-dashboard.html

<!DOCTYPE html>
<html>
<head>
  <title>User Dashboard</title>
</head>
<body>

<h2>User Dashboard</h2>
<p id="welcome"></p>

<button onclick="logout()">Logout</button>

<script>
const user = localStorage.getItem("loggedInUser");

if (!user) {
  window.location.href = "user-login.html";
}

document.getElementById("welcome").innerText =
  "Welcome, " + user;

function logout() {
  localStorage.removeItem("loggedInUser");
  window.location.href = "index.html";
}
</script>

</body>
</html>


---

✅ STEP 6: ADMIN DASHBOARD (PROTECTED)

📄 admin-dashboard.html

