<p>Welcome Admin</p>

<button onclick="logout()">Logout</button>

<script>
if (!localStorage.getItem("adminLoggedIn")) {
  window.location.href = "admin-login.html";
}

function logout() {
  localStorage.removeItem("adminLoggedIn");
  window.location.href = "index.html";
}
</script>

</body>
</html>


---

