import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { 
  Shield, 
  User as UserIcon, 
  LogIn, 
  UserPlus, 
  Globe, 
  Mail, 
  Lock, 
  ArrowRight, 
  Loader2, 
  Star,
  ChevronLeft,
  Building2
} from 'lucide-react';
import { User as UserType, UserRole } from '../types';

interface LoginPageProps {
  onLogin: (user: UserType) => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const navigate = useNavigate();
  const location = useLocation();

  // States: 'select' (The Hub), 'login' (Form), 'register' (Form)
  const [view, setView] = useState<'select' | 'login' | 'register'>('select');
  const [role, setRole] = useState<UserRole>('citizen');
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({ email: '', password: '' });

  // Handle Logic from user prompt
  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    // Simulate standard network delay
    await new Promise(resolve => setTimeout(resolve, 600));

    if (role === 'admin') {
      // 1️⃣ ADMIN LOGIN (FIXED ID & PASSWORD)
      if (form.email === 'admin@civic.gov' && form.password === 'admin123') {
        localStorage.setItem("adminLoggedIn", "true");
        const adminUser: UserType = { email: form.email, role: 'admin', points: 0, badges: [] };
        onLogin(adminUser);
        navigate('/admin');
      } else {
        alert("❌ Invalid Authority Credentials. Use: admin@civic.gov / admin123");
      }
    } else {
      // 2️⃣ USER LOGIN/REGISTER
      let users: any[] = JSON.parse(localStorage.getItem("users") || '[]');

      if (view === 'register') {
        if (!form.email || !form.password) {
          alert("Fill all fields");
          setLoading(false);
          return;
        }

        if (users.find(u => u.email === form.email)) {
          alert("User already exists. Please login.");
          setView('login');
        } else {
          users.push({ email: form.email, password: form.password });
          localStorage.setItem("users", JSON.stringify(users));
          alert("✅ Registration successful. Now login.");
          setView('login');
        }
      } else {
        // Existing User Login
        const valid = users.find(u => u.email === form.email && u.password === form.password);
        if (valid) {
          localStorage.setItem("loggedInUser", form.email);
          const citizenUser: UserType = { 
            email: form.email, 
            role: 'citizen', 
            points: 100, 
            badges: ['🥉 Newcomer'] 
          };
          onLogin(citizenUser);
          navigate('/');
        } else {
          alert("❌ Invalid login or user not registered");
        }
      }
    }
    setLoading(false);
  };

  if (view === 'select') {
    return (
      <div className="min-h-[80vh] flex items-center justify-center py-20 px-4 animate-fadeIn">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Hub Header */}
          <div className="md:col-span-2 text-center mb-10">
            <div className="inline-flex items-center justify-center w-20 h-20 bg-blue-600 text-white rounded-[2rem] shadow-2xl mb-6">
              <Globe size={40} />
            </div>
            <h1 className="text-4xl font-black text-gray-900 tracking-tight">Access Civic Portal</h1>
            <p className="text-gray-500 font-medium mt-2">Select your entry point to continue</p>
          </div>

          {/* Citizen Option */}
          <button 
