};

const App: React.FC = () => {
  const [grievances, setGrievances] = useState<Grievance[]>(() => {
    const saved = localStorage.getItem('civic_grievances');
    return saved ? JSON.parse(saved) : INITIAL_GRIEVANCES;
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const admin = localStorage.getItem('adminLoggedIn');
    const userEmail = localStorage.getItem('loggedInUser');
    if (admin === 'yes') return { email: 'admin@civic.gov', role: 'admin', points: 0, badges: [] };
    if (userEmail) return { email: userEmail, role: 'citizen', points: 100, badges: ['🥉 Newcomer'] };
    return null;
  });

  useEffect(() => {
    localStorage.setItem('civic_grievances', JSON.stringify(grievances));
  }, [grievances]);

  const handleLogin = (user: User) => {
    if (user.role === 'admin') {
      localStorage.setItem('adminLoggedIn', 'yes');
    } else {
      localStorage.setItem('loggedInUser', user.email);
    }
    setCurrentUser(user);
  };

  const handleLogout = () => {
    localStorage.removeItem('loggedInUser');
    localStorage.removeItem('adminLoggedIn');
    setCurrentUser(null);
  };

  const addGrievance = (g: Grievance) => {
    setGrievances(prev => [g, ...prev]);
    if (currentUser?.role === 'citizen') {
      setCurrentUser(curr => curr ? { ...curr, points: curr.points + 50 } : null);
    }
  };

  const updateStatus = (id: string, status: IssueStatus) => {
    setGrievances(prev => prev.map(g => g.id === id ? { ...g, status, updatedAt: new Date().toISOString() } : g));
  };

  const toggleUpvote = (id: string) => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        const voted = !g.votedByMe;
        return { ...g, votedByMe: voted, upvotes: voted ? g.upvotes + 1 : g.upvotes - 1 };
      }
      return g;
    }));
  };

  return (
    <Router>
      <div className="flex flex-col min-h-screen">
        <Navbar user={currentUser} onLogout={handleLogout} />
        <main className="flex-grow pt-16">
          <Routes>
            <Route path="/" element={<HomePage grievances={grievances} user={currentUser} />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/login" element={<LoginPage onLogin={handleLogin} />} />
            <Route path="/report" element={currentUser ? <ReportPage grievances={grievances} onAdd={addGrievance} /> : <Navigate to="/login" />} />
            <Route path="/track" element={<TrackPage grievances={grievances} onUpvote={toggleUpvote} />} />
            <Route path="/admin" element={currentUser?.role === 'admin' ? <AdminPage grievances={grievances} onUpdateStatus={updateStatus} /> : <Navigate to="/login" />} />
            <Route path="/contact" element={<ContactPage />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Shield, User as UserIcon, LogIn, Globe, ArrowRight, ArrowLeft, Mail, Lock, Loader2 } from 'lucide-react';
import { User as UserType, UserRole } from '../types';

interface LoginPageProps {
  onLogin: (user: UserType) => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const navigate = useNavigate();
  const [view, setView] = useState<'hub' | 'citizen' | 'authority'>('hub');
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [loading, setLoading] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    // Simulate API delay
    await new Promise(r => setTimeout(r, 800));

    if (view === 'authority') {
      if (email === "admin@civic.gov" && password === "admin123") {
        onLogin({ email, role: 'admin', points: 0, badges: [] });
        navigate('/admin');
      } else {
        alert("❌ Invalid Authority Credentials. Use: admin@civic.gov / admin123");
      }
    } else {
      // Citizen Logic
      let users = JSON.parse(localStorage.getItem("users") || '[]');
      if (mode === 'register') {
        if (users.some((u: any) => u.email === email)) {
          alert("User already exists. Please login.");
          setMode('login');
        } else {
          users.push({ email, password });
          localStorage.setItem("users", JSON.stringify(users));
          alert("✅ Registration successful. Now login.");
          setMode('login');
        }
      } else {
        const found = users.find((u: any) => u.email === email && u.password === password);
        if (found) {
          onLogin({ email, role: 'citizen', points: 100, badges: ['🥉 Newcomer'] });
          navigate('/');
        } else {
          alert("❌ Invalid credentials or user not registered.");
        }
      }
    }
    setLoading(false);
  };

  if (view === 'hub') {
    return (
      <div className="min-h-[80vh] flex items-center justify-center p-4 animate-in fade-in duration-500">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="md:col-span-2 text-center mb-10">
            <div className="inline-flex items-center justify-center w-20 h-20 bg-blue-600 text-white rounded-[2rem] shadow-2xl mb-6">
              <Globe size={40} />
            </div>
            <h1 className="text-4xl font-black text-gray-900 tracking-tight">Access Civic Portal</h1>
            <p className="text-gray-500 font-medium mt-2">Select your entry point to continue</p>
          </div>

          <button 
            onClick={() => setView('citizen')}
            className="group bg-white p-10 rounded-[3rem] shadow-xl border border-gray-100 hover:border-blue-500 hover:shadow-2xl transition-all text-left relative overflow-hidden"
          >
            <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mb-6 shadow-sm group-hover:bg-blue-600 group-hover:text-white transition-all">
              <UserIcon size={32} />
            </div>
            <h3 className="text-2xl font-black text-gray-900 mb-2">Citizen Portal</h3>
            <p className="text-gray-500 font-medium text-sm mb-8 leading-relaxed">Report issues, track progress, and earn points for helping your city.</p>
            <div className="flex items-center gap-2 text-blue-600 font-black text-xs uppercase tracking-widest">
              Enter Dashboard <ArrowRight size={16} />
            </div>
          </button>

          <button 
            onClick={() => setView('authority')}
            className="group bg-slate-900 p-10 rounded-[3rem] shadow-xl border border-slate-800 hover:border-blue-500 hover:shadow-2xl transition-all text-left relative overflow-hidden"
          >
            <div className="w-16 h-16 bg-blue-600 text-white rounded-2xl flex items-center justify-center mb-6 shadow-sm">
              <Shield size={32} />
            </div>
            <h3 className="text-2xl font-black text-white mb-2">Authority Portal</h3>
            <p className="text-slate-400 font-medium text-sm mb-8 leading-relaxed">Official management center for verifying and resolving public reports.</p>
            <div className="flex items-center gap-2 text-blue-400 font-black text-xs uppercase tracking-widest">
              Secure Login <ArrowRight size={16} />
            </div>
          </button>
        </div>
      </div>
    );
  }

  const isAuthority = view === 'authority';

  return (
    <div className="min-h-[80vh] flex items-center justify-center p-4">
      <div className="max-w-md w-full">
        <button 
          onClick={() => setView('hub')}
          className="mb-8 flex items-center gap-2 text-xs font-black text-gray-400 uppercase tracking-widest hover:text-blue-600 transition-colors"
        >
          <ArrowLeft size={16} /> Back to Selection
        </button>

        <div className={`p-10 rounded-[3rem] shadow-2xl border ${isAuthority ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-gray-100'}`}>
          <div className="text-center mb-10">
            <div className={`w-16 h-16 mx-auto rounded-2xl flex items-center justify-center mb-6 ${isAuthority ? 'bg-blue-600' : 'bg-blue-50 text-blue-600'}`}>
              {isAuthority ? <Shield size={32} /> : <UserIcon size={32} />}
            </div>
            <h2 className="text-3xl font-black tracking-tight">
              {isAuthority ? 'Authority Login' : (mode === 'login' ? 'Citizen Login' : 'Create Account')}
            </h2>
            <p className={`text-sm mt-2 ${isAuthority ? 'text-slate-400' : 'text-gray-500'}`}>
              {isAuthority ? 'Verified Personnel Only' : 'Welcome to CivicConnect'}
            </p>
          </div>

          <form onSubmit={handleAuth} className="space-y-6">
            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2 ml-2">Email Address</label>
              <div className="relative">
                <Mail className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                <input 
                  type="email" required
                  className={`w-full pl-16 pr-6 py-4 rounded-2xl border-2 border-transparent outline-none font-bold transition-all ${
                    isAuthority ? 'bg-slate-800 text-white focus:border-blue-500' : 'bg-gray-50 text-gray-900 focus:border-blue-600 focus:bg-white'
                  }`}
                  placeholder={isAuthority ? 'admin@civic.gov' : 'your@email.com'}
                  value={email}
                  onChange={e => setEmail(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2 ml-2">Password</label>
              <div className="relative">
                <Lock className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                <input 
                  type="password" required
                  className={`w-full pl-16 pr-6 py-4 rounded-2xl border-2 border-transparent outline-none font-bold transition-all ${
                    isAuthority ? 'bg-slate-800 text-white focus:border-blue-500' : 'bg-gray-50 text-gray-900 focus:border-blue-600 focus:bg-white'
                  }`}
                  placeholder="••••••••"
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                />
              </div>
            </div>

            <button 
              disabled={loading}
              className={`w-full py-5 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95 ${
                isAuthority ? 'bg-blue-600 hover:bg-blue-700 shadow-blue-500/20 text-white' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-500/20 text-white'
              }`}
            >
              {loading ? <Loader2 className="animate-spin" /> : <LogIn size={20} />}
              {isAuthority ? 'Authorize Access' : (mode === 'login' ? 'Login' : 'Register')}
            </button>
          </form>

          {!isAuthority && (
            <div className="mt-8 text-center">
              <button 
                onClick={() => setMode(mode === 'login' ? 'register' : 'login')}
                className="text-xs font-black text-gray-400 uppercase tracking-widest hover:text-blue-600 transition-colors"
              >
                {mode === 'login' ? "Need an account? Register" : "Already registered? Login"}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default LoginPage;

