interface LoginPageProps {
  onLogin: (user: UserType) => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const navigate = useNavigate();
  const [view, setView] = useState<'hub' | 'citizen' | 'authority'>('hub');
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [loading, setLoading] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showDemoCreds, setShowDemoCreds] = useState(false);

  // Pre-fill credentials when switching to authority view for demo purposes
  useEffect(() => {
    if (view === 'authority') {
      setEmail('admin@civic.gov');
      setPassword('admin123');
    } else {
      setEmail('');
      setPassword('');
    }
  }, [view]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    // Simulate slight delay for "processing" feel
    await new Promise(r => setTimeout(r, 600));

    if (view === 'authority') {
      if (email === "admin@civic.gov" && password === "admin123") {
        localStorage.setItem("adminLoggedIn", "yes");
        onLogin({ email, role: 'admin', points: 0, badges: [] });
        navigate('/admin');
      } else {
        alert("❌ Invalid Authority Credentials. Use: admin@civic.gov / admin123");
      }
    } else {
      // Citizen Logic
      let users = JSON.parse(localStorage.getItem("users") || '[]');
      if (mode === 'register') {
        if (users.some((u: any) => u.email === email)) {
          alert("⚠️ User already exists. Please login.");
          setMode('login');
        } else {
          users.push({ email, password });
          localStorage.setItem("users", JSON.stringify(users));
          alert("✅ Registration successful. You can now login!");
          setMode('login');
        }
      } else {
        const found = users.find((u: any) => u.email === email && u.password === password);
        if (found) {
          localStorage.setItem("loggedInUser", email);
          onLogin({ email, role: 'citizen', points: 100, badges: ['🥉 Newcomer'] });
          navigate('/');
        } else {
          alert("❌ Invalid credentials or user not registered.");
        }
      }
    }
    setLoading(false);
  };

  const setDemoUser = (u: string, p: string) => {
    setEmail(u);
    setPassword(p);
  };

  if (view === 'hub') {
    return (
      <div className="min-h-[80vh] flex items-center justify-center p-4 animate-fadeIn">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 gap-8">
