import React, { useState, useEffect } from 'react';
import { 
  Filter, 
  MapPin, 
  Tag, 
  ArrowUpRight,
  Download,
  Search,
  CheckCircle,
  Clock,
  AlertTriangle,
  Sparkles,
  TrendingUp,
  Inbox,
  ShieldAlert,
  Activity,
  CheckCircle2,
  XCircle,
  Wrench,
  Loader2,
  ChevronDown,
  RefreshCw,
  BarChart3,
  Map as MapIcon,
  AlertOctagon,
  FileSpreadsheet,
  Printer
} from 'lucide-react';
import { Grievance, IssueCategory, IssueStatus, IssuePriority } from '../types';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  onUpdateStatus: (id: string, status: IssueStatus) => void;
  onUpdateGrievance?: (id: string, updates: Partial<Grievance>) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances, onUpdateStatus, onUpdateGrievance }) => {
  const [activeTab, setActiveTab] = useState<'list' | 'analytics'>('list');
  const [filterCategory, setFilterCategory] = useState<string>('All');
  const [filterStatus, setFilterStatus] = useState<string>('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [isExporting, setIsExporting] = useState(false);
  const [reportDate, setReportDate] = useState(new Date());

  useEffect(() => {
    // Refresh date whenever print is triggered or component mounts
    setReportDate(new Date());
  }, [activeTab]);

  const filtered = grievances.filter(g => {
    const matchesCategory = filterCategory === 'All' || g.category === filterCategory;
    const matchesStatus = filterStatus === 'All' || g.status === filterStatus;
    const matchesSearch = g.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          g.id.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesStatus && matchesSearch;
  });

  const getHeatmapData = () => {
    const areas: Record<string, number> = {};
    grievances.forEach(g => {
      const area = g.location.area || 'Unknown';
      areas[area] = (areas[area] || 0) + 1;
    });
    return Object.entries(areas).sort((a, b) => b[1] - a[1]);
  };

  const downloadMasterLog = () => {
    setIsExporting(true);
    const headers = ["Grievance_ID", "Status", "Priority", "Category", "Area", "Upvotes", "Created_Date"];
    const rows = filtered.map(g => [
      g.id,
      g.status,
      g.priority,
      g.category,
      g.location.area || "City Wide",
      g.upvotes,
      new Date(g.createdAt).toLocaleDateString()
    ]);

    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Civic_Command_Log_${new Date().toISOString().slice(0,10)}.csv`);
    link.click();

    setTimeout(() => setIsExporting(false), 1000);
  };

  const printHealthSummary = () => {
    setReportDate(new Date());
    window.print();
  };

  const stats = [
    { label: 'Active Reports', count: grievances.length, icon: <Inbox />, color: 'bg-blue-600' },
    { label: 'SLA Breaches', count: grievances.filter(g => g.slaDeadline && new Date(g.slaDeadline) < new Date() && g.status !== IssueStatus.RESOLVED).length, icon: <AlertTriangle />, color: 'bg-red-600' },
    { label: 'Emergency Active', count: grievances.filter(g => g.isEmergency && g.status !== IssueStatus.RESOLVED).length, icon: <AlertOctagon />, color: 'bg-orange-600' },
    { label: 'Avg Resolution', count: '42h', icon: <Clock />, color: 'bg-emerald-600' }
  ];

  return (
    <div className="bg-[#fcfcfd] min-h-screen pb-20 animate-fadeIn">
      <style>{`
        @media print {
          nav, .no-print, button, select, input, .lucide { display: none !important; }
          .print-only { display: block !important; }
          .print-visible { display: block !important; visibility: visible !important; opacity: 1 !important; }
          body { background: white !important; color: black !important; padding: 20px !important; }
          .bg-white { box-shadow: none !important; border: 1px solid #eee !important; background: white !important; }
          .shadow-sm, .shadow-xl, .shadow-2xl { box-shadow: none !important; }
          .bg-gray-900 { background: white !important; color: black !important; border: 1px solid #eee !important; }
          .text-white { color: black !important; }
          .text-blue-400, .text-emerald-400 { color: #2563eb !important; }
          .rounded-[3rem], .rounded-[2.5rem] { border-radius: 12px !important; }
          table { width: 100% !important; border-collapse: collapse !important; }
          th, td { border: 1px solid #eee !important; padding: 12px !important; }
        }
      `}</style>

      {/* Main Header - Only visible on screen */}
      <div className="bg-white border-b border-gray-100 pt-16 pb-8 mb-10 shadow-sm no-print">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-12">
            <div>
              <div className="flex items-center gap-3 mb-3">
                <span className="bg-blue-100 text-blue-700 text-[10px] font-black px-3 py-1 rounded-lg uppercase tracking-widest">Command Center</span>
                <span className="text-gray-300">•</span>
                <span className="text-gray-400 text-[10px] font-bold uppercase tracking-widest">Authority Portal</span>
              </div>
              <h1 className="text-4xl font-black text-gray-900 tracking-tight">Municipal Command</h1>
            </div>

            <div className="flex items-center gap-4">
              <button 
                onClick={printHealthSummary}
                className="bg-white border-2 border-slate-100 px-6 py-3 rounded-2xl text-slate-600 font-black text-xs uppercase tracking-widest flex items-center gap-2 hover:bg-slate-50 transition-all shadow-sm"
              >
                <Printer size={16} /> Print Health Summary
              </button>
              <div className="flex bg-gray-100 p-1.5 rounded-2xl">
                <button 
                  onClick={() => setActiveTab('list')}
                  className={`flex items-center gap-2 px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'list' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                  <Activity size={16} /> Reports
                </button>
                <button 
                  onClick={() => setActiveTab('analytics')}
                  className={`flex items-center gap-2 px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'analytics' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                  <BarChart3 size={16} /> Analytics
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4">
        {/* Printable Header - Only visible on paper */}
        <div className="print-only hidden mb-12 border-b-4 border-blue-600 pb-10">
           <div className="flex justify-between items-start">
             <div>
               <h1 className="text-3xl font-black text-slate-900 mb-2 tracking-tighter">MUNICIPAL COMMAND REPORT</h1>
               <p className="text-xs font-black text-blue-600 uppercase tracking-widest">System Health Audit | {reportDate.toLocaleString()}</p>
             </div>
             <div className="text-right">
               <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">CivicConnect Auth ID</p>
               <p className="text-xs font-black text-slate-900">#ADM-{Math.floor(Math.random() * 999999)}</p>
             </div>
           </div>
        </div>

        {/* Stats Section - Visible in both (adjusted for print) */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-10 print-visible">
          {stats.map((stat, i) => (
            <div key={i} className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm print:border-slate-200">
              <div className="flex justify-between items-start">
                <div className={`p-4 rounded-2xl text-white ${stat.color} shadow-lg shadow-current/20 no-print`}>{stat.icon}</div>
                <div className="text-right flex-grow">
                  <span className="text-[10px] font-black text-gray-400 uppercase mb-1 block">{stat.label}</span>
                  <div className="text-3xl font-black text-gray-900 tracking-tighter">{stat.count}</div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {activeTab === 'list' ? (
          <div className="space-y-10">
            <div className="no-print bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm flex flex-wrap items-center gap-6">
              <div className="relative flex-grow min-w-[300px]">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                <input type="text" placeholder="Search case ID..." className="w-full pl-16 pr-6 py-5 rounded-3xl bg-gray-50 outline-none focus:ring-4 focus:ring-blue-100 transition-all font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
              </div>
              <div className="flex gap-4">
                <select className="px-6 py-5 rounded-3xl bg-gray-50 border-none outline-none font-black text-[10px] uppercase tracking-widest cursor-pointer" value={filterStatus} onChange={e => setFilterStatus(e.target.value)}>
                  <option value="All">All Status</option>
                  {Object.values(IssueStatus).map(st => <option key={st} value={st}>{st}</option>)}
                </select>
                <button 
