                  disabled={isExporting}
                  className="bg-slate-900 text-white px-8 py-5 rounded-3xl font-black text-[10px] uppercase tracking-widest flex items-center gap-3 hover:bg-black transition-all shadow-xl active:scale-95 disabled:opacity-50"
                >
                  {isExporting ? <Loader2 className="animate-spin" size={16} /> : <FileSpreadsheet size={16} />}
                  Export Master Log
                </button>
              </div>
            </div>

            <div className="bg-white rounded-[3rem] border border-gray-100 shadow-xl overflow-hidden print-visible">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50/50 border-b border-gray-100">
                    <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-widest">Grievance Identity</th>
                    <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">Protocol & AI</th>
                    <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-widest text-right">Operational Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {filtered.map((g) => (
                    <tr key={g.id} className="hover:bg-blue-50/20 transition-colors">
                      <td className="px-10 py-8">
                        <div className="flex items-center gap-8">
                          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-[10px] border ${g.isEmergency ? 'bg-red-50 border-red-200 text-red-600' : 'bg-gray-100 border-gray-200 text-blue-600'} no-print`}>
                            {g.id.split('-')[1]}
                          </div>
                          <div>
                            <div className="flex items-center gap-2 mb-1.5">
                              <span className="text-blue-600 font-black text-[10px] tracking-widest uppercase">{g.id}</span>
                              {g.isEmergency && <span className="bg-red-600 text-white text-[8px] font-black px-2 py-0.5 rounded-md uppercase animate-pulse">Emergency</span>}
                            </div>
                            <h4 className="font-black text-gray-900 mb-1.5 text-lg">{g.title}</h4>
                            <div className="flex items-center gap-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                              <span className="flex items-center gap-1.5"><MapPin size={12} className="text-red-400 no-print" /> {g.location.area || 'Zone Pulse 1'}</span>
                            </div>
                          </div>
                        </div>
                      </td>
                      <td className="px-10 py-8 text-center">
                         <div className="inline-flex items-center gap-2 px-4 py-2 bg-emerald-50 text-emerald-700 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-emerald-100">
