                            value={g.status}
                            onChange={(e) => onUpdateStatus(g.id, e.target.value as IssueStatus)}
                          >
                            {Object.values(IssueStatus).map(st => <option key={st} value={st} className="bg-white text-gray-900 font-bold">{st}</option>)}
                          </select>
