                      ></div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-gray-900 p-12 rounded-[3rem] text-white shadow-2xl relative overflow-hidden group print:bg-white print:text-black print:border-slate-200">
               <div className="absolute top-0 right-0 p-10 opacity-5 group-hover:scale-110 transition-transform duration-1000 no-print"><TrendingUp size={200} /></div>
