                      <Heart size={20} fill={g.votedByMe ? "currentColor" : "none"} />
                    </button>
                    <span className="text-xs font-black text-gray-900">{g.upvotes}</span>
                  </div>
                  <div>
                    <div className="flex items-center gap-3 mb-1">
                      <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest">{g.id}</span>
                      {g.isEmergency && (
                        <span className="bg-red-600 text-white text-[8px] font-black px-2 py-0.5 rounded-md uppercase animate-pulse flex items-center gap-1">
                          <AlertOctagon size={10} /> Emergency
                        </span>
                      )}
                    </div>
                    <h4 className="font-black text-gray-900 mb-1 group-hover:text-blue-700 transition-colors">{g.title}</h4>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest flex items-center gap-2">
                      <MapPin size={12} /> {g.location.area || "City Center"}
                    </p>
                  </div>
                </div>
                <div className="flex flex-col items-end gap-2">
                   <div className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest ${statusConfig[g.status].color}`}>
                    {g.status}
                  </div>
                  {g.slaDeadline && g.status !== IssueStatus.RESOLVED && (
                    <div className="flex items-center gap-1.5 text-[9px] font-black uppercase tracking-tight">
                      <Timer size={12} className="text-emerald-500" />
                      <SLACountdown deadline={g.slaDeadline} />
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="animate-fadeIn no-print">
          <div className="flex justify-between items-center mb-8">
            <button onClick={() => setSelectedIssue(null)} className="flex items-center gap-3 text-gray-400 font-black text-xs uppercase tracking-widest hover:text-blue-700 transition-colors">
              <ArrowLeft size={18} /> Back to tracker
            </button>
            <div className="flex gap-4">
              <button 
                onClick={() => downloadResolutionRoadmap(selectedIssue)}
                className="bg-slate-100 text-slate-700 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-2 hover:bg-slate-200 transition-all shadow-sm"
              >
                <FileText size={16} /> Resolution Roadmap
              </button>
              <button 
                onClick={downloadReceipt}
                className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-2 hover:bg-blue-700 transition-all shadow-lg shadow-blue-500/20"
              >
                <Printer size={16} /> Download Receipt (PDF)
              </button>
            </div>
          </div>

          <div className="bg-white p-8 md:p-12 rounded-[3.5rem] shadow-2xl border border-gray-100">
            <div className="flex flex-col md:flex-row justify-between items-start gap-8 mb-12">
              <div>
                <div className="flex items-center gap-3 mb-3">
                  <span className="text-blue-600 font-black text-xs uppercase tracking-[0.2em]">{selectedIssue.id}</span>
                  {selectedIssue.isEmergency && <span className="bg-red-600 text-white px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest animate-pulse">Emergency Escalation</span>}
                </div>
                <h2 className="text-4xl font-black text-gray-900 tracking-tight mb-4 leading-tight">{selectedIssue.title}</h2>
                <div className="flex flex-wrap items-center gap-4">
                  <div className={`px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest ${statusConfig[selectedIssue.status].color}`}>
                    {selectedIssue.status}
                  </div>
                  <div className="px-6 py-3 bg-slate-50 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest border border-slate-100">
                    Category: {selectedIssue.category}
                  </div>
                  {selectedIssue.slaDeadline && selectedIssue.status !== IssueStatus.RESOLVED && (
                    <div className="flex items-center gap-2 px-6 py-3 bg-emerald-50 text-emerald-700 rounded-2xl border border-emerald-100 font-black text-xs">
                      <Timer size={16} />
                      SLA: <SLACountdown deadline={selectedIssue.slaDeadline} />
                    </div>
                  )}
                </div>
              </div>
              <div className="p-4 bg-slate-50 rounded-3xl border border-slate-100">
                <div className="flex flex-col items-center gap-1">
                    <button 
                      onClick={(e) => {e.stopPropagation(); onUpvote?.(selectedIssue.id)}}
                      className={`p-4 rounded-2xl transition-all shadow-sm ${selectedIssue.votedByMe ? 'bg-red-500 text-white' : 'bg-white text-gray-400 hover:text-red-500'}`}
                    >
                      <Heart size={24} fill={selectedIssue.votedByMe ? "currentColor" : "none"} />
                    </button>
                    <span className="text-xs font-black text-gray-900 mt-2">{selectedIssue.upvotes} Endorsements</span>
                  </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Grievance Description</label>
                  <div className="bg-gray-50 p-8 rounded-[2.5rem] border border-gray-100">
                    <p className="text-gray-900 font-bold leading-relaxed italic text-lg">"{selectedIssue.description}"</p>
                  </div>
                </div>

                <div className="p-6 bg-blue-50/50 rounded-[2rem] border border-blue-100 flex items-center gap-4">
                  <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-blue-600 shadow-sm"><MapPin /></div>
                  <div>
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Verified Location Coordinate</p>
                    <p className="text-sm font-black text-gray-900">{selectedIssue.location.address || "Zone Pulse Active"}</p>
                    <p className="text-[10px] text-blue-600 font-bold mt-1 uppercase tracking-tight">{selectedIssue.location.area || 'Downtown Sector'}</p>
                  </div>
                </div>

                <div className="pt-8 mt-8 border-t border-slate-100">
                   <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-400"><Calendar size={20} /></div>
                      <div>
                        <p className="text-[9px] font-black text-slate-400 uppercase">Filed On</p>
                        <p className="text-xs font-black text-slate-900">{new Date(selectedIssue.createdAt).toLocaleString()}</p>
                      </div>
                   </div>
                </div>
              </div>

              {selectedIssue.image && (
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Evidence Capture</label>
                  <div className="rounded-[3rem] overflow-hidden border-[12px] border-gray-50 shadow-2xl bg-slate-100">
                    <img src={selectedIssue.image} className="w-full aspect-square object-cover" alt="Captured Evidence" />
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TrackPage;

