import React, { useState, useEffect } from 'react';
import html2canvas from 'html2canvas';
import { 
  Filter, 
  MapPin, 
  Tag, 
  ArrowUpRight,
  Download,
  Search,
  CheckCircle,
  Clock,
  AlertTriangle,
  Sparkles,
  TrendingUp,
  Inbox,
  ShieldAlert,
  Activity,
  CheckCircle2,
  XCircle,
  Wrench,
  Loader2,
  ChevronDown,
  RefreshCw,
  BarChart3,
  Map as MapIcon,
  AlertOctagon,
  FileSpreadsheet,
  Printer,
  ShieldCheck,
  FileText,
  Image as ImageIcon,
  X
} from 'lucide-react';
import { Grievance, IssueCategory, IssueStatus, IssuePriority } from '../types';

interface AdminPageProps {
  grievances: Grievance[];
  onUpdateStatus: (id: string, status: IssueStatus) => void;
  onUpdateGrievance?: (id: string, updates: Partial<Grievance>) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances, onUpdateStatus }) => {
  const [activeTab, setActiveTab] = useState<'list' | 'analytics'>('list');
  const [filterCategory, setFilterCategory] = useState<string>('All');
  const [filterStatus, setFilterStatus] = useState<string>('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [isExporting, setIsExporting] = useState(false);
  const [reportDate, setReportDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [exportLoading, setExportLoading] = useState(false);

  const filtered = grievances.filter(g => {
    const matchesCategory = filterCategory === 'All' || g.category === filterCategory;
    const matchesStatus = filterStatus === 'All' || g.status === filterStatus;
    const matchesSearch = g.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          g.id.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesStatus && matchesSearch;
  });

  const getHeatmapData = () => {
    const areas: Record<string, number> = {};
    grievances.forEach(g => {
      const area = g.location.area || 'Unknown';
      areas[area] = (areas[area] || 0) + 1;
    });
    return Object.entries(areas).sort((a, b) => b[1] - a[1]);
  };

  const downloadPDF = () => {
    setReportDate(new Date());
    setIsModalOpen(false);
    setTimeout(() => window.print(), 100);
  };

  const downloadExcel = () => {
    setExportLoading(true);
    const heatmap = getHeatmapData();
    let csvData = `CivicConnect Municipal Health Summary\nGenerated: ${new Date().toLocaleString()}\n\n`;
    csvData += `REGIONAL HOTSPOTS\nArea,Active Cases\n`;
    heatmap.forEach(([area, count]) => { csvData += `${area},${count}\n`; });
    csvData += `\nDETAILED LOG\nID,Title,Category,Priority,Status,Created At\n`;
    filtered.forEach(g => {
      csvData += `${g.id},${g.title},${g.category},${g.priority},${g.status},${new Date(g.createdAt).toLocaleDateString()}\n`;
    });

    const blob = new Blob([csvData], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `Municipal_Health_Summary_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
    setIsModalOpen(false);
    setExportLoading(false);
  };

  const downloadImage = async () => {
    setExportLoading(true);
    const element = document.getElementById('municipal-health-summary');
    if (element) {
      // Temporarily make it visible for capture
      element.style.display = 'block';
      element.style.position = 'fixed';
      element.style.left = '-9999px';

      try {
        const canvas = await html2canvas(element, { scale: 2, useCORS: true });
        const link = document.createElement('a');
        link.download = `Health_Snapshot_${new Date().getTime()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
      } catch (err) {
        console.error("Image capture failed", err);
      } finally {
        element.style.display = 'none';
        element.style.position = 'absolute';
        element.style.left = '0';
      }
    }
    setIsModalOpen(false);
    setExportLoading(false);
  };

  const stats = [
    { label: 'Active Reports', count: grievances.length, icon: <Inbox />, color: 'bg-blue-600' },
    { label: 'SLA Breaches', count: grievances.filter(g => g.slaDeadline && new Date(g.slaDeadline) < new Date() && g.status !== IssueStatus.RESOLVED).length, icon: <AlertTriangle />, color: 'bg-red-600' },
    { label: 'Emergency Active', count: grievances.filter(g => g.isEmergency && g.status !== IssueStatus.RESOLVED).length, icon: <AlertOctagon />, color: 'bg-orange-600' },
    { label: 'Avg Resolution', count: '42h', icon: <Clock />, color: 'bg-emerald-600' }
  ];

  return (
    <div className="bg-[#fcfcfd] min-h-screen pb-20 animate-fadeIn">
      {/* 
        GUARANTEED PRINT CSS: 
      */}
      <style>{`
        @media screen {
          #municipal-health-summary { display: none; }
        }
        @media print {
          body * {
            visibility: hidden;
          }
          #municipal-health-summary, #municipal-health-summary * {
            visibility: visible;
          }
          #municipal-health-summary {
            display: block !important;
            position: absolute;
            left: 0;
            top: 0;
            width: 100%;
            padding: 20mm;
            background: white !important;
            color: black !important;
          }
          @page {
            margin: 0;
          }
          table { width: 100% !important; border-collapse: collapse !important; margin-top: 20px; }
          th, td { border: 1px solid #ddd !important; padding: 10px !important; text-align: left !important; }
          th { background-color: #f3f4f6 !important; }
        }
      `}</style>

      {/* EXPORT MODAL */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="relative bg-white w-full max-w-lg rounded-[3rem] shadow-2xl p-10 animate-slideUp">
            <button onClick={() => setIsModalOpen(false)} className="absolute right-8 top-8 text-gray-400 hover:text-gray-900 transition-colors">
              <X size={24} />
            </button>
            <div className="text-center mb-10">
              <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-6">
                <Download size={32} />
              </div>
              <h3 className="text-3xl font-black text-slate-900 tracking-tight">Export Protocol</h3>
              <p className="text-gray-500 font-medium mt-2">Select the distribution format for the Health Summary</p>
            </div>

            <div className="grid grid-cols-1 gap-4">
              <button onClick={downloadPDF} className="group flex items-center justify-between p-6 rounded-2xl border-2 border-slate-50 hover:border-blue-500 hover:bg-blue-50 transition-all text-left">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-red-50 text-red-600 rounded-xl flex items-center justify-center shadow-sm group-hover:bg-red-600 group-hover:text-white transition-all">
                    <FileText size={24} />
                  </div>
                  <div>
                    <h4 className="font-black text-slate-900">Official Report (PDF)</h4>
                    <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Ideal for Municipal Audit</p>
                  </div>
                </div>
                <ArrowRight className="text-gray-300 group-hover:text-blue-600 group-hover:translate-x-1 transition-all" size={20} />
              </button>

              <button onClick={downloadExcel} className="group flex items-center justify-between p-6 rounded-2xl border-2 border-slate-50 hover:border-emerald-500 hover:bg-emerald-50 transition-all text-left">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center shadow-sm group-hover:bg-emerald-600 group-hover:text-white transition-all">
                    <FileSpreadsheet size={24} />
                  </div>
                  <div>
                    <h4 className="font-black text-slate-900">Raw Data (Excel/CSV)</h4>
                    <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Ideal for Analysis</p>
                  </div>
                </div>
                <ArrowRight className="text-gray-300 group-hover:text-emerald-600 group-hover:translate-x-1 transition-all" size={20} />
              </button>

              <button onClick={downloadImage} className="group flex items-center justify-between p-6 rounded-2xl border-2 border-slate-50 hover:border-purple-500 hover:bg-purple-50 transition-all text-left">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-purple-50 text-purple-600 rounded-xl flex items-center justify-center shadow-sm group-hover:bg-purple-600 group-hover:text-white transition-all">
                    <ImageIcon size={24} />
                  </div>
                  <div>
                    <h4 className="font-black text-slate-900">Visual Snapshot (PNG)</h4>
                    <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Ideal for Quick Sharing</p>
                  </div>
                </div>
                {exportLoading ? <Loader2 className="animate-spin text-purple-600" /> : <ArrowRight className="text-gray-300 group-hover:text-purple-600 group-hover:translate-x-1 transition-all" size={20} />}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* HIDDEN PRINT TEMPLATE */}
      <div id="municipal-health-summary">
        <div className="border-b-4 border-blue-600 pb-8 mb-10 flex justify-between items-end">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <ShieldCheck size={32} className="text-blue-600" />
              <span className="text-2xl font-black">CivicConnect Municipal Command</span>
            </div>
            <h1 className="text-4xl font-black uppercase tracking-tight">System Health Audit Report</h1>
            <p className="text-sm font-bold text-blue-600 uppercase tracking-widest mt-1">Audit Date: {reportDate.toLocaleString()}</p>
          </div>
          <div className="text-right">
            <p className="text-[10px] font-black text-slate-400 uppercase">Audit Reference</p>
            <p className="text-xl font-black text-slate-900">#AUD-{reportDate.getTime().toString().slice(-6)}</p>
          </div>
        </div>

        <div className="grid grid-cols-4 gap-4 mb-10">
          {stats.map((stat, i) => (
            <div key={i} className="border-2 border-slate-100 p-6 rounded-2xl">
              <p className="text-[10px] font-black uppercase text-slate-400 mb-1">{stat.label}</p>
              <p className="text-2xl font-black text-slate-900">{stat.count}</p>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-2 gap-10 mb-10">
          <div className="border border-slate-200 p-8 rounded-2xl">
            <h3 className="text-lg font-black text-slate-900 mb-4 uppercase">Regional Hotspots</h3>
            <div className="space-y-3">
              {getHeatmapData().map(([area, count]) => (
                <div key={area} className="flex justify-between border-b pb-2">
                  <span className="font-bold">{area}</span>
                  <span className="font-black text-blue-600">{count} Cases</span>
                </div>
              ))}
            </div>
          </div>
          <div className="border border-slate-200 p-8 rounded-2xl bg-slate-50">
            <h3 className="text-lg font-black text-slate-900 mb-4 uppercase">System Performance</h3>
            <div className="space-y-4">
              <div className="flex justify-between"><span>Service Delivery Index</span><span className="font-bold">98.2%</span></div>
              <div className="flex justify-between"><span>Citizen Engagement Score</span><span className="font-bold">Excellent</span></div>
              <div className="flex justify-between"><span>Resolution Latency (Avg)</span><span className="font-bold">42.8 Hours</span></div>
            </div>
          </div>
        </div>

        <h3 className="text-xl font-black mb-4 uppercase">Executive Summary: Critical & Active Logs</h3>
        <table>
          <thead>
            <tr>
              <th>ID</th>
              <th>Case Title</th>
              <th>Category</th>
              <th>Priority</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {filtered.slice(0, 20).map(g => (
              <tr key={g.id}>
                <td className="font-black text-blue-600">{g.id}</td>
                <td className="font-bold">{g.title}</td>
                <td>{g.category}</td>
                <td>{g.priority}</td>
                <td className="font-black uppercase">{g.status}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <div className="mt-20 pt-10 border-t-2 border-slate-200 flex justify-between items-end">
          <div>
            <p className="text-[10px] font-black uppercase text-slate-400">Authorized Authority Signature</p>
            <div className="w-56 h-12 border-b-2 border-slate-300 mt-4"></div>
