                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Grievance Description</label>
                  <div className="bg-gray-50 p-8 rounded-[2.5rem] border border-gray-100 italic text-lg text-gray-900 font-bold">
                    "{selectedIssue.description}"
