interface ReportPageProps {
  grievances: Grievance[];
  onAdd: (g: Grievance) => void;
}

const ReportPage: React.FC<ReportPageProps> = ({ grievances, onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [locationLoading, setLocationLoading] = useState(false);
  const [isAnonymous, setIsAnonymous] = useState(false);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    priority: IssuePriority.MEDIUM,
    description: '',
    image: '',
    location: null as Location | null,
    isEmergency: false
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, priority: string, reasoning: string } | null>(null);

  const handleLocation = () => {
    setLocationLoading(true);
    setTimeout(() => {
      setForm(prev => ({ ...prev, location: { latitude: 40.7128, longitude: -74.006, address: "Sector 14 Municipal Grid", area: "Downtown" } }));
      setLocationLoading(false);
    }, 1500);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 15) return;
    setAnalyzing(true);
    try {
      const catResult = await aiService.categorizeIssue(form.description);
      setForm(prev => ({ ...prev, category: catResult.category, priority: catResult.priority }));
      setAiInsight(catResult);
    } catch (e) {
      console.error(e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleSubmit = async () => {
    setLoading(true);
    const gId = `GRV-${Math.floor(1000 + Math.random() * 9000)}`;
    const newGrievance: Grievance = {
      id: gId,
      title: form.title || `${form.category} Report`,
      category: form.category,
      priority: form.isEmergency ? IssuePriority.CRITICAL : form.priority,
      description: form.description,
      image: form.image,
      location: form.location || { latitude: 0, longitude: 0, address: "Manual Entry" },
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight,
      upvotes: 0,
      isEmergency: form.isEmergency,
      isAnonymous: isAnonymous
    };

    // Pre-generate suggestions for admin
    try {
      newGrievance.aiSuggestions = await aiService.getActionSuggestions(newGrievance);
    } catch (e) { console.error(e); }

    setTimeout(() => {
      onAdd(newGrievance);
      setLoading(false);
      setSuccess(true);
      setTimeout(() => navigate('/track'), 3000);
    }, 2000);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-40 animate-fadeIn text-center">
        <div className="bg-emerald-100 text-emerald-600 p-8 rounded-[2.5rem] mb-8 animate-bounce"><CheckCircle2 size={80} /></div>
        <h2 className="text-4xl font-black text-gray-900 mb-4">Report Logged</h2>
        <div className="bg-blue-50 text-blue-700 px-8 py-4 rounded-2xl font-bold">Points Added! <Star size={16} className="inline fill-blue-700" /></div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-16 animate-fadeIn">
      <div className="bg-white p-12 rounded-[3.5rem] shadow-2xl border border-gray-50">
        <h1 className="text-3xl font-black mb-8">Lodge a Report</h1>

        <div className="space-y-8">
          <div className="flex items-center justify-between p-6 bg-slate-900 text-white rounded-[2rem]">
            <div className="flex items-center gap-4">
              <Shield size={32} className="text-blue-400" />
              <div>
                <p className="text-xs font-black uppercase tracking-widest text-blue-400">Whistleblower Mode</p>
                <p className="text-sm font-bold">Report anonymously without revealing identity.</p>
              </div>
            </div>
            <button 
              onClick={() => setIsAnonymous(!isAnonymous)}
              className={`px-6 py-3 rounded-2xl font-black text-xs transition-all ${isAnonymous ? 'bg-blue-600' : 'bg-slate-800 border border-slate-700'}`}
            >
              {isAnonymous ? 'Anonymous ON' : 'Make Anonymous'}
            </button>
          </div>

          <div>
            <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2 ml-2">Description</label>
            <textarea 
              rows={4}
              placeholder="Tell us what happened..."
              className="w-full px-8 py-6 rounded-[2.5rem] bg-gray-50 border-none focus:ring-4 focus:ring-blue-100 transition-all font-medium"
              value={form.description}
              onChange={e => setForm({...form, description: e.target.value})}
              onBlur={runAiAnalysis}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <button onClick={handleLocation} className="p-6 bg-blue-50 text-blue-600 rounded-[2rem] border border-blue-100 font-black text-xs flex flex-col items-center gap-2">
              <MapPin /> {form.location ? 'Location Locked' : 'Sync Location'}
            </button>
            <button onClick={() => fileInputRef.current?.click()} className="p-6 bg-slate-50 text-slate-600 rounded-[2rem] border border-slate-100 font-black text-xs flex flex-col items-center gap-2">
              <Camera /> {form.image ? 'Image Attached' : 'Attach Photo'}
              <input ref={fileInputRef} type="file" className="hidden" onChange={handleFileChange} />
            </button>
          </div>

          <button onClick={handleSubmit} disabled={loading} className="w-full py-6 bg-blue-600 text-white rounded-[2rem] font-black shadow-xl hover:bg-blue-700 transition-all flex items-center justify-center gap-3">
            {loading ? <Loader2 className="animate-spin" /> : <Send />}
            Finalize & Submit
          </button>
        </div>
      </div>
