          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowExportModal(false)}></div>
          <div className="relative bg-white w-full max-w-md rounded-[3rem] shadow-2xl p-10 animate-slideUp">
            <div className="text-center mb-8">
              <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-4">
                <Download size={32} />
              </div>
              <h3 className="text-2xl font-black text-slate-900">Download Receipt</h3>
              <p className="text-slate-500 font-bold text-sm mt-2">Get an official copy of your report</p>
            </div>

            <div className="space-y-4">
              <button onClick={handleExportPDF} className="w-full group flex items-center justify-between p-5 rounded-2xl border-2 border-slate-50 hover:border-blue-600 hover:bg-blue-50 transition-all">
                <div className="flex items-center gap-4">
                  <FileText className="text-red-500" />
                  <span className="font-black text-slate-900 text-sm">Official PDF Receipt</span>
                </div>
                <ArrowRight size={18} className="text-slate-300 group-hover:text-blue-600" />
              </button>

              <button onClick={handleExportExcel} className="w-full group flex items-center justify-between p-5 rounded-2xl border-2 border-slate-50 hover:border-emerald-600 hover:bg-emerald-50 transition-all">
                <div className="flex items-center gap-4">
                  <FileSpreadsheet className="text-emerald-500" />
                  <span className="font-black text-slate-900 text-sm">Data Sheet (XLSX)</span>
                </div>
                <ArrowRight size={18} className="text-slate-300 group-hover:text-emerald-600" />
              </button>

              <button onClick={handleExportImage} className="w-full group flex items-center justify-between p-5 rounded-2xl border-2 border-slate-50 hover:border-purple-600 hover:bg-purple-50 transition-all">
                <div className="flex items-center gap-4">
                  <ImageIcon className="text-purple-500" />
                  <span className="font-black text-slate-900 text-sm">Digital Snapshot (PNG)</span>
                </div>
                {isExporting ? <Loader2 className="animate-spin text-purple-600" size={18} /> : <ArrowRight size={18} className="text-slate-300 group-hover:text-purple-600" />}
              </button>
            </div>

            <button onClick={() => setShowExportModal(false)} className="mt-8 w-full py-4 text-slate-400 font-black text-[10px] uppercase tracking-widest hover:text-slate-900 transition-colors">
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* Header Area */}
      <div className="bg-white border-b border-slate-100 pt-32 pb-16 mb-12 shadow-sm">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-10">
            <div>
              <div className="inline-flex items-center gap-2 px-3 py-1 bg-blue-50 rounded-lg text-[10px] font-black uppercase tracking-widest text-blue-600 mb-4">
                <Globe size={12} /> Live Transparency
              </div>
              <h1 className="text-5xl font-black text-slate-900 tracking-tight">Transparency Center</h1>
              <p className="text-xl text-slate-400 font-medium mt-2">Public accountability ledger for city infrastructure.</p>
            </div>

            <div className="flex items-center gap-4 w-full md:w-auto">
              <div className="relative flex-grow md:w-80">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input 
                  type="text" 
                  placeholder="Track Case ID..."
                  className="w-full pl-16 pr-6 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none transition-all font-bold"
