import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Camera, MapPin, Send, Loader2, CheckCircle, Sparkles, ArrowLeft, ImageIcon, AlertCircle, X, ShieldAlert, ChevronDown, Mic, MicOff, CheckCircle2, AlertOctagon, Star, Shield
} from 'lucide-react';
import { IssueCategory, IssueStatus, IssuePriority, Grievance, Location } from '../types';
import { aiService } from '../services/geminiService';

interface ReportPageProps {
  grievances: Grievance[];
  onAdd: (g: Grievance) => void;
}

const ReportPage: React.FC<ReportPageProps> = ({ grievances, onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [locationLoading, setLocationLoading] = useState(false);
  const [isAnonymous, setIsAnonymous] = useState(false);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    priority: IssuePriority.MEDIUM,
    description: '',
    image: '',
    location: null as Location | null,
    isEmergency: false
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, priority: string, reasoning: string } | null>(null);

  const handleLocation = () => {
    setLocationLoading(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setForm(prev => ({ 
          ...prev, 
          location: { 
            latitude: pos.coords.latitude, 
            longitude: pos.coords.longitude, 
            address: "Auto-detected GPS Location", 
            area: "Municipal Grid A" 
          } 
        }));
        setLocationLoading(false);
      }, () => {
        setForm(prev => ({ ...prev, location: { latitude: 40.7128, longitude: -74.006, address: "Sector 14 Grid (Fallback)", area: "Downtown" } }));
        setLocationLoading(false);
      });
    } else {
      setLocationLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 15) return;
    setAnalyzing(true);
    try {
      const catResult = await aiService.categorizeIssue(form.description);
      setForm(prev => ({ ...prev, category: catResult.category, priority: catResult.priority }));
      setAiInsight(catResult);
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleSubmit = async () => {
    if (!form.description) return;
    setLoading(true);

    const gId = `GRV-${Math.floor(1000 + Math.random() * 9000)}`;
    const newGrievance: Grievance = {
      id: gId,
      title: form.title || `${form.category} Report`,
      category: form.category,
      priority: form.isEmergency ? IssuePriority.CRITICAL : form.priority,
      description: form.description,
      image: form.image,
      location: form.location || { latitude: 0, longitude: 0, address: "Manual Entry" },
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight,
      upvotes: 0,
      isEmergency: form.isEmergency,
      isAnonymous: isAnonymous
    };

    // Trigger submission immediately for speed
    onAdd(newGrievance);

    // Background task for official suggestions (non-blocking)
    aiService.getActionSuggestions(newGrievance).then(suggestions => {
       // In a real app, we'd update the DB. Here it's handled by reference if still in memory.
       newGrievance.aiSuggestions = suggestions;
    }).catch(e => console.error("Background AI failed", e));

    setTimeout(() => {
      setLoading(false);
      setSuccess(true);
      setTimeout(() => navigate('/track'), 2000);
    }, 800);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-40 animate-fadeIn text-center">
        <div className="bg-emerald-100 text-emerald-600 p-10 rounded-[3rem] mb-10 animate-bounce shadow-xl">
           <CheckCircle2 size={80} />
        </div>
        <h2 className="text-5xl font-black text-slate-900 mb-6 tracking-tight">Report Logged!</h2>
        <div className="bg-blue-600 text-white px-10 py-5 rounded-[2rem] font-black text-xl shadow-2xl flex items-center gap-3">
          Impact Score: +50 XP <Star size={24} className="fill-white" />
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-16 animate-fadeIn">
      <div className="bg-white p-12 md:p-16 rounded-[4rem] shadow-2xl border border-slate-50 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-blue-50 rounded-full blur-[100px] -z-10 opacity-50"></div>

        <h1 className="text-4xl font-black text-slate-900 mb-10 tracking-tight flex items-center gap-4">
           <Sparkles className="text-blue-600" /> Lodge a Report
        </h1>

        <div className="space-y-10">
          <div className="flex flex-col md:flex-row items-center justify-between p-8 bg-slate-900 text-white rounded-[2.5rem] shadow-xl group">
            <div className="flex items-center gap-6 mb-6 md:mb-0">
              <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg group-hover:scale-110 transition-transform">
                <Shield size={32} className="text-white" />
              </div>
              <div>
                <p className="text-xs font-black uppercase tracking-widest text-blue-400">Whistleblower Mode</p>
                <p className="text-sm font-bold opacity-80">Report anonymously. Identity hidden.</p>
              </div>
            </div>
            <button 
              onClick={() => setIsAnonymous(!isAnonymous)}
              className={`px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${isAnonymous ? 'bg-blue-600 text-white shadow-xl' : 'bg-slate-800 text-slate-400 border border-slate-700 hover:text-white'}`}
            >
              {isAnonymous ? 'Anonymous Mode: ACTIVE' : 'Toggle Anonymous'}
            </button>
          </div>

          <div>
            <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-4">Report Narrative</label>
            <div className="relative">
              <textarea 
                rows={5}
                placeholder="What did you observe? (e.g., Broken pipe on 5th Ave...)"
                className="w-full px-10 py-8 rounded-[3rem] bg-slate-50 border-2 border-transparent focus:border-blue-200 outline-none transition-all font-bold text-lg text-slate-900 shadow-inner"
                value={form.description}
                onChange={e => setForm({...form, description: e.target.value})}
                onBlur={runAiAnalysis}
              />
              {analyzing && (
                <div className="absolute bottom-6 right-10 flex items-center gap-2 text-blue-600 animate-pulse">
                   <Loader2 size={16} className="animate-spin" />
                   <span className="text-[10px] font-black uppercase tracking-widest">AI Categorizing...</span>
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <button onClick={handleLocation} className={`p-10 rounded-[3rem] font-black text-sm flex flex-col items-center gap-4 transition-all border-2 ${form.location ? 'bg-emerald-50 border-emerald-100 text-emerald-600 shadow-emerald-500/10' : 'bg-slate-50 border-slate-100 text-slate-600 hover:border-blue-200 hover:bg-blue-50'}`}>
              {locationLoading ? <Loader2 className="animate-spin" /> : <MapPin size={32} />}
              {form.location ? 'Coordinate Sync Active' : 'Sync GPS Location'}
            </button>
