          <div className="bg-white p-12 md:p-16 rounded-[4rem] shadow-2xl border border-slate-50 relative overflow-hidden">
            <h1 className="text-4xl font-black text-slate-900 mb-10 tracking-tight flex items-center gap-4">
               <Zap className="text-blue-600" /> System Report
            </h1>

            <div className="space-y-10">
              <div className="flex flex-col md:flex-row items-center justify-between p-8 bg-slate-900 text-white rounded-[2.5rem] shadow-xl">
                <div className="flex items-center gap-6">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${isAnonymous ? 'bg-blue-600 shadow-blue-500/50' : 'bg-slate-800'}`}>
                    <Shield size={28} />
                  </div>
                  <div>
                    <p className="text-[10px] font-black uppercase tracking-widest text-blue-400">Anonymity Module</p>
                    <p className="text-sm font-bold opacity-80">{isAnonymous ? 'Ghost Protocol Active' : 'Public Profile Active'}</p>
                  </div>
                </div>
                <button 
                  onClick={() => setIsAnonymous(!isAnonymous)}
                  className={`mt-4 md:mt-0 px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${isAnonymous ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400 border border-slate-700'}`}
                >
                  {isAnonymous ? 'Identity Hidden' : 'Make Anonymous'}
                </button>
              </div>

              <div>
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-4">Issue Description</label>
                <div className="relative group">
                  <textarea 
                    rows={5}
                    placeholder="Describe the issue in detail..."
                    className="w-full px-10 py-8 rounded-[3rem] bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none transition-all font-bold text-lg text-slate-900 shadow-inner group-hover:bg-white"
                    value={form.description}
                    onChange={e => setForm({...form, description: e.target.value})}
                    onBlur={runAiAnalysis}
                  />
                  {analyzing && (
                    <div className="absolute top-6 right-10 flex items-center gap-2 text-blue-600">
                       <Loader2 size={16} className="animate-spin" />
                       <span className="text-[10px] font-black uppercase tracking-widest animate-pulse">AI Scanning...</span>
                    </div>
                  )}
                </div>
              </div>

              {aiInsight && (
                <div className="bg-blue-50/50 border-2 border-blue-100 rounded-[3rem] p-8 animate-slideUp">
