                   </div>
                   <div className="flex flex-wrap gap-4 mb-6">
                      <div className="px-4 py-2 bg-white rounded-xl shadow-sm border border-blue-100">
                         <span className="text-[9px] font-black uppercase text-slate-400 block mb-1">Category</span>
                         <span className="text-xs font-black text-slate-900">{aiInsight.category}</span>
