                         <span className={`text-xs font-black ${aiInsight.priority === 'Critical' ? 'text-red-600' : 'text-blue-600'}`}>{aiInsight.priority}</span>
                      </div>
                   </div>
                   <p className="text-sm font-medium text-slate-500 italic">" {aiInsight.reasoning} "</p>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <button onClick={handleLocation} className={`p-10 rounded-[3rem] font-black text-xs uppercase tracking-widest flex flex-col items-center gap-4 transition-all border-2 ${form.location ? 'bg-emerald-50 border-emerald-100 text-emerald-600' : 'bg-slate-50 border-slate-100 text-slate-400 hover:bg-blue-50 hover:border-blue-200'}`}>
                  <MapPin size={32} />
