                <button onClick={() => fileInputRef.current?.click()} className={`p-10 rounded-[3rem] font-black text-xs uppercase tracking-widest flex flex-col items-center gap-4 transition-all border-2 ${form.image ? 'bg-blue-50 border-blue-100 text-blue-600' : 'bg-slate-50 border-slate-100 text-slate-400 hover:bg-blue-50 hover:border-blue-200'}`}>
