import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import { Location, Grievance, IssueStatus } from '../types';
import { MapPin, Navigation, Crosshair } from 'lucide-react';

interface LiveTrackingMapProps {
  mode: 'picker' | 'viewer';
  initialLocation?: Location | null;
  onLocationSelect?: (loc: Location) => void;
  grievances?: Grievance[];
  onGrievanceClick?: (g: Grievance) => void;
  className?: string;
}

const LiveTrackingMap: React.FC<LiveTrackingMapProps> = ({ 
  mode, 
  initialLocation, 
  onLocationSelect, 
  grievances, 
  onGrievanceClick,
  className = "h-[400px]"
}) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);
  const markerRef = useRef<L.Marker | null>(null);
  const markersGroupRef = useRef<L.LayerGroup | null>(null);

  const [address, setAddress] = useState<string>('');
  const [loading, setLoading] = useState(false);

  // Initialize Map
  useEffect(() => {
    if (!mapContainerRef.current || mapRef.current) return;

    const defaultCenter: [number, number] = initialLocation 
      ? [initialLocation.latitude, initialLocation.longitude] 
      : [11.1271, 78.6569]; // Default to Tamil Nadu area

    const map = L.map(mapContainerRef.current, {
      zoomControl: false,
      attributionControl: false
    }).setView(defaultCenter, mode === 'picker' ? 15 : 12);

    L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
      maxZoom: 19,
    }).addTo(map);

    L.control.zoom({ position: 'bottomright' }).addTo(map);

    mapRef.current = map;
    markersGroupRef.current = L.layerGroup().addTo(map);

    if (mode === 'picker') {
      map.on('click', (e) => {
        const { lat, lng } = e.latlng;
        updatePickerMarker(lat, lng);
      });

      if (initialLocation) {
        updatePickerMarker(initialLocation.latitude, initialLocation.longitude);
      }
    }

    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  // Update markers for viewer mode
  useEffect(() => {
    if (mode === 'viewer' && markersGroupRef.current && grievances) {
      markersGroupRef.current.clearLayers();
      grievances.forEach(g => {
        const color = g.status === IssueStatus.RESOLVED ? '#10b981' : '#2563eb';
        const icon = L.divIcon({
          className: 'custom-div-icon',
          html: `<div style="background-color: ${color}; width: 12px; height: 12px; border: 2px solid white; border-radius: 50%; box-shadow: 0 0 10px rgba(0,0,0,0.2);"></div>`,
          iconSize: [12, 12],
          iconAnchor: [6, 6]
        });

        const marker = L.marker([g.location.latitude, g.location.longitude], { icon })
          .on('click', () => onGrievanceClick?.(g))
          .addTo(markersGroupRef.current!);
      });
    }
  }, [grievances, mode]);

  const reverseGeocode = async (lat: number, lng: number) => {
    setLoading(true);
    try {
      const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}`);
      const data = await res.json();
      const displayAddr = data.display_name || 'Unknown Location';
      const area = data.address?.suburb || data.address?.neighbourhood || data.address?.city || 'Municipal Sector';

      setAddress(displayAddr);
      onLocationSelect?.({
        latitude: lat,
        longitude: lng,
        address: displayAddr,
        area: area
      });
    } catch (err) {
      console.error('Reverse geocoding failed', err);
    } finally {
      setLoading(false);
    }
  };

  const updatePickerMarker = (lat: number, lng: number) => {
    if (!mapRef.current) return;

    if (markerRef.current) {
      markerRef.current.setLatLng([lat, lng]);
    } else {
      const icon = L.divIcon({
        className: 'picker-icon',
        html: `<div class="bg-blue-600 p-2 rounded-full border-2 border-white shadow-xl text-white"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg></div>`,
        iconSize: [36, 36],
        iconAnchor: [18, 36]
      });

      markerRef.current = L.marker([lat, lng], { draggable: true, icon })
        .addTo(mapRef.current)
        .on('dragend', (e) => {
          const { lat, lng } = e.target.getLatLng();
          reverseGeocode(lat, lng);
        });
    }
    reverseGeocode(lat, lng);
  };

  const locateMe = () => {
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition((pos) => {
      const { latitude, longitude } = pos.coords;
      mapRef.current?.setView([latitude, longitude], 16);
      updatePickerMarker(latitude, longitude);
    });
  };

  return (
    <div className={`relative overflow-hidden rounded-[2.5rem] border border-slate-100 shadow-inner group ${className}`}>
      <div ref={mapContainerRef} className="w-full h-full z-10" />

      {mode === 'picker' && (
        <div className="absolute top-6 left-6 z-20 flex flex-col gap-3 max-w-[80%]">
          <button 
            onClick={locateMe}
            className="bg-white text-slate-900 px-5 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-2xl flex items-center gap-2 hover:bg-blue-600 hover:text-white transition-all active:scale-95"
          >
            <Crosshair size={14} /> Sync Current Position
          </button>

          {address && (
            <div className="bg-white/90 backdrop-blur-md p-4 rounded-2xl shadow-xl border border-white text-[10px] font-bold text-slate-600 animate-slideUp">
              <span className="text-blue-600 font-black block mb-1">SELECTED LOCATION</span>
              {loading ? 'Fetching Address...' : address}
            </div>
          )}
        </div>
      )}

      {/* Decorative Overlay */}
      <div className="absolute inset-0 pointer-events-none border-[12px] border-white/50 rounded-[2.5rem] z-20"></div>
    </div>
  );
};

export default LiveTrackingMap;

