    if (!selectedIssue) return;
    const data = getExportData(selectedIssue);
    const doc = new jsPDF() as any;

    doc.setFontSize(22);
    doc.setTextColor(37, 99, 235);
    doc.text(data.header, 105, 20, { align: "center" });

    doc.setFontSize(14);
    doc.setTextColor(31, 41, 55);
    doc.text(data.title, 105, 30, { align: "center" });

    doc.setFontSize(10);
    doc.setTextColor(107, 114, 128);
    doc.text(`ID: ${selectedIssue.id} | Timestamp: ${data.timestamp}`, 105, 38, { align: "center" });

    let currentY = 50;
    data.sections.forEach(section => {
      doc.autoTable({
        startY: currentY,
        head: [[section.name, "Details"]],
        body: section.data,
        theme: 'grid',
        headStyles: { fillColor: [31, 41, 55] },
        styles: { fontSize: 9 }
      });
      currentY = doc.lastAutoTable.finalY + 10;
    });

    doc.setFontSize(8);
    doc.setTextColor(156, 163, 175);
    doc.text(data.footer, 105, doc.internal.pageSize.height - 10, { align: "center" });

    doc.save(`CivicConnect_Receipt_${selectedIssue.id}.pdf`);
    setShowExportModal(false);
  };

  const handleExportExcel = () => {
    if (!selectedIssue) return;
    const data = getExportData(selectedIssue);
