      wsRows.push([section.name.toUpperCase()]);
      section.data.forEach(row => wsRows.push(row));
      wsRows.push([]);
    });

    wsRows.push([data.footer]);

    const ws = XLSX.utils.aoa_to_sheet(wsRows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Citizen Receipt");
