                <button onClick={() => setViewMode('map')} className={`px-6 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${viewMode === 'map' ? 'bg-white text-blue-600 shadow-xl' : 'text-slate-400'}`}>
