          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4">
        {viewMode === 'map' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 animate-slideUp">
             <div className="lg:col-span-8 bg-white rounded-[4rem] p-4 border border-slate-100 shadow-2xl relative min-h-[600px] overflow-hidden">
                <LiveTrackingMap 
