        subdomains: "abcd",
        maxZoom: 19
      }
    ).addTo(map);

    // Optional: click to place marker manually
    map.on("click", (e) => {
      placeMarker([e.latlng.lat, e.latlng.lng]);
    });
  }
}, []);


---

4️⃣ Place Marker Function

const placeMarker = (coords) => {
  const map = mapRef.current;
  if (!map) return;

  // Remove old marker if exists
  if (markerRef.current) map.removeLayer(markerRef.current);

  const marker = L.marker(coords, { draggable: true }).addTo(map);

  // Drag to update coordinates
  marker.on("dragend", (e) => {
    const { lat, lng } = e.target.getLatLng();
    reverseGeocode(lat, lng);
  });

  markerRef.current = marker;
  reverseGeocode(coords[0], coords[1]);
};


---

5️⃣ Reverse Geocode (Optional)

const reverseGeocode = async (lat, lng) => {
  try {
    const res = await axios.get(
      `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}&addressdetails=1`
    );
    setAddress(res.data.display_name);
  } catch {
    setAddress("Address not found");
  }
};


---

6️⃣ Important Notes

✅ Always wrap your locateMe button with an onClick. Browsers only allow geolocation when triggered by a user action.

<button onClick={locateMe}>Locate Me</button>

✅ Test on HTTPS or localhost.
✅ Ask users politely to allow location. You can show a tooltip:

> “To track your location on the map, please allow location access in your browser.”



✅ Use enableHighAccuracy: true for more precise GPS coordinates.


