import React, { useState } from 'react';
import { 
  Search, MapPin, ArrowLeft, Download, CheckCircle2, History, Clock, Map as MapIcon, 
  Grid, Globe, ShieldAlert, Activity, Filter, Info, X, FileText, FileSpreadsheet, Image as ImageIcon,
  ArrowRight, Loader2
} from 'lucide-react';
import { Grievance, IssueStatus } from '../types';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import * as XLSX from 'xlsx';
import html2canvas from 'html2canvas';
import LiveTrackingMap from '../components/LiveTrackingMap';

interface TrackPageProps {
  grievances: Grievance[];
  onUpvote?: (id: string) => void;
}

const TrackPage: React.FC<TrackPageProps> = ({ grievances }) => {
  const [searchId, setSearchId] = useState('');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [selectedIssue, setSelectedIssue] = useState<Grievance | null>(null);
  const [showExportModal, setShowExportModal] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  // Sequence: Platform Name, Title, Timestamp, User Info, Complaint Details, Location, Status, AI Priority, Resolution, Footer
  const getExportData = (issue: Grievance) => {
    return {
      header: "CivicConnect - Public Grievance Platform",
      title: "Complaint Submission Receipt",
      timestamp: new Date().toLocaleString(),
      sections: [
        { name: "1. Submitter Information", data: [["Account Type", "Verified Citizen"], ["Impact Points Earned", "+50 XP"]] },
        { name: "2. Complaint Details", data: [["Reference ID", issue.id], ["Subject", issue.title], ["Filed On", new Date(issue.createdAt).toLocaleString()], ["Description", issue.description]] },
        { name: "3. Location Information", data: [["Full Address", issue.location.address || "N/A"], ["Area", issue.location.area || "City Grid"], ["Coordinates", `${issue.location.latitude}, ${issue.location.longitude}`]] },
        { name: "4. Status & Insights", data: [["Current Status", issue.status], ["System Priority", issue.priority], ["AI Categorization", issue.category]] },
        { name: "5. Resolution Progress", data: [["SLA Deadline", issue.slaDeadline || "Calculating..."]] }
      ],
      footer: "CivicConnect Citizen Registry • Secure Record Receipt"
    };
  };

  const handleExportPDF = () => {
    if (!selectedIssue) return;
    const data = getExportData(selectedIssue);
    const doc = new jsPDF() as any;

    doc.setFontSize(22);
    doc.setTextColor(37, 99, 235);
    doc.text(data.header, 105, 20, { align: "center" });

    doc.setFontSize(14);
    doc.setTextColor(31, 41, 55);
    doc.text(data.title, 105, 30, { align: "center" });

    doc.setFontSize(10);
    doc.setTextColor(107, 114, 128);
    doc.text(`ID: ${selectedIssue.id} | Timestamp: ${data.timestamp}`, 105, 38, { align: "center" });

    let currentY = 50;
    data.sections.forEach(section => {
      doc.autoTable({
        startY: currentY,
        head: [[section.name, "Details"]],
        body: section.data,
        theme: 'grid',
        headStyles: { fillColor: [31, 41, 55] },
        styles: { fontSize: 9 }
      });
      currentY = doc.lastAutoTable.finalY + 10;
    });

    doc.setFontSize(8);
    doc.setTextColor(156, 163, 175);
    doc.text(data.footer, 105, doc.internal.pageSize.height - 10, { align: "center" });

    doc.save(`CivicConnect_Receipt_${selectedIssue.id}.pdf`);
    setShowExportModal(false);
  };

  const handleExportExcel = () => {
    if (!selectedIssue) return;
    const data = getExportData(selectedIssue);
    const wsRows = [
      [data.header],
      [data.title],
      [`Receipt ID: ${selectedIssue.id}`],
      [`Timestamp: ${data.timestamp}`],
      [],
    ];

    data.sections.forEach(section => {
      wsRows.push([section.name.toUpperCase()]);
      section.data.forEach(row => wsRows.push(row));
      wsRows.push([]);
    });

    wsRows.push([data.footer]);

    const ws = XLSX.utils.aoa_to_sheet(wsRows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Citizen Receipt");
    XLSX.writeFile(wb, `CivicConnect_Receipt_${selectedIssue.id}.xlsx`);
    setShowExportModal(false);
  };

  const handleExportImage = async () => {
    if (!selectedIssue) return;
    setIsExporting(true);
    const element = document.getElementById(`issue-card-${selectedIssue.id}`);
    if (element) {
      const canvas = await html2canvas(element, { scale: 2, backgroundColor: '#ffffff' });
      const link = document.createElement('a');
      link.download = `CivicConnect_Snapshot_${selectedIssue.id}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
    setIsExporting(false);
    setShowExportModal(false);
  };

  const handleGrievanceClick = (g: Grievance) => {
    setSelectedIssue(g);
    // Auto-scroll to the card in the list or highlight
    const element = document.getElementById(`issue-card-${g.id}`);
    element?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  return (
    <div className="bg-[#fcfcfd] min-h-screen pb-32 animate-fadeIn relative">
      {/* EXPORT MODAL */}
      {showExportModal && selectedIssue && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowExportModal(false)}></div>
          <div className="relative bg-white w-full max-w-md rounded-[3rem] shadow-2xl p-10 animate-slideUp">
            <div className="text-center mb-8">
              <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-4">
                <Download size={32} />
              </div>
              <h3 className="text-2xl font-black text-slate-900">Download Receipt</h3>
              <p className="text-slate-500 font-bold text-sm mt-2">Get an official copy of your report</p>
            </div>

            <div className="space-y-4">
              <button onClick={handleExportPDF} className="w-full group flex items-center justify-between p-5 rounded-2xl border-2 border-slate-50 hover:border-blue-600 hover:bg-blue-50 transition-all">
                <div className="flex items-center gap-4">
                  <FileText className="text-red-500" />
                  <span className="font-black text-slate-900 text-sm">Official PDF Receipt</span>
                </div>
                <ArrowRight size={18} className="text-slate-300 group-hover:text-blue-600" />
              </button>

              <button onClick={handleExportExcel} className="w-full group flex items-center justify-between p-5 rounded-2xl border-2 border-slate-50 hover:border-emerald-600 hover:bg-emerald-50 transition-all">
                <div className="flex items-center gap-4">
                  <FileSpreadsheet className="text-emerald-500" />
                  <span className="font-black text-slate-900 text-sm">Data Sheet (XLSX)</span>
                </div>
                <ArrowRight size={18} className="text-slate-300 group-hover:text-emerald-600" />
              </button>

              <button onClick={handleExportImage} className="w-full group flex items-center justify-between p-5 rounded-2xl border-2 border-slate-50 hover:border-purple-600 hover:bg-purple-50 transition-all">
                <div className="flex items-center gap-4">
                  <ImageIcon className="text-purple-500" />
                  <span className="font-black text-slate-900 text-sm">Digital Snapshot (PNG)</span>
                </div>
                {isExporting ? <Loader2 className="animate-spin text-purple-600" size={18} /> : <ArrowRight size={18} className="text-slate-300 group-hover:text-purple-600" />}
              </button>
            </div>

            <button onClick={() => setShowExportModal(false)} className="mt-8 w-full py-4 text-slate-400 font-black text-[10px] uppercase tracking-widest hover:text-slate-900 transition-colors">
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* Header Area */}
      <div className="bg-white border-b border-slate-100 pt-32 pb-16 mb-12 shadow-sm">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-10">
            <div>
              <div className="inline-flex items-center gap-2 px-3 py-1 bg-blue-50 rounded-lg text-[10px] font-black uppercase tracking-widest text-blue-600 mb-4">
                <Globe size={12} /> Live Transparency
              </div>
              <h1 className="text-5xl font-black text-slate-900 tracking-tight">Transparency Center</h1>
              <p className="text-xl text-slate-400 font-medium mt-2">Public accountability ledger for city infrastructure.</p>
            </div>

            <div className="flex items-center gap-4 w-full md:w-auto">
              <div className="relative flex-grow md:w-80">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input 
                  type="text" 
                  placeholder="Track Case ID..."
                  className="w-full pl-16 pr-6 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none transition-all font-bold"
                  value={searchId}
                  onChange={e => setSearchId(e.target.value)}
                />
              </div>
              <div className="flex bg-slate-100 p-1.5 rounded-3xl shadow-inner">
                <button onClick={() => setViewMode('list')} className={`px-6 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${viewMode === 'list' ? 'bg-white text-blue-600 shadow-xl' : 'text-slate-400'}`}>
                  <Grid size={18} className="inline mr-2" /> List
                </button>
                <button onClick={() => setViewMode('map')} className={`px-6 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${viewMode === 'map' ? 'bg-white text-blue-600 shadow-xl' : 'text-slate-400'}`}>
                  <MapIcon size={18} className="inline mr-2" /> Map
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4">
        {viewMode === 'map' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 animate-slideUp">
             <div className="lg:col-span-8 bg-white rounded-[4rem] p-4 border border-slate-100 shadow-2xl relative min-h-[600px] overflow-hidden">
                <LiveTrackingMap 
                  mode="viewer" 
                  grievances={grievances} 
                  onGrievanceClick={handleGrievanceClick}
                  className="h-[700px] rounded-[3.5rem]" 
                />

                <div className="absolute top-10 left-10 z-20 pointer-events-none">
                   <div className="bg-white/80 backdrop-blur-md p-6 rounded-[2rem] shadow-xl border border-white">
                    <h3 className="text-xl font-black text-slate-900 mb-1">Infrastructure Hub</h3>
                    <p className="text-slate-500 font-bold text-[10px] uppercase tracking-widest">Real-time Node Status</p>
                   </div>
                </div>

                <div className="absolute bottom-10 left-10 z-20 flex gap-6 bg-slate-900/90 backdrop-blur-md p-6 rounded-3xl border border-white/10">
                   <div className="flex items-center gap-3">
                      <div className="w-3 h-3 bg-emerald-500 rounded-full shadow-[0_0_10px_#10b981]"></div>
                      <span className="text-[10px] font-black uppercase text-white tracking-widest">Resolved</span>
                   </div>
                   <div className="flex items-center gap-3">
                      <div className="w-3 h-3 bg-blue-500 rounded-full shadow-[0_0_10px_#3b82f6]"></div>
                      <span className="text-[10px] font-black uppercase text-white tracking-widest">Active Report</span>
                   </div>
