import React, { useState, useEffect } from 'react';
import { 
  ArrowRight, Download, Search, Sparkles, Inbox, Activity, Loader2, Map as MapIcon, 
  AlertOctagon, FileSpreadsheet, FileText, X, Globe, ClipboardList, Clock, Users, 
  CheckCircle2, TrendingUp, ShieldCheck, Image as ImageIcon, MapPin
} from 'lucide-react';
import { Grievance, IssueStatus } from '../types';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  onUpdateStatus: (id: string, status: IssueStatus) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showExportModal, setShowExportModal] = useState(false);
  const [isGeneratingSuggestions, setIsGeneratingSuggestions] = useState(false);

  const stats = [
    { label: "Active Queue", val: grievances.filter(g => g.status !== IssueStatus.RESOLVED).length, icon: <Activity />, color: "text-blue-600" },
    { label: "Avg Response", val: "2.4h", icon: <Clock />, color: "text-emerald-600" },
    { label: "SLA Breaches", val: "0", icon: <AlertOctagon />, color: "text-red-600" },
  ];

  const filtered = grievances.filter(g => 
    g.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    g.id.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Trigger AI Suggestion on selection if missing
  useEffect(() => {
    const fetchSuggestions = async () => {
      if (selectedCase && !selectedCase.aiSuggestions && !isGeneratingSuggestions) {
        setIsGeneratingSuggestions(true);
        try {
          const suggestions = await aiService.getActionSuggestions(selectedCase);
          selectedCase.aiSuggestions = suggestions;
          setSelectedCase({ ...selectedCase });
        } catch (e) {
          console.error("AI Generation failed", e);
        } finally {
          setIsGeneratingSuggestions(false);
        }
      }
    };
    fetchSuggestions();
  }, [selectedCase]);

  const getExportData = (singleCase: Grievance | null = null) => {
    const timestamp = new Date().toLocaleString();
    const footer = "CivicConnect Municipal Protocol v4.0 • Authorized Audit Record";

    // Exact sequence as requested: Platform, Title, Date/Time, User/Admin info, Complaint, Location, Status, AI Insights, Resolution, Footer
    if (singleCase) {
      return {
        header: "CivicConnect - Public Grievance Platform",
        title: `Individual Case Audit: ${singleCase.id}`,
        timestamp,
        sections: [
          { name: "1. Administrative Information", data: [["Auditor Role", "System Administrator"], ["Audit Date", timestamp]] },
          { name: "2. Complaint Details", data: [["ID", singleCase.id], ["Subject", singleCase.title], ["Summary", singleCase.description]] },
          { name: "3. Location Information", data: [["Full Address", singleCase.location.address || "N/A"], ["Area", singleCase.location.area || "City Wide"], ["Coordinates", `${singleCase.location.latitude}, ${singleCase.location.longitude}`]] },
          { name: "4. Status & Insights", data: [["Current Status", singleCase.status], ["Priority", singleCase.priority], ["AI Category", singleCase.category]] },
          { name: "5. Resolution Summary", data: [["Assigned Dept", singleCase.aiSuggestions?.department || "Pending Assignment"], ["Manpower Est.", singleCase.aiSuggestions?.manpower || "N/A"]] }
        ],
        footer
      };
    }

    return {
      header: "CivicConnect - Public Grievance Platform",
      title: "Municipal System Health Audit",
      timestamp,
      sections: [
        { name: "1. System Performance", data: [["Total Reports", grievances.length], ["Active Cases", stats[0].val], ["Generated At", timestamp]] },
        { name: "2. Department Performance Reports", data: filtered.slice(0, 15).map(g => [g.id, g.category, g.status]) },
        { name: "3. Pending vs Resolved Analytics", data: [["Resolved", grievances.filter(x => x.status === IssueStatus.RESOLVED).length], ["Pending", grievances.filter(x => x.status !== IssueStatus.RESOLVED).length]] }
      ],
      footer
    };
  };

  const handleExportPDF = () => {
    const data = getExportData(selectedCase);
    const doc = new jsPDF() as any;

    doc.setFontSize(22);
    doc.setTextColor(37, 99, 235);
    doc.text(data.header, 105, 20, { align: "center" });

    doc.setFontSize(14);
    doc.setTextColor(31, 41, 55);
    doc.text(data.title, 105, 30, { align: "center" });

    doc.setFontSize(10);
    doc.setTextColor(107, 114, 128);
    doc.text(`Generated: ${data.timestamp}`, 105, 38, { align: "center" });

    let currentY = 50;
    data.sections.forEach(section => {
      doc.autoTable({
        startY: currentY,
        head: [[section.name, "Details"]],
        body: section.data,
        theme: 'grid',
        headStyles: { fillColor: [31, 41, 55] },
        styles: { fontSize: 9 }
      });
      currentY = doc.lastAutoTable.finalY + 10;
    });

    doc.setFontSize(8);
    doc.setTextColor(156, 163, 175);
    doc.text(data.footer, 105, doc.internal.pageSize.height - 10, { align: "center" });

    doc.save(`CivicConnect_Admin_Report_${Date.now()}.pdf`);
    setShowExportModal(false);
  };

  const handleExportExcel = () => {
    const data = getExportData(selectedCase);
    const wsRows = [
      [data.header],
      [data.title],
      [`Timestamp: ${data.timestamp}`],
      [],
    ];

    data.sections.forEach(section => {
      wsRows.push([section.name.toUpperCase()]);
      section.data.forEach(row => wsRows.push(row));
      wsRows.push([]);
    });

    wsRows.push([data.footer]);

    const ws = XLSX.utils.aoa_to_sheet(wsRows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Audit Data");
    XLSX.writeFile(wb, `CivicConnect_Export_${Date.now()}.xlsx`);
    setShowExportModal(false);
  };

  return (
    <div className="bg-[#f8fafc] min-h-screen pb-32 pt-32 animate-fadeIn relative">
      {/* EXPORT MODAL */}
      {showExportModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowExportModal(false)}></div>
          <div className="relative bg-white w-full max-w-md rounded-[3rem] shadow-2xl p-10 animate-slideUp">
            <div className="text-center mb-8">
              <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-4">
                <Download size={32} />
              </div>
              <h3 className="text-2xl font-black text-slate-900">Export Report</h3>
              <p className="text-slate-500 font-bold text-sm mt-2">Choose your preferred audit format</p>
            </div>

            <div className="space-y-4">
              <button onClick={handleExportPDF} className="w-full group flex items-center justify-between p-5 rounded-2xl border-2 border-slate-50 hover:border-blue-600 hover:bg-blue-50 transition-all">
                <div className="flex items-center gap-4">
                  <FileText className="text-red-500" />
                  <span className="font-black text-slate-900 text-sm">Standard Audit (PDF)</span>
                </div>
                <ArrowRight size={18} className="text-slate-300 group-hover:text-blue-600" />
              </button>

              <button onClick={handleExportExcel} className="w-full group flex items-center justify-between p-5 rounded-2xl border-2 border-slate-50 hover:border-emerald-600 hover:bg-emerald-50 transition-all">
                <div className="flex items-center gap-4">
                  <FileSpreadsheet className="text-emerald-500" />
                  <span className="font-black text-slate-900 text-sm">Data Sheet (XLSX)</span>
                </div>
                <ArrowRight size={18} className="text-slate-300 group-hover:text-emerald-600" />
              </button>
            </div>

            <button onClick={() => setShowExportModal(false)} className="mt-8 w-full py-4 text-slate-400 font-black text-[10px] uppercase tracking-widest hover:text-slate-900 transition-colors">
              Dismiss
            </button>
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-4">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-10 mb-16">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 bg-slate-900 text-white rounded-lg text-[10px] font-black uppercase tracking-widest mb-4 shadow-xl">
              <ShieldCheck size={12} className="text-emerald-400" /> Authority Command
            </div>
            <h1 className="text-5xl font-black text-slate-900 tracking-tight">System Oversight</h1>
            <p className="text-xl text-slate-400 font-medium mt-2">Managing the pulse of public services.</p>
          </div>
          <div className="flex flex-wrap items-center gap-4">
            <button 
              onClick={() => { setSelectedCase(null); setShowExportModal(true); }}
              className="bg-white text-slate-900 border border-slate-200 px-6 py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-2 hover:bg-slate-50 transition-all shadow-sm"
            >
              <Download size={18} /> Download All Reports
            </button>
            <div className="flex items-center gap-6 bg-white p-3 rounded-[2.5rem] shadow-xl border border-slate-100">
               {stats.map((s, i) => (
                 <div key={i} className={`flex items-center gap-4 px-6 ${i !== 0 ? 'border-l border-slate-100' : ''}`}>
                    <div className={`${s.color} p-2 bg-slate-50 rounded-xl`}>{s.icon}</div>
                    <div>
                      <span className="block text-[9px] font-black text-slate-400 uppercase tracking-widest">{s.label}</span>
                      <span className="text-xl font-black text-slate-900">{s.val}</span>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          <div className="lg:col-span-8 space-y-8">
             <div className="relative mb-8">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={24} />
                <input 
                  type="text" 
                  placeholder="Filter case identity or subject..."
                  className="w-full pl-16 pr-8 py-6 rounded-[2.5rem] bg-white border-2 border-transparent focus:border-blue-500 shadow-2xl outline-none font-bold text-lg transition-all"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
             </div>

             <div className="bg-white rounded-[3.5rem] border border-slate-50 shadow-2xl overflow-hidden">
                <table className="w-full text-left">
                  <thead>
                    <tr className="bg-slate-50/50 border-b border-slate-100">
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400">Grievance Identity</th>
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400">Category</th>
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {filtered.map(g => (
                      <tr 
                        key={g.id} 
                        className={`hover:bg-blue-50/20 cursor-pointer transition-colors group ${selectedCase?.id === g.id ? 'bg-blue-50/80' : ''}`}
                        onClick={() => setSelectedCase(g)}
                      >
                        <td className="px-10 py-8">
                           <span className="text-blue-600 font-black text-[10px] uppercase tracking-widest block mb-2">{g.id}</span>
