                      <button onClick={() => setSelectedCase(null)} className="w-10 h-10 bg-slate-100 text-slate-400 rounded-2xl flex items-center justify-center hover:bg-red-50 hover:text-red-500 transition-all"><X size={20}/></button>
                    </div>
