                            </div>
                         </div>

                         <div className="pt-6 border-t border-white/10">
                            <p className="text-[10px] font-black uppercase mb-4 text-blue-400 tracking-widest">Resolution Protocol:</p>
                            <ul className="space-y-4">
                               {selectedCase.aiSuggestions.steps.map((step, idx) => (
                                 <li key={idx} className="text-xs font-medium flex gap-3 text-slate-300">
