                    ) : (
                      <div className="flex flex-col items-center py-10 opacity-50">
                        <Loader2 className="animate-spin mb-4" />
                        <p className="text-[10px] font-black uppercase tracking-widest">Generating Blueprint...</p>
                      </div>
                    )}
