          </div>
        </div>
      )}
    </nav>
  );
};

const App: React.FC = () => {
  const [grievances, setGrievances] = useState<Grievance[]>(() => {
    try {
      const saved = localStorage.getItem('civic_grievances');
      const parsed = saved ? JSON.parse(saved) : INITIAL_GRIEVANCES;
      return Array.isArray(parsed) ? parsed : INITIAL_GRIEVANCES;
    } catch {
      return INITIAL_GRIEVANCES;
    }
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const admin = localStorage.getItem('adminLoggedIn');
    const userEmail = localStorage.getItem('loggedInUser');
    if (admin === 'yes') return { email: 'admin@civic.gov', role: 'admin', points: 0, trustScore: 100, badges: [] };
    if (userEmail) return { email: userEmail, role: 'citizen', points: 100, trustScore: 75, badges: ['🥉 Newcomer'] };
    return null;
  });

  useEffect(() => {
    localStorage.setItem('civic_grievances', JSON.stringify(grievances));
  }, [grievances]);

  useEffect(() => {
    localStorage.setItem('users', JSON.stringify(DEMO_CITIZENS));
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    localStorage.removeItem('loggedInUser');
    localStorage.removeItem('adminLoggedIn');
    setCurrentUser(null);
  };

  const addGrievance = (g: Grievance) => {
    setGrievances(prev => [g, ...prev]);
    if (currentUser?.role === 'citizen') {
      setCurrentUser(curr => curr ? { ...curr, points: curr.points + 50 } : null);
    }
  };

  const updateStatus = (id: string, status: IssueStatus) => {
    setGrievances(prev => prev.map(g => g.id === id ? { ...g, status, updatedAt: new Date().toISOString() } : g));
  };

  const toggleUpvote = (id: string) => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        const voted = !g.votedByMe;
        return { ...g, votedByMe: voted, upvotes: voted ? g.upvotes + 1 : g.upvotes - 1 };
      }
      return g;
    }));
  };

  return (
    <Router>
      <div className="flex flex-col min-h-screen">
        <Navbar user={currentUser} onLogout={handleLogout} grievances={grievances} />
        <main className="flex-grow pt-16">
          <Routes>
            <Route path="/" element={<HomePage grievances={grievances} user={currentUser} />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/login" element={<LoginPage onLogin={handleLogin} />} />
            <Route path="/report" element={currentUser ? <ReportPage grievances={grievances} onAdd={addGrievance} /> : <Navigate to="/login" />} />
            <Route path="/track" element={<TrackPage grievances={grievances} onUpvote={toggleUpvote} />} />
            <Route path="/admin" element={currentUser?.role === 'admin' ? <AdminPage grievances={grievances} onUpdateStatus={updateStatus} /> : <Navigate to="/login" />} />
            <Route path="/contact" element={<ContactPage />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  Search, MapPin, ArrowLeft, Download, CheckCircle2, History, Clock, Map as MapIcon, 
  Grid, Globe, ShieldAlert, Activity, Filter, Info, X, FileText, FileSpreadsheet, Image as ImageIcon,
  ArrowRight, Loader2, ThumbsUp, Heart, TrendingUp, Sparkles, Star, AlertOctagon, AlertTriangle
} from 'lucide-react';
import { Grievance, IssueStatus, IssuePriority } from '../types';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import * as XLSX from 'xlsx';
import html2canvas from 'html2canvas';
import LiveTrackingMap from '../components/LiveTrackingMap';

interface TrackPageProps {
  grievances: Grievance[];
  onUpvote?: (id: string) => void;
}

type FilterType = 'priority' | 'xp' | 'fixes' | 'emergencies';

const TrackPage: React.FC<TrackPageProps> = ({ grievances, onUpvote }) => {
  const [searchId, setSearchId] = useState('');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [selectedIssue, setSelectedIssue] = useState<Grievance | null>(null);
  const [showExportModal, setShowExportModal] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [activeFilter, setActiveFilter] = useState<FilterType>('priority');

  // Unified Filtering and Sorting Logic
  const filteredGrievances = useMemo(() => {
    let result = [...grievances];

    // Search filter
    if (searchId) {
      result = result.filter(g => 
        g.id.toLowerCase().includes(searchId.toLowerCase()) || 
        g.title.toLowerCase().includes(searchId.toLowerCase())
      );
    }

    // Category filter
    switch (activeFilter) {
      case 'priority':
        // Default: Sort by upvotes
        result.sort((a, b) => b.upvotes - a.upvotes);
        break;
      case 'xp':
        // High XP: Issues with high engagement (upvotes > 5)
        result = result.filter(g => g.upvotes > 5);
        result.sort((a, b) => b.upvotes - a.upvotes);
        break;
      case 'fixes':
        // Recent Fixes: Only resolved issues
        result = result.filter(g => g.status === IssueStatus.RESOLVED);
        result.sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
        break;
      case 'emergencies':
        // Emergencies: Emergency flag or Critical priority
        result = result.filter(g => g.isEmergency || g.priority === IssuePriority.CRITICAL);
        result.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
        break;
    }

    return result;
  }, [grievances, searchId, activeFilter]);

  const getExportData = (issue: Grievance) => {
    return {
      header: "CivicConnect - Public Grievance Platform",
      title: "Complaint Submission Receipt",
      timestamp: new Date().toLocaleString(),
      sections: [
        { name: "1. Submitter Information", data: [["Account Type", "Verified Citizen"], ["Impact Points Earned", "+50 XP"]] },
        { name: "2. Complaint Details", data: [["Reference ID", issue.id], ["Subject", issue.title], ["Filed On", new Date(issue.createdAt).toLocaleString()], ["Description", issue.description]] },
        { name: "3. Location Information", data: [["Full Address", issue.location.address || "N/A"], ["Area", issue.location.area || "City Grid"], ["Coordinates", `${issue.location.latitude}, ${issue.location.longitude}`]] },
        { name: "4. Status & Insights", data: [["Current Status", issue.status], ["System Priority", issue.priority], ["AI Categorization", issue.category]] },
        { name: "5. Resolution Progress", data: [["SLA Deadline", issue.slaDeadline || "Calculating..."]] }
      ],
      footer: "CivicConnect Citizen Registry • Secure Record Receipt"
    };
  };

  const handleExportPDF = () => {
    if (!selectedIssue) return;
    const data = getExportData(selectedIssue);
    const doc = new jsPDF() as any;

    doc.setFontSize(22);
    doc.setTextColor(37, 99, 235);
    doc.text(data.header, 105, 20, { align: "center" });
    doc.save(`CivicConnect_Receipt_${selectedIssue.id}.pdf`);
    setShowExportModal(false);
  };

  const handleExportExcel = () => {
    if (!selectedIssue) return;
    const data = getExportData(selectedIssue);
    const wsRows = [
      [data.header], [data.title], [`Receipt ID: ${selectedIssue.id}`], [`Timestamp: ${data.timestamp}`], [],
    ];
    data.sections.forEach(section => {
      wsRows.push([section.name.toUpperCase()]);
      section.data.forEach(row => wsRows.push(row));
      wsRows.push([]);
    });
    wsRows.push([data.footer]);
    const ws = XLSX.utils.aoa_to_sheet(wsRows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Citizen Receipt");
    XLSX.writeFile(wb, `CivicConnect_Receipt_${selectedIssue.id}.xlsx`);
    setShowExportModal(false);
  };

  const handleExportImage = async () => {
    if (!selectedIssue) return;
    setIsExporting(true);
    const element = document.getElementById(`issue-card-${selectedIssue.id}`);
    if (element) {
      const canvas = await html2canvas(element, { scale: 2, backgroundColor: '#ffffff' });
      const link = document.createElement('a');
      link.download = `CivicConnect_Snapshot_${selectedIssue.id}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
    setIsExporting(false);
    setShowExportModal(false);
  };

  const handleGrievanceClick = (g: Grievance) => {
    setSelectedIssue(g);
    const element = document.getElementById(`issue-card-${g.id}`);
    element?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

