  const [isExporting, setIsExporting] = useState(false);
  const [activeFilter, setActiveFilter] = useState<FilterType>('priority');

  // Unified Filtering and Sorting Logic
  const filteredGrievances = useMemo(() => {
    let result = [...grievances];
    if (searchId) {
      result = result.filter(g => 
        g.id.toLowerCase().includes(searchId.toLowerCase()) || 
        g.title.toLowerCase().includes(searchId.toLowerCase()) ||
        g.dnaSignature?.toLowerCase().includes(searchId.toLowerCase())
      );
    }

    switch (activeFilter) {
      case 'priority': result.sort((a, b) => b.upvotes - a.upvotes); break;
      case 'xp': result = result.filter(g => g.upvotes > 5); result.sort((a, b) => b.upvotes - a.upvotes); break;
      case 'fixes': result = result.filter(g => g.status === IssueStatus.RESOLVED); break;
      case 'emergencies': result = result.filter(g => g.isEmergency || g.priority === IssuePriority.CRITICAL); break;
    }
    return result;
  }, [grievances, searchId, activeFilter]);

  const handleExportPDF = () => {
    if (!selectedIssue) return;
    const doc = new jsPDF() as any;
    doc.setFontSize(22);
    doc.setTextColor(37, 99, 235);
    doc.text("CivicConnect Proprietary Audit", 105, 20, { align: "center" });
    doc.save(`CivicConnect_Audit_${selectedIssue.id}.pdf`);
    setShowExportModal(false);
