                  <p className="text-slate-400 text-sm font-medium leading-relaxed mb-8">Select a case node to visualize its ResolveChain™ and verify IssueDNA™ integrity.</p>
               </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

