import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import * as XLSX from 'xlsx';
import html2canvas from 'html2canvas';
import { Grievance, IssueStatus } from '../types';

export const downloadService = {
  /**
   * Generates a professional PDF Audit for a single grievance.
   */
  async exportGrievancePDF(g: Grievance) {
    const doc = new jsPDF() as any;

    // Header
    doc.setFillColor(2, 6, 23); // Slate-950
    doc.rect(0, 0, 210, 40, 'F');

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont('helvetica', 'bold');
    doc.text('CIVICCONNECT™ MUNICIPAL AUDIT', 14, 25);

    doc.setFontSize(10);
    doc.text(`AUDIT ID: ${g.id} | DNA: ${g.dnaSignature}`, 14, 32);

    // Body
    doc.setTextColor(33, 33, 33);
    doc.setFontSize(16);
    doc.text(g.title, 14, 55);

    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.text(`Category: ${g.category}`, 14, 62);
    doc.text(`Status: ${g.status}`, 14, 67);
    doc.text(`Priority: ${g.priority}`, 14, 72);
    doc.text(`Created: ${new Date(g.createdAt).toLocaleString()}`, 14, 77);

    doc.setFont('helvetica', 'bold');
    doc.text('Narrative:', 14, 87);
    doc.setFont('helvetica', 'normal');
    const splitDesc = doc.splitTextToSize(g.description, 180);
    doc.text(splitDesc, 14, 92);

    // ResolveChain™ Table
    const tableData = g.resolveChain.map(event => [
      new Date(event.timestamp).toLocaleString(),
      event.status,
      event.action,
      event.actor
    ]);

    doc.autoTable({
      startY: 110,
      head: [['Timestamp', 'Status', 'Action Performed', 'Authored By']],
      body: tableData,
      theme: 'grid',
      headStyles: { fillColor: [37, 99, 235], textColor: 255 },
      styles: { fontSize: 8 }
    });

    doc.setFontSize(8);
    doc.setTextColor(150, 150, 150);
    doc.text('This is a proprietary electronic audit generated by CivicConnect™ Command OS.', 14, doc.internal.pageSize.height - 10);

    doc.save(`Audit_${g.dnaSignature}.pdf`);
  },

  /**
   * Exports an array of grievances to an Excel Ledger.
   */
  exportGrievancesExcel(data: Grievance[], filename = 'City_Health_Ledger.xlsx') {
    const flattened = data.map(g => ({
      'ID': g.id,
      'DNA Signature': g.dnaSignature,
      'Title': g.title,
      'Category': g.category,
      'Priority': g.priority,
      'Status': g.status,
      'Area': g.location?.area || 'N/A',
      'Address': g.location?.address || 'N/A',
      'Created At': new Date(g.createdAt).toLocaleString(),
      'Upvotes': g.upvotes
    }));

    const worksheet = XLSX.utils.json_to_sheet(flattened);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Grievances');
    XLSX.writeFile(workbook, filename);
  },

  /**
   * Captures a DOM element and downloads it as a PNG image.
   */
  async captureSnapshot(elementId: string, filename = 'Audit_Snapshot.png') {
    const element = document.getElementById(elementId);
    if (!element) return;

    const canvas = await html2canvas(element, {
      backgroundColor: '#ffffff',
      scale: 2, // High resolution
      logging: false,
      useCORS: true
    });

    const link = document.createElement('a');
    link.download = filename;
    link.href = canvas.toDataURL('image/png');
    link.click();
  }
};

