import React, { useState, useEffect, useMemo } from 'react';
import { 
  Download, Search, Inbox, Activity, Loader2, 
  X, ShieldCheck, Navigation, Sparkles, FileSpreadsheet, ChevronDown,
  FileText, Image as ImageIcon, Fingerprint, ExternalLink
} from 'lucide-react';
import { Grievance, IssueStatus } from '../types';
import { downloadService } from '../services/downloadService';

interface AdminPageProps {
  grievances: Grievance[];
  onUpdateStatus: (id: string, status: IssueStatus) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [optimizingRoute, setOptimizingRoute] = useState(false);
  const [routePlan, setRoutePlan] = useState<Grievance[] | null>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportingType, setExportingType] = useState<string | null>(null);

  const stats = [
    { label: "Active Queue", val: Array.isArray(grievances) ? grievances.filter(g => g && g.status !== IssueStatus.RESOLVED).length : 0, icon: <Activity />, color: "text-blue-600" },
    { label: "SmartRoute™ Saving", val: "18%", icon: <Navigation />, color: "text-emerald-600" },
    { label: "Verified DNA", val: Array.isArray(grievances) ? grievances.length : 0, icon: <ShieldCheck />, color: "text-indigo-600" },
  ];

  const filtered = useMemo(() => {
    if (!Array.isArray(grievances)) return [];
    return grievances.filter(g => {
      if (!g) return false;
      const title = g.title?.toLowerCase() || '';
      const id = g.id?.toLowerCase() || '';
      const dna = g.dnaSignature?.toLowerCase() || '';
      const term = searchTerm.toLowerCase();
      return title.includes(term) || id.includes(term) || dna.includes(term);
    });
  }, [grievances, searchTerm]);

  const runSmartRoute = () => {
    if (!Array.isArray(grievances)) return;
    setOptimizingRoute(true);
    setTimeout(() => {
      const active = grievances.filter(g => g && g.status !== IssueStatus.RESOLVED).slice(0, 3);
      setRoutePlan(active);
      setOptimizingRoute(false);
    }, 2000);
  };

  const handleGlobalExport = () => {
    setIsExporting(true);
    try {
      downloadService.exportGrievancesExcel(grievances, `Municipal_Audit_Log_${new Date().toLocaleDateString()}.xlsx`);
    } catch (e) {
      console.error(e);
    } finally {
      setTimeout(() => setIsExporting(false), 1000);
    }
  };

  const handleCaseExport = async (type: 'pdf' | 'excel' | 'snapshot') => {
    if (!selectedCase) return;
    setExportingType(type);

    try {
      if (type === 'pdf') {
        await downloadService.exportGrievancePDF(selectedCase, 'Admin Authority');
      } else if (type === 'excel') {
        downloadService.exportGrievancesExcel([selectedCase], `Audit_Record_${selectedCase.id}.xlsx`);
      } else if (type === 'snapshot') {
        await downloadService.captureSnapshot('admin-case-card', `Admin_Snapshot_${selectedCase.id}.png`);
      }
    } catch (error) {
      console.error('Export failed', error);
    } finally {
      setExportingType(null);
      setShowExportModal(false);
    }
  };

  return (
    <div className="bg-[#f8fafc] min-h-screen pb-32 pt-32 animate-fadeIn relative">
      {/* PROFESSIONAL EXPORT MODAL */}
      {showExportModal && selectedCase && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowExportModal(false)}></div>
          <div className="bg-white rounded-[3rem] p-10 max-w-md w-full relative z-10 shadow-2xl animate-slideUp">
             <div className="flex justify-between items-center mb-8">
                <h3 className="text-xl font-black text-slate-900">Admin Audit Export</h3>
                <button onClick={() => setShowExportModal(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                  <X size={20} />
                </button>
             </div>

             <div className="space-y-4">
                <button 
                  onClick={() => handleCaseExport('pdf')}
                  disabled={!!exportingType}
                  className="w-full p-6 bg-slate-50 hover:bg-blue-50 border-2 border-transparent hover:border-blue-100 rounded-3xl flex items-center gap-6 transition-all group"
                >
                  <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-blue-600 shadow-sm group-hover:bg-blue-600 group-hover:text-white transition-all">
                    {exportingType === 'pdf' ? <Loader2 className="animate-spin" /> : <FileText size={24} />}
                  </div>
                  <div className="text-left">
                    <p className="font-black text-slate-900">Official PDF Audit</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Internal verification standard</p>
                  </div>
                </button>

                <button 
                  onClick={() => handleCaseExport('excel')}
                  disabled={!!exportingType}
                  className="w-full p-6 bg-slate-50 hover:bg-emerald-50 border-2 border-transparent hover:border-emerald-100 rounded-3xl flex items-center gap-6 transition-all group"
                >
                  <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-emerald-600 shadow-sm group-hover:bg-emerald-600 group-hover:text-white transition-all">
                    {exportingType === 'excel' ? <Loader2 className="animate-spin" /> : <FileSpreadsheet size={24} />}
                  </div>
                  <div className="text-left">
                    <p className="font-black text-slate-900">Excel Data Sheet</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Sortable database record</p>
                  </div>
                </button>

                <button 
                  onClick={() => handleCaseExport('snapshot')}
                  disabled={!!exportingType}
                  className="w-full p-6 bg-slate-50 hover:bg-indigo-50 border-2 border-transparent hover:border-indigo-100 rounded-3xl flex items-center gap-6 transition-all group"
                >
                  <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm group-hover:bg-indigo-600 group-hover:text-white transition-all">
                    {exportingType === 'snapshot' ? <Loader2 className="animate-spin" /> : <ImageIcon size={24} />}
                  </div>
                  <div className="text-left">
                    <p className="font-black text-slate-900">Health UI Snapshot</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Visual capture for logs</p>
                  </div>
                </button>
             </div>
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-4">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-10 mb-16">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 bg-slate-900 text-white rounded-lg text-[10px] font-black uppercase tracking-widest mb-4 shadow-xl">
              <ShieldCheck size={12} className="text-emerald-400" /> Municipal Command OS
            </div>
            <h1 className="text-5xl font-black text-slate-900 tracking-tight">Oversight Console</h1>
            <p className="text-xl text-slate-400 font-medium mt-2">Managing the city's proprietary ResolveChain™.</p>
          </div>
          <div className="flex flex-wrap items-center gap-4">
            <button 
              onClick={handleGlobalExport}
              disabled={isExporting}
              className="bg-white text-slate-900 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 hover:bg-slate-50 border border-slate-200 transition-all shadow-xl"
            >
              {isExporting ? <Loader2 className="animate-spin" size={18} /> : <FileSpreadsheet size={18} />}
              Export City Ledger
            </button>
            <button 
              onClick={runSmartRoute}
              disabled={optimizingRoute}
              className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 hover:bg-blue-700 transition-all shadow-xl shadow-blue-600/20 disabled:opacity-50"
            >
              {optimizingRoute ? <Loader2 className="animate-spin" size={18} /> : <Navigation size={18} />}
              Generate SmartRoute™
            </button>
            <div className="flex items-center gap-6 bg-white p-3 rounded-[2.5rem] shadow-xl border border-slate-100">
               {stats.map((s, i) => (
                 <div key={i} className={`flex items-center gap-4 px-6 ${i !== 0 ? 'border-l border-slate-100' : ''}`}>
                    <div className={`${s.color} p-2 bg-slate-50 rounded-xl`}>{s.icon}</div>
                    <div>
                      <span className="block text-[9px] font-black text-slate-400 uppercase tracking-widest">{s.label}</span>
                      <span className="text-xl font-black text-slate-900">{s.val}</span>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        </div>

        {routePlan && (
          <div className="mb-16 bg-emerald-900 text-white p-12 rounded-[4rem] shadow-2xl animate-slideUp relative overflow-hidden">
             <div className="absolute top-0 right-0 p-8">
               <button onClick={() => setRoutePlan(null)} className="text-white/40 hover:text-white"><X size={24}/></button>
             </div>
             <h3 className="text-3xl font-black mb-8 flex items-center gap-4">
                <Navigation className="text-emerald-400" size={32} /> SmartRoute™ Optimized Dispatch
             </h3>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {routePlan.map((p, idx) => (
                  <div key={p.id} className="bg-white/5 border border-white/10 p-6 rounded-3xl backdrop-blur-md">
                     <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest block mb-2">Stop #{idx+1} • {p.dnaSignature || 'LEGACY'}</span>
                     <p className="font-black text-lg mb-2">{p.title}</p>
                     <p className="text-xs text-white/60 line-clamp-2">{p.location?.address || 'Location Unavailable'}</p>
                  </div>
                ))}
             </div>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          <div className="lg:col-span-8 space-y-8">
             <div className="relative mb-8">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={24} />
                <input 
                  type="text" 
                  placeholder="Scan IssueDNA™ or Case ID..."
                  className="w-full pl-16 pr-8 py-6 rounded-[2.5rem] bg-white border-2 border-transparent focus:border-blue-500 shadow-2xl outline-none font-bold text-lg transition-all"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
             </div>

             <div className="bg-white rounded-[3.5rem] border border-slate-50 shadow-2xl overflow-hidden">
                <table className="w-full text-left">
                  <thead>
                    <tr className="bg-slate-50/50 border-b border-slate-100">
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400">IssueDNA™ Identity</th>
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400">Category</th>
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {filtered.map(g => (
                      <tr 
                        key={g.id} 
                        className={`hover:bg-blue-50/20 cursor-pointer transition-colors group ${selectedCase?.id === g.id ? 'bg-blue-50/80' : ''}`}
                        onClick={() => setSelectedCase(g)}
                      >
                        <td className="px-10 py-8">
                           <span className="text-blue-600 font-black text-[10px] uppercase tracking-widest block mb-1">{g.dnaSignature || 'LEGACY-SIG'}</span>
                           <h4 className="font-black text-slate-900 text-lg group-hover:text-blue-700 transition-colors">{g.title}</h4>
                        </td>
                        <td className="px-10 py-8">
                           <span className="px-4 py-2 bg-slate-100 rounded-xl text-[10px] font-black text-slate-500 uppercase tracking-widest">{g.category}</span>
                        </td>
                        <td className="px-10 py-8 text-right">
                           <div className={`inline-flex px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm ${g.status === IssueStatus.RESOLVED ? 'bg-emerald-600 text-white' : 'bg-slate-900 text-white'}`}>
                              {g.status}
                           </div>
                        </td>
                      </tr>
                    ))}
                    {filtered.length === 0 && (
                      <tr>
                        <td colSpan={3} className="px-10 py-20 text-center text-slate-400 font-bold">No matching records found in Command OS.</td>
                      </tr>
                    )}
                  </tbody>
                </table>
             </div>
          </div>

          <div className="lg:col-span-4">
             {selectedCase ? (
               <div id="admin-case-card" className="bg-white rounded-[4rem] border border-slate-50 shadow-2xl p-12 sticky top-32 animate-slideUp">
                  <div className="flex justify-between items-center mb-8">
                    <h3 className="text-3xl font-black leading-tight text-slate-900">{selectedCase.title}</h3>
                    <div className="flex gap-2">
                       <button onClick={() => setShowExportModal(true)} className="p-2 text-slate-400 hover:text-blue-600 transition-colors" title="Export Audit Record"><Download size={20}/></button>
                       <button onClick={() => setSelectedCase(null)} className="p-2 text-slate-300 hover:text-slate-900 transition-colors"><X size={24}/></button>
                    </div>
                  </div>

                  <div className="space-y-8">
                    <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Technical Summary</p>
                      <div className="flex flex-wrap gap-2">
                        <span className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[9px] font-black">{selectedCase.id}</span>
                        <span className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[9px] font-black">{selectedCase.dnaSignature}</span>
                      </div>
                    </div>

                    <div className="space-y-4">
                      <p className="text-[10px] font-black uppercase text-slate-400 mb-4 ml-4 tracking-widest">ResolveChain™ Append Status</p>
                      <div className="grid grid-cols-2 gap-4">
                        {Object.values(IssueStatus).map(status => (
                          <button 
                            key={status}
                            onClick={() => {
                              if (selectedCase) {
                                onUpdateStatus(selectedCase.id, status);
                                setSelectedCase(null);
                              }
                            }}
                            className={`py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${selectedCase.status === status ? 'bg-blue-600 text-white shadow-xl' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
                          >
                            {status}
                          </button>
                        ))}
                      </div>
                    </div>

                    <div className="pt-6 border-t border-slate-100">
                       <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Internal Actions</h4>
                       <button 
                         onClick={() => setShowExportModal(true)}
                         className="w-full py-5 rounded-[2rem] bg-slate-900 text-white font-black text-xs uppercase tracking-widest hover:bg-black transition-all flex items-center justify-center gap-3"
                       >
                         <Download size={16} /> Audit Export Options
                       </button>
                    </div>
                  </div>
               </div>
             ) : (
               <div className="bg-slate-50 border-4 border-dashed border-slate-100 rounded-[4rem] p-20 text-center flex flex-col items-center justify-center min-h-[600px]">
                 <Inbox size={64} className="text-slate-100 mb-8" />
